window.applyPermissions = function() {
    if (!window.sessionUser) return;
    
    // 1. 👑 OWNER / MASTER KEY ACCESS
    if (window.sessionUser.isOwner) {
        document.querySelectorAll('.nav-item').forEach(el => el.style.display = 'block');
        return;
    }
    
    // 2. 🤝 FRANCHISEE ISOLATION PROTOCOL (THE WALLED GARDEN)
    if (window.sessionUser.isFranchisee) {
        // Hide EVERYTHING first
        document.querySelectorAll('.nav-item').forEach(el => el.style.display = 'none');
        
        // Expose ONLY the safe operational tabs
        const allowedTabs = [
            'dashboard', 'accounts', 'financial-flow', 'transfers', 
            'devices', 'payroll', 'inbox', 'dispatch', 'zreadings', 
            'history', 'expenses', 'branches', 'sop', 'equipment', 
            'inventory', 'alerts', 'bulletin', 'franchise-hub'
        ];
        
        allowedTabs.forEach(tab => {
            let el = document.getElementById('nav-' + tab);
            if (el) el.style.display = 'flex'; // Use flex to preserve your sidebar icon layouts!
        });

        // 🛑 UI MORPHING: Hide HQ-Specific Metrics from Franchisees
        setTimeout(() => {
            // Hide HQ Bank Cash on Cash Flow & Accounts Tabs
            let safeCashCards = document.querySelectorAll('#hubSafeCash');
            safeCashCards.forEach(c => { if(c.parentElement) c.parentElement.style.display = 'none'; });
            
            // Hide the "Publish Announcement" boxes on the Bulletin Board
            let publisherDiv = document.getElementById('announceTitle')?.parentElement;
            if (publisherDiv) publisherDiv.style.display = 'none';
            let aiPromptDiv = document.getElementById('aiRoughIdea')?.parentElement;
            if (aiPromptDiv) aiPromptDiv.style.display = 'none';
        }, 1000);

        return;
    }
    
    // 3. 👔 STANDARD MANAGER ACCESS
    document.querySelectorAll('.nav-item').forEach(el => {
        if (el.id !== 'nav-dashboard') el.style.display = 'none';
    });
    
    window.sessionUser.permissions.forEach(tabName => {
        let el = document.getElementById('nav-' + tabName);
        if (el) el.style.display = 'flex';
    });

    let adminEl = document.getElementById('nav-admin');
    if (adminEl) adminEl.style.display = 'none'; 
};

// ========================================================
// ⚡ FAST PIN SECURITY ENGINE
// ========================================================
window.tempAuthUser = null;
window.tempAuthData = null;

onAuthStateChanged(auth, async (user) => {
  const loginOverlay = document.getElementById('loginOverlay');
  const stage1 = document.getElementById('loginStage1');
  const stage2 = document.getElementById('loginStage2');
  
  if (user) {
    let isAuthorized = false;
    let userData = null;
    let docId = null;

    try {
        if (user.email === MASTER_EMAIL) {
            const q = window.query(window.collection(window.db, "hq_managers"), window.where("email", "==", user.email));
            const snap = await window.getDocs(q);
            if (snap.empty) {
                const newDoc = await window.addDoc(window.collection(window.db, "hq_managers"), {
                    email: user.email, role: 'Owner', permissions: ['all'], assignedBranch: 'All', pin: '0319'
                });
                docId = newDoc.id;
                userData = { pin: '0319', permissions: ['all'], role: 'Owner', assignedBranch: 'All' };
            } else {
                docId = snap.docs[0].id;
                userData = snap.docs[0].data();
            }
            isAuthorized = true;
        } else {
            const q = window.query(window.collection(window.db, "hq_managers"), window.where("email", "==", user.email));
            const snap = await window.getDocs(q);
            if (!snap.empty) {
                docId = snap.docs[0].id;
                userData = snap.docs[0].data();
                isAuthorized = true;
            }
        }
    } catch (e) { console.error(e); }

    if (isAuthorized) {
        if (!userData.pin) {
            userData.pin = '1234'; 
            await window.updateDoc(window.doc(window.db, "hq_managers", docId), { pin: '1234' });
        }
        
        window.tempAuthUser = user;
        window.tempAuthData = userData;
        window.tempAuthData.docId = docId;

        document.getElementById('authWelcomeName').innerText = `${userData.role}: ${user.displayName || 'Authorized'}`;
        stage1.style.display = 'none';
        stage2.style.display = 'block';
        loginOverlay.style.display = 'flex';
        
        setTimeout(() => {
            let pinBox = document.getElementById('managerPinInput');
            if(pinBox) pinBox.focus();
        }, 300);

    } else {
        await signOut(auth);
        if(typeof Swal !== 'undefined') Swal.fire('Clearance Denied', 'Your Google Account is not authorized.', 'error');
        loginOverlay.style.display = 'flex';
        stage1.style.display = 'block';
        stage2.style.display = 'none';
    }
  } else {
    if (loginOverlay) {
        loginOverlay.style.display = 'flex';
        stage1.style.display = 'block';
        stage2.style.display = 'none';
    }
  }
});

window.checkManagerPin = function() {
    let pinInput = document.getElementById('managerPinInput');
    let pinVal = pinInput.value.trim();
    let err = document.getElementById('pinErrorMsg');
    
    // Check if it is at least 4 characters
    if (pinVal.length >= 4) {
        if (pinVal === window.tempAuthData.pin) {
            pinInput.value = '';
            pinInput.style.borderColor = '#cbd5e1';
            err.style.display = 'none';
            window.finalizeManagerLogin();
        } else {
            err.innerText = '❌ ACCESS DENIED. INVALID PIN.';
            err.style.display = 'block';
            pinInput.value = '';
            pinInput.style.borderColor = '#ef4444';
            pinInput.focus();
        }
    } else {
        err.innerText = '❌ PIN must be at least 4 characters long.';
        err.style.display = 'block';
        pinInput.style.borderColor = '#ef4444';
        pinInput.focus();
    }
};

window.cancelLoginAndSignOut = async function() {
    await signOut(auth);
    window.tempAuthUser = null;
    window.tempAuthData = null;
    let pinBox = document.getElementById('managerPinInput');
    if (pinBox) {
        pinBox.value = '';
        pinBox.style.borderColor = '#cbd5e1';
    }
    document.getElementById('pinErrorMsg').style.display = 'none';
};

// ==========================================
// 👑 FRANCHISEE DATA ISOLATION ENGINE
// ==========================================
window.isBranchAllowed = function(branchName) {
    if (!window.sessionUser || window.sessionUser.isOwner || !window.sessionUser.isFranchisee) return true;
    return window.sessionUser.allowedBranches.includes(branchName);
};

window.finalizeManagerLogin = function() {
    let isFranchisee = window.tempAuthData.role === 'Franchisee';
    let branchStr = window.tempAuthData.assignedBranch || 'Main Office';
    
    // 🔥 Supports Multi-Branch Franchisees (e.g., "Pampanga, Pampanga 2")
    let allowedArr = branchStr.split(',').map(b => b.trim());

    // 🔥 THE CRASH FIX: Safely fallback to a default array if permissions are missing in Firebase!
    let safePermissions = window.tempAuthData.permissions || ['all'];

    window.sessionUser = {
        email: window.tempAuthUser.email,
        branch: allowedArr[0], 
        allowedBranches: allowedArr, 
        isFranchisee: isFranchisee,
        cashierName: window.tempAuthUser.displayName || window.tempAuthData.fullName || window.tempAuthData.name || 'Manager',
        isOwner: (window.tempAuthUser.email === MASTER_EMAIL || (!isFranchisee && safePermissions.includes('all'))),
        permissions: safePermissions
    };

    // 🎨 DYNAMIC UI BRANDING
    let logoTxt = document.getElementById('sidebarLogoBranchText');
    if (logoTxt) logoTxt.innerText = isFranchisee ? allowedArr.join(' & ').toUpperCase() : "MAIN OFFICE";
    
    let profName = document.getElementById('sidebarProfileName');
    if (profName) profName.innerText = window.sessionUser.cashierName;
    
    let profRole = document.getElementById('sidebarProfileRole');
    if (profRole) profRole.innerText = isFranchisee ? "Franchise Owner" : "Admin Access";

    let overlay = document.getElementById('loginOverlay');
    if (overlay) overlay.style.display = 'none';
    
    if (typeof window.applyPermissions === 'function') window.applyPermissions();
    if (typeof window.applyFranchiseUIProtections === 'function') window.applyFranchiseUIProtections(); 
    if (typeof window.switchView === 'function') window.switchView('dashboard');
    if (typeof window.loadGlobalDashboard === 'function') window.loadGlobalDashboard();
};

// 🔥 THE BULLETPROOF GOOGLE LOGIN FIX FOR iOS/IPHONE
window.loginWithGoogle = async function() {
  try {
    // Show loading state so you know it was clicked
    let btn = document.querySelector('#loginStage1 button');
    let oldHtml = btn.innerHTML;
    btn.innerHTML = '⏳ Securely connecting...';
    btn.disabled = true;

    provider.setCustomParameters({ prompt: 'select_account' });
    
    // Apple ITP blocks redirects, but Popup works flawlessly via secure overlay
    await signInWithPopup(auth, provider);
    
  } catch (error) {
    console.error("Login Trigger Error:", error);
    let btn = document.querySelector('#loginStage1 button');
    if (btn) {
        btn.innerHTML = '<img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" style="width: 20px; height: 20px;"> Sign in with Google';
        btn.disabled = false;
    }
    // Ignore harmless popup closures, alert true errors
    if (error.code !== 'auth/popup-closed-by-user' && error.code !== 'auth/cancelled-popup-request') {
        if(typeof Swal !== 'undefined') Swal.fire("Login failed", error.message, "error");
    }
  }
};

