// Run the radar the moment the page loads
document.addEventListener("DOMContentLoaded", () => {
    if (typeof window.setDefaultCutoffDates === 'function') { try { window.setDefaultCutoffDates(); } catch(e) {} }
});

  // Wire up the Refresh Button
