window.loadGroupedRestocks = async function() {
    const tbody = document.getElementById('invoicesTableBody');
    if (!tbody) return;
    
    tbody.innerHTML = '<tr><td colspan="5" class="text-center" style="padding: 40px; color: #0ea5e9; font-weight: bold;">⏳ Fetching HQ Restock Invoices...</td></tr>';
    
    try {
        const q = window.query(window.collection(window.db, "hq_restocks"), window.orderBy("timestamp", "desc"));
        const snap = await window.getDocs(q);
        
        let html = '';

        if (snap.empty) {
            html = `<tr><td colspan="5" style="text-align:center; padding: 40px; color: #64748b; font-weight: bold;">No restock invoices found in the system.</td></tr>`;
        } else {
            snap.forEach(docSnap => {
                let d = docSnap.data();
                let dateStr = d.timestamp?.toDate ? d.timestamp.toDate().toLocaleString('en-US', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : 'Unknown';
                
                let cost = parseFloat(d.totalCost) || 0;

                // 🔥 THE FIX: Sub-columns for Items - Qty - Subtotal inside the invoice row!
                let itemsList = `<table style="width:100%; border-collapse:collapse; font-size:12px; margin-top:5px; background: white; border: 1px solid #e2e8f0; border-radius: 6px; overflow: hidden;">`;
                (d.items || []).forEach(i => {
                    let sub = parseFloat(i.subtotal) || 0;
                    itemsList += `
                        <tr style="border-bottom:1px dashed #e2e8f0;">
                            <td style="padding: 6px 10px; font-weight:bold; color:#334155; width: 60%;">${i.name}</td>
                            <td style="padding: 6px 10px; color:#64748b; text-align:center; width: 20%;">${i.purchQty || i.qty} ${i.purchUom || 'units'}</td>
                            <td style="padding: 6px 10px; text-align:right; font-weight:bold; color:#0ea5e9; width: 20%;">₱${sub.toLocaleString(undefined, {minimumFractionDigits:2})}</td>
                        </tr>`;
                });
                itemsList += `</table>`;
                
                let encodedData = encodeURIComponent(JSON.stringify({id: docSnap.id, ...d}));

                html += `
                    <tr style="border-bottom: 1px solid #e2e8f0; transition: background 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='white'">
                        <td style="padding: 15px; vertical-align: top;">
                            <strong style="color: #0f172a; font-size: 13px;">${dateStr}</strong><br>
                            <span style="color:#64748b; font-size: 11px; font-weight: bold;">👤 ${d.user || 'Admin'}</span>
                        </td>
                        <td style="padding: 15px; font-weight: 900; color: #0ea5e9; font-size: 13px; vertical-align: top;">${d.supplier || 'HQ Restock'}</td>
                        <td style="padding: 15px; font-weight: 900; color: #dc2626; font-size: 16px; vertical-align: top;">₱${cost.toLocaleString(undefined, {minimumFractionDigits:2})}</td>
                        <td style="padding: 15px; vertical-align: top;">${itemsList}</td>
                        <td style="padding: 15px; text-align: right; vertical-align: top;">
                            <button onclick="window.revertAndEditRestock('${encodedData}')" style="background: white; color: #f59e0b; border: 1px solid #fcd34d; padding: 8px 12px; border-radius: 6px; font-weight: 900; cursor: pointer; font-size: 11px; white-space: nowrap; box-shadow: 0 1px 2px rgba(245, 158, 11, 0.1); transition: 0.2s;" onmouseover="this.style.background='#fffbeb'" onmouseout="this.style.background='white'">↩️ Revert & Edit</button>
                        </td>
                    </tr>
                `;
            });
        }

        tbody.innerHTML = html;
        window.updateLifetimeRestockCost(); 

    } catch(e) {
        console.error(e); 
        tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding: 40px; color: #ef4444; font-weight: bold;">Failed to load invoices. Check internet connection.</td></tr>`;
    }
};

window.revertAndEditRestock = async function(encodedData) {
    let invoice = JSON.parse(decodeURIComponent(encodedData));

    let confirm = await Swal.fire({
        title: 'Revert & Edit?',
        text: 'This will undo the stock additions from this invoice and load the items back into your cart so you can fix them. Proceed?',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#f59e0b',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Yes, Revert it!',
        customClass: { popup: 'rounded-2xl shadow-xl' }
    });

    if (!confirm.isConfirmed) return;

    Swal.fire({title: 'Reverting Stock...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        for (let item of invoice.items) {
            
            // 🛡️ THE FALLBACK FIX: Hunt down the item even if it's missing its ID!
            let docRef;
            if (item.id) {
                docRef = window.doc(window.db, "inventory", item.id);
            } else {
                let itemName = item.name || item.itemName;
                const invQ = window.query(window.collection(window.db, "inventory"), window.where("name", "==", itemName), window.where("branch", "==", "Main Office"));
                const invSnap = await window.getDocs(invQ);
                if (!invSnap.empty) docRef = invSnap.docs[0].ref;
            }

            if (docRef) {
                let snap = await window.getDoc(docRef);
                if (snap.exists()) {
                    let data = snap.data();
                    let oldQty = parseFloat(data.currentStock || 0);
                    
                    // Safely extract the amount that was originally added
                    let itemPurchQty = parseFloat(item.purchQty) || parseFloat(item.qty) || 0;
                    let convRate = parseFloat(item.conversionRate || data.conversionRate || data.conversion || 1);
                    let subBaseQty = parseFloat(item.baseQtyToAdd) || (itemPurchQty * convRate);
                    
                    let newQty = oldQty - subBaseQty;

                    // Reverse the math!
                    await window.updateDoc(docRef, { currentStock: newQty });

                    await window.addDoc(window.collection(window.db, "stock_logs"), {
                        branch: "Main Office",
                        item: item.name || item.itemName,
                        oldQty: oldQty,
                        newQty: newQty,
                        variance: -subBaseQty,
                        uom: data.uom || 'units',
                        type: "HQ Restock Reverted (Edit)",
                        note: `Invoice undone by ${localStorage.getItem('cashierName') || 'Manager'}`,
                        user: localStorage.getItem('cashierName') || 'Manager',
                        timestamp: new Date()
                    });
                }
            }
        }

        // Delete the grouped invoice document
        await window.deleteDoc(window.doc(window.db, "hq_restocks", invoice.id));

        // Load the items back into the cart UI so the manager can fix them
        window.restockCart = invoice.items;
        document.getElementById('restockSupplierInput').value = invoice.supplier || '';
        document.getElementById('restockCostInput').value = invoice.totalCost || '';

        Swal.close();
        document.getElementById('restockModal').style.display = 'flex';
        
        if (typeof window.renderRestockCart === 'function') window.renderRestockCart();
        if (typeof window.loadInventoryData === 'function') window.loadInventoryData();
        if (typeof window.loadStockLogs === 'function') window.loadStockLogs();
        if (typeof window.updateLifetimeRestockCost === 'function') window.updateLifetimeRestockCost();

        Swal.fire({ toast: true, position: 'top-end', icon: 'success', title: 'Restock Reverted! Edit your cart now.', showConfirmButton: false, timer: 3000 });

    } catch (e) {
        console.error("Revert Error:", e);
        Swal.fire('Error', 'Failed to revert stock safely. ' + e.message, 'error');
    }
};

// 🔥 TABS FOR PREP AND STOCK HISTORY 🔥
window.activePrepBranch = 'All';
window.switchPrepBranch = function(branch) {
    window.activePrepBranch = branch;
    window.loadPrepBatchLogs();
};

window.loadPrepBatchLogs = async function() {
    const tbody = document.getElementById('prepBatchLogsBody');
    const tabContainer = document.getElementById('prepBranchTabs');
    if (!tbody || !tabContainer) return;
    
    // Inject Branch Tabs!
    let branches = window.globalActiveBranches ? window.globalActiveBranches.filter(b => b !== "Main Office") : ["Cabantian", "Citygate", "Maa"];
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;
    if (isFranchisee) branches = [window.sessionUser.branch];

    let allActive = window.activePrepBranch === 'All';
    let bHtml = `<div onclick="window.switchPrepBranch('All')" style="min-width: 120px; background: ${allActive ? '#f3e8ff' : 'white'}; border: 2px solid ${allActive ? '#a855f7' : '#e2e8f0'}; padding: 10px; border-radius: 8px; cursor: pointer; text-align: center; font-weight: bold; font-size: 13px; color: ${allActive ? '#7e22ce' : '#64748b'}; transition: 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.02);">🌐 All Branches</div>`;
    
    if (isFranchisee) {
        bHtml = ''; 
        window.activePrepBranch = window.sessionUser.branch;
    }

    branches.forEach(b => {
        let isAct = window.activePrepBranch === b;
        bHtml += `<div onclick="window.switchPrepBranch('${b}')" style="min-width: 120px; background: ${isAct ? '#f3e8ff' : 'white'}; border: 2px solid ${isAct ? '#a855f7' : '#e2e8f0'}; padding: 10px; border-radius: 8px; cursor: pointer; text-align: center; font-weight: bold; font-size: 13px; color: ${isAct ? '#7e22ce' : '#64748b'}; transition: 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.02);">📍 ${b}</div>`;
    });
    tabContainer.innerHTML = bHtml;

    // 🔥 INJECT DATE FILTER DYNAMICALLY 🔥
    let headerDiv = tabContainer.parentElement;
    if (headerDiv && !document.getElementById('prepDateFilterContainer')) {
        let filterHtml = `
            <div id="prepDateFilterContainer" style="display: flex; gap: 10px; align-items: center; margin-left: auto; margin-right: 15px;">
                <input type="date" id="prepDateFilter" onchange="window.loadPrepBatchLogs()" style="padding: 10px 15px; border-radius: 8px; border: 1px solid #cbd5e1; outline: none; font-weight: bold; color: #8b5cf6; font-size: 13px; background: white;" title="Filter by Date">
                <button onclick="document.getElementById('prepDateFilter').value=''; window.loadPrepBatchLogs();" style="background: #f8fafc; border: 1px solid #cbd5e1; padding: 10px 15px; border-radius: 8px; font-weight: bold; color: #475569; font-size: 13px; cursor: pointer; transition: 0.2s;">Clear</button>
            </div>
        `;
        let refreshBtn = headerDiv.querySelector('.btn-refresh');
        if (refreshBtn) {
            refreshBtn.insertAdjacentHTML('beforebegin', filterHtml);
        }
    }

    tbody.innerHTML = '<tr><td colspan="6" class="text-center" style="padding: 40px; color: #8b5cf6; font-weight: bold;">Loading prep history...</td></tr>';
    
    let dateFilterEl = document.getElementById('prepDateFilter');
    let selectedDate = dateFilterEl ? dateFilterEl.value : "";

    try {
        let q;
        if (selectedDate) {
            let startOfDay = new Date(selectedDate + 'T00:00:00');
            let endOfDay = new Date(selectedDate + 'T23:59:59');
            q = window.query(window.collection(window.db, "stock_logs"), 
                window.where("type", "in", ["Manager Prep Batch", "End-of-Shift Kitchen Prep"]), 
                window.where("timestamp", ">=", startOfDay), 
                window.where("timestamp", "<=", endOfDay), 
                window.orderBy("timestamp", "desc")
            );
        } else {
            q = window.query(window.collection(window.db, "stock_logs"), 
                window.where("type", "in", ["Manager Prep Batch", "End-of-Shift Kitchen Prep"]), 
                window.orderBy("timestamp", "desc"), 
                window.limit(100) // Increased limit so you can see more shifts!
            );
        }

        const snap = await window.getDocs(q);
        
        let logs = [];
        snap.forEach(doc => {
            let d = doc.data();
            if (window.activePrepBranch !== "All" && d.branch !== window.activePrepBranch) return;
            logs.push({ id: doc.id, ...d });
        });

        logs.sort((a,b) => b.timestamp - a.timestamp); // Newest first

        let html = '';
        let currentShiftGroup = '';

        logs.forEach(log => {
            let timeObj = log.timestamp ? log.timestamp.toDate() : new Date();
            let timeStr = timeObj.toLocaleTimeString('en-PH', {hour: '2-digit', minute:'2-digit'});
            let dateStr = timeObj.toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
            let pUom = log.purchUom || 'Batch';
            let pQty = log.purchQty ? log.purchQty : '-';
            let purchDisplay = log.purchQty ? `(${pQty} ${pUom}s)` : '';
            let staffName = log.user || log.cashier || 'System';

            // 🔥 GROUP BY DATE AND CASHIER (THE SHIFT DIVIDER) 🔥
            let shiftKey = `${dateStr}_${staffName}`;

            if (shiftKey !== currentShiftGroup) {
                html += `
                    <tr>
                        <td colspan="6" style="background: #f3e8ff; padding: 12px 15px; font-weight: 900; color: #6d28d9; text-transform: uppercase; font-size: 13px; letter-spacing: 1px; border-bottom: 2px solid #d8b4fe; border-top: 2px solid #d8b4fe;">
                            📅 ${dateStr} &nbsp;&nbsp;|&nbsp;&nbsp; 🧑‍🍳 Shift: ${staffName}
                        </td>
                    </tr>
                `;
                currentShiftGroup = shiftKey;
            }

            html += `
                <tr style="border-bottom: 1px solid #f1f5f9; transition: background 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='white'">
                    <td style="padding: 12px 15px; color: #64748b; font-size: 12px; padding-left: 25px;">${timeStr}</td>
                    <td style="padding: 12px 15px;"><span class="badge badge-open">${log.branch}</span></td>
                    <td style="padding: 12px 15px; font-weight: bold; color: #334155;">👤 ${staffName}</td>
                    <td style="padding: 12px 15px; font-weight: bold; color: #8b5cf6;">${log.item}</td>
                    <td style="padding: 12px 15px;">
                        <strong style="color: #10b981; font-size: 15px;">+${log.variance} ${log.uom}</strong><br>
                        <span style="color: #0ea5e9; font-size: 11px; font-weight: bold;">${purchDisplay}</span>
                    </td>
                    <td style="padding: 12px 15px;">
                        <button onclick="window.undoKitchenPrep('${log.id}', '${log.item.replace(/'/g, "\\'")}', ${log.variance})" style="background: white; color: #dc2626; border: 1px solid #fecaca; padding: 6px 12px; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 11px; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">✖ Undo</button>
                    </td>
                </tr>
            `;
        });

        tbody.innerHTML = html || '<tr><td colspan="6" style="text-align:center; padding: 40px; color: #94a3b8; font-weight: bold;">No prep batches logged for this filter.</td></tr>';
    } catch(e) {
        console.error(e);
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; color: #dc2626; padding: 40px; font-weight: bold;">Error loading history.</td></tr>';
    }
};

window.activeStockLogBranch = 'All';
window.switchStockLogBranch = function(branch) {
    window.activeStockLogBranch = branch;
    window.loadStockLogs();
};

window.loadStockLogs = async function() {
  const tbody = document.getElementById('stockLogsBody');
  const tabContainer = document.getElementById('stockLogBranchTabs');
  if (!tbody || !tabContainer) return;

  // Inject Branch Tabs!
  let branches = window.globalActiveBranches ? window.globalActiveBranches : ["Main Office", "Cabantian", "Citygate", "Maa"];
  let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;
  if (isFranchisee) branches = [window.sessionUser.branch];

  let allActive = window.activeStockLogBranch === 'All';
  let bHtml = `<div onclick="window.switchStockLogBranch('All')" style="min-width: 120px; background: ${allActive ? '#e0f2fe' : 'white'}; border: 2px solid ${allActive ? '#0ea5e9' : '#e2e8f0'}; padding: 10px; border-radius: 8px; cursor: pointer; text-align: center; font-weight: bold; font-size: 13px; color: ${allActive ? '#0284c7' : '#64748b'}; transition: 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.02);">🌐 All Branches</div>`;
  
  if (isFranchisee) {
      bHtml = ''; 
      window.activeStockLogBranch = window.sessionUser.branch;
  }

  branches.forEach(b => {
      let isAct = window.activeStockLogBranch === b;
      bHtml += `<div onclick="window.switchStockLogBranch('${b}')" style="min-width: 120px; background: ${isAct ? '#e0f2fe' : 'white'}; border: 2px solid ${isAct ? '#0ea5e9' : '#e2e8f0'}; padding: 10px; border-radius: 8px; cursor: pointer; text-align: center; font-weight: bold; font-size: 13px; color: ${isAct ? '#0284c7' : '#64748b'}; transition: 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.02);">📍 ${b}</div>`;
  });
  tabContainer.innerHTML = bHtml;

  tbody.innerHTML = '<tr><td colspan="7" class="text-center" style="padding: 40px; color: #0ea5e9; font-weight: bold;">Loading history...</td></tr>';

  try {
    const qLogs = window.query(window.collection(window.db, "stock_logs"), window.orderBy("timestamp", "desc"), window.limit(100));
    const snap = await window.getDocs(qLogs);
    let html = '';

    snap.forEach(doc => {
      let data = doc.data();
      if (window.activeStockLogBranch !== "All" && data.branch !== window.activeStockLogBranch) return;

      let dateStr = data.timestamp ? data.timestamp.toDate().toLocaleString('en-PH', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'Just now';

      let user = data.user || data.cashier || "System";
      let uom = data.uom || "";
      let oldQty = data.oldQty !== undefined ? data.oldQty : "-";
      let newQty = data.newQty !== undefined ? data.newQty : "-";
      let logType = data.type || "System Update";

      let varHtml = '';
      if (data.variance > 0) {
          varHtml = `<span style="color: #16a34a; font-weight: 900; font-size: 15px;">+${data.variance} ${uom} <br><span style="font-size:10px; color:#64748b; font-weight: bold;">(${logType})</span></span>`;
      } else if (data.variance < 0) {
          varHtml = `<span style="color: #dc2626; font-weight: 900; font-size: 15px;">${data.variance} ${uom} <br><span style="font-size:10px; color:#64748b; font-weight: bold;">(${logType})</span></span>`;
      } else {
          varHtml = `<span style="color: #94a3b8; font-weight: bold; font-size: 13px;">No Change <br><span style="font-size:10px; color:#64748b;">(${logType})</span></span>`;
      }

      html += `
        <tr style="border-bottom: 1px solid #f1f5f9; transition: background 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='white'">
          <td style="font-size: 12px; color: #64748b; padding: 15px 20px;">${dateStr}</td>
          <td style="padding: 15px 20px;"><span class="badge badge-open">${data.branch || 'Unknown'}</span></td>
          <td style="font-weight: bold; color: #334155; padding: 15px 20px;">👤 ${user}</td>
          <td style="font-weight: 900; color: #0f172a; padding: 15px 20px;">${data.item || 'Unknown Item'}</td>
          <td style="color: #64748b; padding: 15px 20px; font-weight: bold;">${oldQty} <span style="font-size:11px; font-weight:normal;">${uom}</span></td>
          <td style="font-weight: 900; color: #0284c7; padding: 15px 20px;">${newQty} <span style="font-size:11px; font-weight:normal;">${uom}</span></td>
          <td style="padding: 15px 20px;">${varHtml}</td>
        </tr>
      `;
    });

    tbody.innerHTML = html || '<tr><td colspan="7" class="text-center" style="padding: 40px; color: #64748b; font-weight: bold;">No stock history found.</td></tr>';
  } catch (e) { 
    console.error("Stock Logs Error:", e); 
    tbody.innerHTML = '<tr><td colspan="7" class="text-center" style="color:red; padding: 40px; font-weight: bold;">Error loading logs. Check console.</td></tr>'; 
  }
};

window.activeLogisticsTab = 'Requests'; // Default tab memory

window.loadDispatchLogs = async function() {
    const tbody = document.getElementById('dispatchLogBody');
    if(!tbody) return;
    tbody.innerHTML = '<tr><td colspan="3" class="text-center" style="padding: 20px;">⏳ Loading logistics data...</td></tr>';
    
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;
    let myBranch = window.sessionUser ? window.sessionUser.branch : "Unknown";

    try {
        let poQuery = query(collection(db, "purchase_orders"), where("status", "in", ["Pending", "Drafting", "Delayed"]), orderBy("timestamp", "desc"));
        if (isFranchisee) poQuery = query(collection(db, "purchase_orders"), where("branch", "==", myBranch), where("status", "in", ["Pending", "Drafting", "Delayed"]), orderBy("timestamp", "desc"));
        const poSnap = await getDocs(poQuery);
        
        let poHtml = '';
        let poCount = 0;
        
        poSnap.forEach(docSnap => {
            let po = docSnap.data();
            poCount++;
            let dateStr = po.timestamp ? po.timestamp.toDate().toLocaleString('en-PH', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'Just now';
            
            let isDelayed = po.status === "Delayed" || (po.requestedBy && po.requestedBy.includes("Backlogged"));
            
            let statusBadge = '';
            let titleTxt = '';
            let delayMeta = '';

            if (isDelayed) {
                statusBadge = `<span style="background:#fef2f2; color:#b91c1c; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">⏳ Delayed (HQ Out of Stock)</span>`;
                titleTxt = `⏳ Postponed Delivery to ${po.branch}`;
                
                let origDate = po.originalRequestDate || dateStr.split(',')[0];
                delayMeta = `
                    <div style="margin-top: 8px; padding: 6px; background: #fff; border: 1px dashed #fca5a5; border-radius: 4px; display: inline-block;">
                        <span style="font-size:11px; color:#ef4444; font-weight:bold;">Originally Requested: ${origDate}</span><br>
                        <span style="font-size:10px; color:#64748b;">Set aside by system on: ${dateStr}</span>
                    </div>`;
            } else if (po.status === "Drafting") {
                statusBadge = `<span style="background:#bae6fd; color:#0369a1; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">Drafting in Cart</span>`;
                titleTxt = po.type === 'Internal Request' ? `📢 Stock Issue Report from ${po.branch}` : `📝 Purchase Order from ${po.branch}`;
            } else {
                statusBadge = `<span style="background:#fef3c7; color:#d97706; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">Pending</span>`;
                titleTxt = po.type === 'Internal Request' ? `📢 Stock Issue Report from ${po.branch}` : `📝 Purchase Order from ${po.branch}`;
            }

            let actionBtn = isFranchisee 
                ? `<span style="color:#ca8a04; font-weight:bold; font-size:11px;">⏳ Waiting for HQ</span>`
                : `<button onclick="window.reviewPurchaseOrder('${docSnap.id}')" style="background:#0ea5e9; color:white; border:none; padding:6px 12px; border-radius:6px; font-weight:bold; cursor:pointer; font-size:12px; box-shadow: 0 2px 4px rgba(14,165,233,0.3);">🔍 Review Request</button>`;
            
            poHtml += `<tr style="background:#fffbeb; border-bottom:2px solid #fde68a;">
                <td style="padding:15px;">
                    <div style="font-weight:900; color:#d97706; font-size:15px;">${titleTxt}</div>
                    <div style="font-size:12px; color:#b45309; margin-top: 4px; font-weight:bold;">Requested by: ${po.requestedBy}</div>
                    <div style="font-size:11px; color:#d97706; margin-top:4px;">📅 ${dateStr} • <strong style="font-size:13px;">${po.items.length} items</strong></div>
                    ${delayMeta}
                </td>
                <td style="padding:15px; text-align:center;">${statusBadge}</td>
                <td style="padding:15px; text-align:right;">${actionBtn}</td>
            </tr>`;
        });

        let qLogs = query(collection(db, "dispatch_logs"), orderBy("timestamp", "desc"));
        if (isFranchisee) qLogs = query(collection(db, "dispatch_logs"), where("toBranch", "==", myBranch), orderBy("timestamp", "desc"));
        const snap = await getDocs(qLogs);
        
        let deliveries = {};
        snap.forEach(doc => {
            let d = doc.data(); d.id = doc.id;
            let groupKey = `${d.date}_${d.toBranch}_${d.driver || 'Unknown'}`;
            if(!deliveries[groupKey]) deliveries[groupKey] = { date: d.date, time: d.time, toBranch: d.toBranch, driver: d.driver || 'Unknown', items: [], status: 'In Transit', timestamp: d.timestamp };
            deliveries[groupKey].items.push(d);
            if(d.status === "Received") deliveries[groupKey].status = "Received";
            if(d.status === "Variance") deliveries[groupKey].status = "Variance Detected";
            if(d.status === "Backloaded") deliveries[groupKey].status = "Backloaded";
        });

        let deliveryHtml = '';
        let sortedKeys = Object.keys(deliveries).sort((a,b) => deliveries[b].timestamp - deliveries[a].timestamp);

        sortedKeys.slice(0, 20).forEach(key => {
            let del = deliveries[key];
            let badgeColor = del.status === 'Received' ? '#16a34a' : (del.status === 'Variance Detected' ? '#dc2626' : (del.status === 'Backloaded' ? '#475569' : '#f59e0b'));
            let safeItemsJson = encodeURIComponent(JSON.stringify(del.items));

            deliveryHtml += `<tr style="border-bottom:1px solid #e2e8f0; background: white; transition: 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='white'">
                <td style="padding:15px;">
                    <div style="font-weight:bold; color:#0f172a; font-size:14px;">📍 To: ${del.toBranch}</div>
                    <div style="font-size:12px; color:#64748b; margin-top: 4px;">🚚 Driver: ${del.driver}</div>
                    <div style="font-size:11px; color:#94a3b8; margin-top:4px;">📅 ${del.date} at ${del.time}</div>
                </td>
                <td style="padding:15px; text-align:center;"><span style="background:${badgeColor}; color:white; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">${del.status}</span></td>
                <td style="padding:15px; text-align:right;"><button onclick="window.viewDispatchDetails('${safeItemsJson}', '${del.toBranch}', '${del.driver}', '${del.date}', '${del.time}')" style="background: white; color: #0ea5e9; border: 1px solid #0ea5e9; padding: 6px 12px; border-radius: 6px; font-size: 12px; font-weight: bold; cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">🔍 Full Details</button></td>
            </tr>`;
        });

        window.globalPoHtml = poHtml;
        window.globalDeliveryHtml = deliveryHtml;
        window.globalPoCount = poCount;
        window.globalDeliveryCount = sortedKeys.length;

        if (poCount > 0 && window.activeLogisticsTab !== 'Deliveries') {
            window.activeLogisticsTab = 'Requests';
        }

        window.renderLogisticsFeed();

    } catch (e) { 
        console.error(e); 
        tbody.innerHTML = '<tr><td colspan="3" class="text-center" style="color:red; padding: 20px;">Error loading logs</td></tr>'; 
    }
};

window.renderLogisticsFeed = function() {
    const tbody = document.getElementById('dispatchLogBody');
    if (!tbody) return;
    
    let table = tbody.closest('table');
    
    // 🎨 Auto-rename the main card title!
    let cardHeaders = table.closest('.card')?.querySelectorAll('h1, h2, h3, h4, h5, h6, .card-header');
    if (cardHeaders) {
        cardHeaders.forEach(h => {
            if (h.innerText.includes('Recent Deliveries') || h.innerText.includes('Logistics Feed')) {
                h.innerHTML = '📜 Logistics Feed';
            }
        });
    }

    // 🎨 Inject the beautifully styled Tab UI above the table!
    if (!document.getElementById('logisticsTabContainer')) {
        let tabHtml = `
            <div id="logisticsTabContainer" style="display: flex; border-bottom: 2px solid #e2e8f0; margin-bottom: 0px; background: #f8fafc; border-radius: 8px 8px 0 0; overflow: hidden;">
                <button id="btnTabRequests" onclick="window.switchLogisticsTab('Requests')" style="flex: 1; padding: 14px; border: none; border-bottom: 3px solid transparent; background: transparent; font-weight: 900; color: #64748b; cursor: pointer; font-size: 13px; text-transform: uppercase; transition: 0.2s;">
                    📢 Stock Requests (<span id="tabCountReq">0</span>)
                </button>
                <button id="btnTabDeliveries" onclick="window.switchLogisticsTab('Deliveries')" style="flex: 1; padding: 14px; border: none; border-bottom: 3px solid transparent; background: transparent; font-weight: 900; color: #64748b; cursor: pointer; font-size: 13px; text-transform: uppercase; transition: 0.2s; border-left: 1px solid #e2e8f0;">
                    🚚 Deliveries (<span id="tabCountDel">0</span>)
                </button>
            </div>
        `;
        table.insertAdjacentHTML('beforebegin', tabHtml);
        table.style.marginTop = "0px";
    }

    // Update the live counters inside the tabs
    document.getElementById('tabCountReq').innerText = window.globalPoCount || 0;
    document.getElementById('tabCountDel').innerText = window.globalDeliveryCount || 0;

    let btnReq = document.getElementById('btnTabRequests');
    let btnDel = document.getElementById('btnTabDeliveries');

    // Toggle Colors and Content based on which tab is clicked
    if (window.activeLogisticsTab === 'Requests') {
        btnReq.style.color = '#0ea5e9'; btnReq.style.borderBottomColor = '#0ea5e9'; btnReq.style.background = '#f0f9ff';
        btnDel.style.color = '#64748b'; btnDel.style.borderBottomColor = 'transparent'; btnDel.style.background = '#f8fafc';
        tbody.innerHTML = window.globalPoHtml || '<tr><td colspan="3" class="text-center" style="padding:50px; color:#94a3b8; font-weight:bold;">No pending requests. You are all caught up! 🎉</td></tr>';
    } else {
        btnDel.style.color = '#0ea5e9'; btnDel.style.borderBottomColor = '#0ea5e9'; btnDel.style.background = '#f0f9ff';
        btnReq.style.color = '#64748b'; btnReq.style.borderBottomColor = 'transparent'; btnReq.style.background = '#f8fafc';
        tbody.innerHTML = window.globalDeliveryHtml || '<tr><td colspan="3" class="text-center" style="padding:50px; color:#94a3b8; font-weight:bold;">No recent deliveries on record.</td></tr>';
    }
};

// ========================================================
// 🔍 STOCK REQUEST REVIEW ENGINE (INSTANT INVENTORY OVERRIDE)
// ========================================================
window.reviewPurchaseOrder = async function(poId) {
    try {
        Swal.fire({title: 'Loading Request...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});
        const docRef = window.doc(window.db, "purchase_orders", poId);
        const snap = await window.getDoc(docRef);
        if (!snap.exists()) return Swal.fire('Error', 'This request could not be found.', 'error');
        
        let po = snap.data();
        let dateStr = po.timestamp ? (po.timestamp.toDate ? po.timestamp.toDate() : new Date(po.timestamp)).toLocaleString('en-US', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : 'Unknown';
        
        const hqSnap = await window.getDocs(window.query(window.collection(window.db, "inventory"), window.where("branch", "==", "Main Office")));
        let hqStock = {};
        let hqDetails = {}; 
        hqSnap.forEach(d => {
            hqStock[d.data().name] = parseFloat(d.data().currentStock || 0);
            hqDetails[d.data().name] = d.data(); 
        });

        let html = `
            <div style="margin-bottom: 15px;">
                <button onclick="window.deleteStockRequest('${poId}')" style="width: 100%; padding: 14px; background: #fef2f2; border: 2px solid #fca5a5; color: #b91c1c; border-radius: 8px; font-weight: 900; cursor: pointer; font-size: 15px; box-shadow: 0 4px 6px rgba(220, 38, 38, 0.15); text-transform: uppercase;">
                    🗑️ Permanently Delete Request
                </button>
            </div>

            <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 15px; margin-bottom: 15px; text-align: left;">
                <div style="font-size: 11px; color: #64748b; font-weight: bold; text-transform: uppercase;">Requested By</div>
                <div style="font-size: 15px; color: #0f172a; font-weight: 900; margin-bottom: 10px;">👤 ${po.requestedBy || 'Staff'}</div>
                <div style="font-size: 11px; color: #64748b; font-weight: bold; text-transform: uppercase;">Date Submitted</div>
                <div style="font-size: 14px; color: #334155; font-weight: bold;">📅 ${dateStr}</div>
            </div>

            <!-- 🔥 THE FIX: table-layout: fixed and centered columns pull everything together perfectly! -->
            <div style="max-height: 40vh; overflow-y: auto; overflow-x: hidden; text-align: left; border: 1px solid #cbd5e1; border-radius: 8px; border-bottom: none;">
            <table style="width: 100%; border-collapse: collapse; font-size: 13px; table-layout: fixed;">
                <thead style="background: #0f172a; color: white; position: sticky; top: 0; z-index: 10;">
                    <tr>
                        <th style="padding: 12px 15px; text-align: left; width: 50%;">Item Description</th>
                        <th style="padding: 12px 15px; text-align: center; width: 25%;">Count / Request</th>
                        <th style="padding: 12px 15px; text-align: center; width: 25%;">Status</th>
                    </tr>
                </thead>
                <tbody>`;
        
        if (po.items && po.items.length > 0) {
            po.items.forEach(item => {
                let isAudit = (item.requestType === 'Low Stock' || item.requestType === 'Out of Stock' || item.physicalStock !== undefined);
                let badgeText = item.requestType || 'Request';
                
                if (badgeText === 'Delayed / Backlogged' && isAudit) {
                    let phys = item.physicalStock !== undefined ? item.physicalStock : (item.displayQty || item.qty || 0);
                    badgeText = (phys <= 0) ? 'Out of Stock' : 'Low Stock';
                }

                let alertColor = badgeText === 'Out of Stock' ? '#dc2626' : (badgeText === 'Low Stock' ? '#d97706' : (badgeText === 'Lost in Transit' ? '#b91c1c' : '#0284c7'));
                
                // 🧠 AI Color & Label Logic
                let isAI = badgeText.includes('AI') || badgeText.includes('Maintaining') || badgeText.includes('Restock') || badgeText.includes('Par Fill');
                if (isAI) alertColor = '#0ea5e9';

                let alertStyle = badgeText === 'Lost in Transit' ? `color: white; background: ${alertColor}; border: 1px solid #7f1d1d;` : `color: ${alertColor}; background: white; border: 1px solid ${alertColor}50;`;
                let rowBg = badgeText === 'Lost in Transit' ? '#fff1f2' : 'white';

                let itemName = item.itemName || item.name;
                let hqData = hqDetails[itemName] || {};
                
                let masterCRate = parseFloat(hqData.conversionRate) || parseFloat(hqData.conversion) || parseFloat(item.convRate) || parseFloat(item.conversionRate) || 1;
                
                let printUom = hqData.purchaseUom || hqData.purchUom || item.purchaseUom || item.displayUom || item.uom;
                let baseUom = hqData.uom || hqData.baseUom || item.uom || item.baseUom;

                let formatNum = (num) => (num % 1 === 0 ? num : parseFloat(num).toFixed(2));

                let qtyDisplay = '';
                if (isAudit) {
                    let physBase = item.physicalStock !== undefined ? parseFloat(item.physicalStock) : (parseFloat(item.qty) || 0);
                    let sysBase = item.systemStock !== undefined ? parseFloat(item.systemStock) : '---';

                    let physCount = item.displayQty !== undefined ? parseFloat(item.displayQty) : (physBase / masterCRate);
                    let sysCount = sysBase !== '---' ? (sysBase / masterCRate) : '---';
                    
                    printUom = item.displayUom || printUom;

                    let topLabel = isAI ? 'Qty Need' : 'Phys';
                    let topColor = isAI ? '#0ea5e9' : '#b91c1c';

                    // Center aligned text pulls it right into the middle of the box!
                    qtyDisplay = `
                        <div style="font-size: 13px; color: ${topColor}; font-weight: 900; text-align: center; white-space: nowrap;">${topLabel}: ${formatNum(physCount)} <span style="font-size:10px;">${printUom}</span></div>
                        <div style="font-size: 11px; color: #64748b; font-weight: bold; text-align: center; white-space: nowrap;">Sys: ${sysCount !== '---' ? formatNum(sysCount) : '---'} <span style="font-size:10px;">${printUom}</span></div>
                    `;
                } else {
                    let reqBase = parseFloat(item.qty) || 0;
                    let reqCount = reqBase / masterCRate;
                    qtyDisplay = `<div style="font-weight: 900; color: #0ea5e9; font-size: 14px; text-align: center; white-space: nowrap;">Req: ${formatNum(reqCount)} <span style="font-size: 10px; color: #64748b;">${printUom}</span></div>`;
                }

                html += `
                    <tr style="border-bottom: 1px solid #e2e8f0; background: ${rowBg};">
                        <td style="padding: 12px 15px; font-weight: bold; color: #334155; vertical-align: middle; word-wrap: break-word;">
                            ${itemName}<br>
                            <span style="font-size:10px; color:#64748b; font-weight:normal;">HQ Stock: ${formatNum(hqStock[itemName] || 0)} ${baseUom}</span>
                        </td>
                        <td style="padding: 12px 15px; text-align: center; vertical-align: middle;">${qtyDisplay}</td>
                        <td style="padding: 12px 15px; text-align: center; vertical-align: middle;">
                            <span style="${alertStyle} padding: 4px 10px; border-radius: 6px; font-weight: bold; font-size: 11px; white-space: normal; display: inline-block; line-height: 1.2;">${badgeText}</span>
                        </td>
                    </tr>
                `;
            });
        }
        html += `</tbody></table></div>`;
        
        html += `
            <div style="margin-top: 15px;">
                <button type="button" onclick="window.processRejectRequest('${poId}')" style="width: 100%; background: #dc2626; color: white; border: none; padding: 12px 15px; border-radius: 8px; cursor: pointer; font-weight: bold; font-size: 14px; box-shadow: 0 4px 6px rgba(220, 38, 38, 0.2); transition: 0.2s;">
                    🛑 Reject Request & Notify Branch
                </button>
            </div>
        `;
        
        let titleTxt = po.type === 'Internal Request' ? `📢 Issue Report: ${po.branch}` : `📦 Request from ${po.branch}`;
        
        let actionResult = await Swal.fire({
            title: titleTxt, 
            html: html, 
            showCancelButton: true, showDenyButton: true,
            confirmButtonColor: '#16a34a', cancelButtonColor: '#64748b', denyButtonColor: '#d97706',
            confirmButtonText: '🛒 Load to Dispatch Cart', denyButtonText: '⏸️ Postpone / Set Aside', cancelButtonText: 'Close Window',
            width: '800px', // Adjusted to keep it perfectly proportioned
            customClass: { popup: 'rounded-2xl shadow-xl' }
        });

        if (actionResult.isConfirmed) {
            if (typeof window.dispatchCart === 'undefined') window.dispatchCart = [];
            
            let storedDest = localStorage.getItem('takodeal_dispatch_to');
            if (window.dispatchCart.length > 0 && storedDest && storedDest !== po.branch) {
                await window.clearDispatchCart(); 
                Swal.fire({
                    toast: true, position: 'top-end', icon: 'info',
                    title: `Previous cart set aside. Loading ${po.branch}...`,
                    showConfirmButton: false, timer: 3000
                });
            }

            if (window.dispatchCart.length === 0) {
                Object.keys(localStorage).forEach(key => { if(key.startsWith('takodeal_draft_qty_')) localStorage.removeItem(key); });
            }

            let totalPenaltiesIssued = 0;

            for (let reqItem of po.items) {
                let itemName = reqItem.itemName || reqItem.name;
                let hqData = hqDetails[itemName] || {}; 

                let pUom = hqData.purchaseUom || hqData.purchUom || reqItem.purchaseUom || reqItem.uom || 'units';
                let bUom = hqData.uom || hqData.baseUom || reqItem.uom || reqItem.baseUom || 'units';
                let cRate = parseFloat(hqData.conversionRate) || parseFloat(hqData.conversion) || parseFloat(reqItem.convRate) || parseFloat(reqItem.conversionRate) || 1;

                let originalBaseQty = parseFloat(reqItem.qty) || 0;
                let originalDisplayQty = originalBaseQty / cRate; 
                
                let physStockToPass = reqItem.physicalStock !== undefined ? reqItem.physicalStock : originalBaseQty;
                let sysStockToPass = reqItem.systemStock !== undefined ? reqItem.systemStock : 0;
                
                let isAudit = (reqItem.requestType === 'Low Stock' || reqItem.requestType === 'Out of Stock' || reqItem.physicalStock !== undefined);
                let badgeText = reqItem.requestType || 'Request';
                if (badgeText === 'Delayed / Backlogged' && isAudit) {
                    badgeText = (physStockToPass <= 0) ? 'Out of Stock' : 'Low Stock';
                }
                
                let rawReqQty = isAudit ? 0 : originalDisplayQty;
                let baseReqQty = isAudit ? 0 : originalBaseQty;

                let mappedItem = {
                    ...reqItem, 
                    rawQty: rawReqQty,
                    qty: baseReqQty,
                    origRawQty: rawReqQty, 
                    origBaseQty: baseReqQty,
                    purchaseUom: pUom,
                    baseUom: bUom,
                    conversionRate: cRate,
                    selectedUom: (pUom.toLowerCase() !== bUom.toLowerCase()) ? 'purch' : 'base',
                    hqStock: parseFloat(hqData.currentStock) || 0,
                    requestType: badgeText,
                    physicalStock: physStockToPass, 
                    systemStock: sysStockToPass
                };

                mappedItem.convRate = (mappedItem.selectedUom === 'purch') ? cRate : 1;
                mappedItem.friendlyUom = (mappedItem.selectedUom === 'purch') ? pUom : bUom;

                let existing = window.dispatchCart.find(i => (i.itemName || i.name) === itemName);
                
                if (existing) {
                    existing.rawQty = (parseFloat(existing.rawQty) || 0) + rawReqQty;
                    existing.qty = (parseFloat(existing.qty) || 0) + baseReqQty;
                    existing.origRawQty = existing.rawQty;
                    existing.origBaseQty = existing.qty;
                    existing.requestType = badgeText;
                    existing.physicalStock = physStockToPass;
                    existing.systemStock = sysStockToPass;
                    existing.purchaseUom = mappedItem.purchaseUom;
                    existing.baseUom = mappedItem.baseUom;
                    existing.conversionRate = mappedItem.conversionRate;
                    existing.hqStock = mappedItem.hqStock;
                } else {
                    window.dispatchCart.push(mappedItem);
                }
            }

            document.getElementById('dispFrom').value = "Main Office"; 
            document.getElementById('dispTo').value = po.branch;
            
            let activePos = localStorage.getItem('takodeal_active_po') || "";
            let poArray = activePos ? activePos.split(',') : [];
            if (!poArray.includes(poId)) poArray.push(poId);
            
            localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));
            localStorage.setItem('takodeal_dispatch_to', po.branch);
            localStorage.setItem('takodeal_active_po', poArray.join(','));
            
            await window.updateDoc(docRef, { status: "Drafting", managerMessage: 'Approved. Inventory synced and loaded into Dispatch Cart.', processedAt: window.serverTimestamp() });
            
            window.renderDispatchCart(); 
            window.loadDispatchLogs();
            
            Swal.fire({title: 'Loaded to Cart! 🛒', text: `Items moved to Dispatch for ${po.branch}.`, icon: 'success', timer: 2000, showConfirmButton: false});
            
        } else if (actionResult.isDenied) {
            const { value: rejectReason } = await Swal.fire({
                title: 'Postpone Request',
                input: 'text',
                inputLabel: 'Reason for postponing',
                inputPlaceholder: 'Out of stock at HQ...',
                showCancelButton: true,
                confirmButtonColor: '#d97706',
                confirmButtonText: 'Set Aside',
                inputValidator: (value) => { if (!value) return 'You need to provide a reason!'; }
            });
            
            if (rejectReason) {
                Swal.fire({title: 'Updating...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});
                await window.updateDoc(docRef, { status: 'Delayed', managerMessage: rejectReason, processedAt: window.serverTimestamp() });
                Swal.fire('Postponed', 'The request was set aside.', 'info');
                window.loadDispatchLogs(); 
            }
        }
    } catch(e) { console.error(e); Swal.fire('Error', 'Failed to load details.', 'error'); }
};

// ==========================================
// 🛑 THE REJECT ENGINE (MUST BE ADDED RIGHT BELOW IT)
// ==========================================
window.processRejectRequest = async function(docId) {
    if (!docId) return;

    let reason = prompt(
        "🛑 REJECTING REQUEST\n\nEnter the reason for rejection (this will pop up on the Cashier's screen):",
        "Incorrect Unit of Quantity (e.g., inputted Cans instead of Grams). Please recount physically and submit a new request."
    );

    if (reason === null || reason.trim() === "") return;

    Swal.fire({title: 'Rejecting...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        await updateDoc(doc(db, "purchase_orders", docId), { 
            status: "Rejected",
            rejectReason: reason,
            cashierAcknowledged: false, // Forces the red box to appear for the cashier!
            processedAt: serverTimestamp()
        });
        
        Swal.fire('✅ Rejected!', 'The request was rejected and the branch has been notified.', 'success');
        
        // Refresh the lists
        if (typeof window.loadDispatchLogs === 'function') window.loadDispatchLogs();
        if (typeof window.startPOListener === 'function') window.startPOListener();
    } catch (e) {
        console.error(e);
        Swal.fire('Error', 'Failed to reject request.', 'error');
    }
};

// ==========================================
// 🗑️ DISPOSE / DELETE STOCK REQUEST ENGINE
// ==========================================
window.deleteStockRequest = async function(poId) {
    let confirmDelete = await Swal.fire({
        title: 'Dispose Request?',
        text: "Are you sure you want to permanently delete this request? This action cannot be undone.",
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#dc2626',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Yes, Delete it!',
        customClass: { popup: 'rounded-2xl shadow-xl' }
    });

    if (!confirmDelete.isConfirmed) return;

    Swal.fire({title: 'Deleting...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        await deleteDoc(doc(db, "purchase_orders", poId));
        Swal.fire({
            title: 'Deleted!', 
            text: 'The request has been permanently disposed.', 
            icon: 'success', 
            timer: 2000, 
            showConfirmButton: false,
            customClass: { popup: 'rounded-2xl' }
        });
        
        if (typeof window.loadDispatchLogs === 'function') window.loadDispatchLogs(); 
        Swal.close(); // Force the modal to close instantly
    } catch (e) {
        console.error("Delete Error:", e);
        Swal.fire('Error', 'Failed to delete the request.', 'error');
    }
};

window.approvePurchaseOrder = async function(poId) {
    try {
        const poRef = doc(db, "purchase_orders", poId);
        const poSnap = await getDoc(poRef);
        if (!poSnap.exists()) return;
        
        let po = poSnap.data();
        dispatchCart = po.items;
        document.getElementById('dispFrom').value = "Main Office";
        document.getElementById('dispTo').value = po.branch;
        await updateDoc(poRef, { status: "Approved" });
        
        if (typeof renderDispatchCart === 'function') renderDispatchCart(); else window.renderDispatchCart();
        window.loadDispatchLogs();
        
        Swal.fire({
            title: '✅ Purchase Order Loaded!',
            html: `${po.branch}'s request has been placed into your Dispatch Cart.<br><br><span style="font-size: 13px; color: #64748b;">You can now adjust quantities or remove out-of-stock items before clicking <b>Send Dispatch Delivery</b> to physically pack it.</span>`,
            icon: 'info', confirmButtonColor: '#0f766e', customClass: { popup: 'rounded-2xl' }
        });
    } catch(e) { console.error(e); Swal.fire('Error', 'Failed to load Purchase Order.', 'error'); }
};

// ========================================================
// 🚚 UPGRADED DISPATCH DETAILS MODAL (WITH VARIANCE & TIME)
// ========================================================
window.backloadDispatchItem = async function(logId, itemName, qtyToReturn, destinationBranch) {
    if (!confirm(`⚠️ BACKLOAD ITEM\n\nAre you sure you want to cancel the delivery of ${qtyToReturn} units of "${itemName}" to ${destinationBranch}?\n\nThis will mark the item as "Backloaded" and securely return the physical stock to the Main Office warehouse.`)) return;

    Swal.fire({ title: 'Processing Backload...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    try {
        // 1. Mark the dispatch log as Backloaded
        await updateDoc(doc(db, "dispatch_logs", logId), { 
            status: "Backloaded", 
            receivedDisplayQty: 0, 
            receivedQty: 0 
        });

        // 2. Refund the stock back to the Main Office
        const invQ = query(collection(db, "inventory"), where("branch", "==", "Main Office"), where("name", "==", itemName));
        const invSnap = await getDocs(invQ);
        
        if (!invSnap.empty) {
            let invDoc = invSnap.docs[0];
            let currentStock = parseFloat(invDoc.data().currentStock) || 0;
            let uom = invDoc.data().uom || 'units';
            
            await updateDoc(invDoc.ref, { currentStock: currentStock + qtyToReturn });

            // 3. Write an official Stock Log for the return
            await addDoc(collection(db, "stock_logs"), {
                branch: "Main Office", item: itemName, uom: uom,
                oldQty: currentStock, newQty: currentStock + qtyToReturn, variance: qtyToReturn,
                type: "Delivery Backload", note: `Cancelled transit to ${destinationBranch}. Stock returned.`,
                user: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: new Date()
            });
        }

        Swal.fire({
            title: '✅ Item Backloaded',
            text: `${itemName} has been successfully cancelled and returned to HQ inventory.`,
            icon: 'success',
            customClass: { popup: 'rounded-2xl' }
        });
        
        // Refresh UI
        document.getElementById('dispatchDetailsModal').style.display = 'none';
        window.loadDispatchLogs();
        if(typeof window.loadInventoryData === 'function') window.loadInventoryData();
        
    } catch(e) {
        console.error("Backload Error:", e);
        Swal.fire('Error', 'Failed to backload item. Please check console.', 'error');
    }
};

window.resolveMissingDispatchItems = async function(encodedGroup) {
    let items = JSON.parse(decodeURIComponent(encodedGroup));
    let missingItems = items.filter(i => {
        let sent = parseFloat(i.displayQty || i.qty);
        let received = i.receivedDisplayQty !== undefined ? parseFloat(i.receivedDisplayQty) : (i.receivedQty !== undefined ? parseFloat(i.receivedQty) : null);
        if (received === null || i.status === 'Backloaded') return false;
        return (received - sent) < 0;
    });
    
    if (missingItems.length === 0) return;

    let itemsListHtml = missingItems.map(i => {
        let sent = parseFloat(i.displayQty || i.qty);
        let received = i.receivedDisplayQty !== undefined ? parseFloat(i.receivedDisplayQty) : parseFloat(i.receivedQty);
        let variance = Math.abs(received - sent);
        let uom = i.displayUom || i.uom;
        return `<li style="margin-bottom: 5px;"><b>${i.item || i.name}</b>: Missing <b style="color:#dc2626;">${variance} ${uom}</b></li>`;
    }).join('');

    const { value: action } = await Swal.fire({
        title: '🕵️ Resolve Missing Items',
        html: `
            <div style="text-align: left; font-size: 13px; color: #334155; margin-bottom: 15px;">
                The cashier reported receiving less than what was dispatched. Please double-check with the driver. How do you want to resolve this?
                <ul style="margin-top: 10px; color: #0f172a; background: #f8fafc; padding: 10px 10px 10px 25px; border-radius: 6px; border: 1px solid #e2e8f0;">
                    ${itemsListHtml}
                </ul>
            </div>
        `,
        input: 'radio',
        inputOptions: {
            'return': '📦 The driver brought them back (Return to HQ Inventory)',
            'requeue': '🔄 They were genuinely lost (Re-queue as a Stock Request)'
        },
        inputValidator: (value) => { if (!value) return 'You need to select an action!'; },
        showCancelButton: true, confirmButtonText: 'Confirm Resolution', confirmButtonColor: '#0ea5e9',
        customClass: { popup: 'rounded-2xl shadow-xl' }
    });

    if (!action) return;
    Swal.fire({title: 'Processing Resolution...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        if (action === 'return') {
            for (let item of missingItems) {
                let sent = parseFloat(item.displayQty || item.qty);
                let received = item.receivedDisplayQty !== undefined ? parseFloat(item.receivedDisplayQty) : parseFloat(item.receivedQty);
                let convRate = parseFloat(item.convRate) || 1;
                let baseVarianceQty = Math.abs(received - sent) * convRate; 
                let originBranch = item.fromBranch || "Main Office";
                
                const invQ = query(collection(db, "inventory"), where("branch", "==", originBranch), where("name", "==", item.item || item.name));
                const invSnap = await getDocs(invQ);
                
                if (!invSnap.empty) {
                    let invDoc = invSnap.docs[0];
                    let currentStock = parseFloat(invDoc.data().currentStock) || 0;
                    await updateDoc(invDoc.ref, { currentStock: currentStock + baseVarianceQty });
                    
                    await addDoc(collection(db, "stock_logs"), {
                        branch: originBranch, item: item.item || item.name, uom: invDoc.data().uom || 'units',
                        oldQty: currentStock, newQty: currentStock + baseVarianceQty, variance: baseVarianceQty,
                        type: "Dispatch Returned (Missing Resolved)", note: `Items missing at destination returned to HQ.`,
                        user: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: serverTimestamp()
                    });
                }
                await updateDoc(doc(db, "dispatch_logs", item.id), { status: 'Missing (Returned to HQ)' });
            }
            Swal.fire('✅ Returned to HQ', 'The missing items have been successfully returned to your Main Office inventory.', 'success');
        } 
        else if (action === 'requeue') {
            let toBranch = missingItems[0].toBranch;
            let poItems = missingItems.map(item => {
                let sent = parseFloat(item.displayQty || item.qty);
                let received = item.receivedDisplayQty !== undefined ? parseFloat(item.receivedDisplayQty) : parseFloat(item.receivedQty);
                let displayVariance = Math.abs(received - sent);
                let baseVarianceQty = displayVariance * (parseFloat(item.convRate) || 1); 

                return { 
                    itemName: item.item || item.name, name: item.item || item.name, 
                    qty: baseVarianceQty, displayQty: displayVariance, 
                    uom: item.baseUom || item.uom, displayUom: item.displayUom || item.purchaseUom || item.uom, 
                    requestType: 'Lost in Transit', physicalStock: 0, systemStock: 0 
                };
            });

            await addDoc(collection(db, "purchase_orders"), { branch: toBranch, items: poItems, status: "Pending", type: "Lost Item Replacement", requestedBy: "System (HQ Resolved)", timestamp: serverTimestamp() });

            for (let item of missingItems) {
                await updateDoc(doc(db, "dispatch_logs", item.id), { status: 'Missing (Re-queued)' });
            }
            Swal.fire('✅ Re-Queued', 'Lost items have been instantly sent to the Stock Requests feed so you can dispatch them again.', 'success');
        }

        document.getElementById('dispatchDetailsModal').style.display = 'none';
        if (typeof window.loadDispatchLogs === 'function') window.loadDispatchLogs();
        if (typeof window.loadInventoryData === 'function') window.loadInventoryData();
    } catch (e) { console.error(e); Swal.fire('Error', 'Failed to resolve items.', 'error'); }
};

// ========================================================
// 🚚 THE DISPATCH & LOGISTICS ENGINE (SMART COMMAND CENTER)
// ========================================================
window.dispatchCart = [];
window.dispatchInventoryList = [];

window.loadDispatchDashboard = async function() {
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;
    let myBranch = window.sessionUser ? window.sessionUser.branch : "Unknown";

    const branches = window.globalActiveBranches ? window.globalActiveBranches : ["Main Office", "Cabantian", "Citygate", "Maa", "SM Lanang"];
    
    let fromHtml = '<option value="">-- Select Source --</option>';
    let toHtml = '<option value="">-- Select Destination --</option>';
    let btn = document.getElementById('btnSubmitDispatch');

    if (isFranchisee) {
        fromHtml = `<option value="Main Office">Main Office (HQ)</option>`;
        toHtml = `<option value="${myBranch}">${myBranch}</option>`;
        if (btn) btn.innerText = "📝 Request Stock from HQ";
    } else {
        branches.forEach(b => {
            fromHtml += `<option value="${b}">${b}</option>`;
            toHtml += `<option value="${b}">${b}</option>`;
        });
        if (btn) btn.innerText = "🚀 Send Dispatch Delivery";
    }

    document.getElementById('dispFrom').innerHTML = fromHtml;
    document.getElementById('dispFrom').value = "Main Office";
    document.getElementById('dispTo').innerHTML = toHtml;

    // 💾 VAULT RECOVERY: Restore Cart if they accidentally refreshed!
    let savedCart = localStorage.getItem('takodeal_dispatch_cart');
    if (savedCart && !isFranchisee) {
        try { window.dispatchCart = JSON.parse(savedCart); } catch(e) { window.dispatchCart = []; }
        let savedTo = localStorage.getItem('takodeal_dispatch_to');
        if (savedTo) setTimeout(() => { document.getElementById('dispTo').value = savedTo; }, 100);
    } else {
        window.dispatchCart = [];
    }
    
    if (isFranchisee) document.getElementById('dispTo').value = myBranch;

    window.renderDispatchCart();
    await window.loadDispatchInventory();
};

window.loadDispatchInventory = async function () {
    let fromBranch = document.getElementById('dispFrom').value;
    let itemInput = document.getElementById('dispItem');

    if (itemInput.tagName === 'SELECT') {
        let newInput = document.createElement('input');
        newInput.id = 'dispItem'; newInput.setAttribute('list', 'dispatchDatalist');
        newInput.placeholder = "Type to search item to send...";
        newInput.style.cssText = "width: 100%; padding: 10px; border: 1px solid var(--border); border-radius: 6px; outline: none; box-sizing: border-box; font-size: 14px; font-weight: bold; color: #334155;";
        newInput.onchange = window.updateDispatchUomLabel; newInput.onkeyup = window.updateDispatchUomLabel; 
        itemInput.parentNode.replaceChild(newInput, itemInput); itemInput = newInput;
    }

    if (!fromBranch) { itemInput.placeholder = 'Select source branch first...'; itemInput.disabled = true; itemInput.value = ''; return; }
    
    itemInput.disabled = false; itemInput.placeholder = 'Scanning warehouse...'; itemInput.value = '';
    window.dispatchInventoryList = [];

    try {
        const q = query(collection(db, "inventory"), where("branch", "==", fromBranch));
        const snap = await getDocs(q);
        
        let datalistHtml = '<datalist id="dispatchDatalist">';
        let sortedStock = [];
        
        snap.forEach(docSnap => { let data = docSnap.data(); sortedStock.push({ id: docSnap.id, ...data }); });
        sortedStock.sort((a, b) => a.name.localeCompare(b.name));
        let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;

        sortedStock.forEach(data => {
            window.dispatchInventoryList.push(data);
            let safeStock = parseFloat(data.currentStock).toFixed(1);
            if (isFranchisee) datalistHtml += `<option value="${data.name}">${data.name} (Request in ${data.uom})</option>`;
            else datalistHtml += `<option value="${data.name}">Available: ${safeStock} ${data.uom}</option>`;
        });
        datalistHtml += '</datalist>';

        let existingList = document.getElementById('dispatchDatalist');
        if (existingList) existingList.remove();
        document.body.insertAdjacentHTML('beforeend', datalistHtml);

        itemInput.placeholder = 'Type to search item...'; window.updateDispatchUomLabel();
        if (window.dispatchCart.length > 0) window.renderDispatchCart();
    } catch (e) { console.error(e); itemInput.placeholder = 'Error loading stock'; }
};

window.updateDispatchUomLabel = async function() {
    let itemName = document.getElementById('dispItem').value.trim();
    let uomDrop = document.getElementById('dispUomSelect');
    let toBranch = document.getElementById('dispTo').value;

    // 🔥 INJECT AI TRACKER UI DYNAMICALLY
    let aiContainer = document.getElementById('dispAiTracker');
    if (!aiContainer) {
        // Place it beautifully right below the quantity box
        let qtyContainer = document.getElementById('dispQty').parentElement.parentElement;
        qtyContainer.insertAdjacentHTML('afterend', `<div id="dispAiTracker" style="width: 100%; margin-top: 10px; flex-basis: 100%;"></div>`);
        aiContainer = document.getElementById('dispAiTracker');
    }

    if (!itemName || !toBranch) { 
        uomDrop.innerHTML = '<option value="base">Units</option>'; 
        if(aiContainer) aiContainer.innerHTML = '';
        return; 
    }

    let invItem = window.dispatchInventoryList.find(i => i.name === itemName);
    if (invItem) {
        let baseUom = invItem.uom || 'units'; 
        let purchUom = invItem.purchaseUom || 'Bulk';
        uomDrop.innerHTML = `<option value="purch">${purchUom}</option><option value="base">${baseUom}</option>`;
    }

    // 🔥 AWAKEN THE AI TRACKER ENGINE
    if(aiContainer) {
        aiContainer.innerHTML = '<span style="color:#0ea5e9; font-size:11px; font-weight:bold; animation: pulse 1s infinite;">🤖 AI Scanning Branch Data...</span>';
        
        try {
            // 1. Fetch current stock at destination branch
            const invQ = query(collection(db, "inventory"), where("branch", "==", toBranch), where("name", "==", itemName));
            const invSnap = await getDocs(invQ);
            let currentStock = 0; let bUom = 'units';
            if (!invSnap.empty) {
                currentStock = parseFloat(invSnap.docs[0].data().currentStock) || 0;
                bUom = invSnap.docs[0].data().uom || 'units';
            }

            // 2. Fetch last 14 days burn rate
            let fourteenDaysAgo = new Date();
            fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);
            const logsQ = query(collection(db, "stock_logs"), where("branch", "==", toBranch), where("item", "==", itemName), where("timestamp", ">=", fourteenDaysAgo));
            const logsSnap = await getDocs(logsQ);

            let totalBurn = 0;
            logsSnap.forEach(doc => {
                let log = doc.data();
                let v = parseFloat(log.variance) || 0;
                let t = (log.type || "").toLowerCase();
                // Mathematically calculate every deduction
                if (v < 0 && (t.includes("sales") || t.includes("deduction") || t.includes("waste") || t.includes("spoilage") || t.includes("store use") || t.includes("prep") || t.includes("adjustment") || t.includes("voided") || t.includes("penalty") || t.includes("audit") || t.includes("count"))) {
                    totalBurn += Math.abs(v);
                }
            });

            let dailyBurn = totalBurn / 14;
            let daysLeft = dailyBurn > 0 ? (currentStock / dailyBurn) : Infinity;
            let daysText = daysLeft === Infinity ? "∞" : daysLeft.toFixed(1) + " Days";
            let statusColor = currentStock <= 0 ? "#dc2626" : (daysLeft <= 3 ? "#ea580c" : "#16a34a");

            aiContainer.innerHTML = `
                <div style="background: #f8fafc; border: 1px dashed #cbd5e1; padding: 10px; border-radius: 8px; font-size: 11px; color: #475569; display: flex; flex-direction: column; gap: 4px; box-shadow: inset 0 2px 4px rgba(0,0,0,0.02);">
                    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 4px;">
                        <strong style="color: #0f172a;">🤖 AI Stock Radar (${toBranch})</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Current Live Stock:</span>
                        <strong style="color: ${currentStock <= 0 ? '#dc2626' : '#334155'};">${currentStock.toFixed(2)} ${bUom}</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Avg. Daily Burn (14-day):</span>
                        <strong style="color: #b45309;">${dailyBurn.toFixed(2)} ${bUom}/day</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Estimated Runway:</span>
                        <strong style="color: ${statusColor};">${daysText}</strong>
                    </div>
                </div>
            `;
        } catch(e) {
            console.error("AI Tracker Error:", e);
            aiContainer.innerHTML = '<span style="color:#ef4444; font-size:11px;">Error loading AI data.</span>';
        }
    }
};

window.addToDispatchCart = function () {
    let itemName = document.getElementById('dispItem').value;
    let rawQty = parseFloat(document.getElementById('dispQty').value);
    if (!itemName || isNaN(rawQty) || rawQty <= 0) { alert("Please select an item and valid quantity."); return; }

    let invItem = window.dispatchInventoryList.find(i => i.name === itemName);
    if (!invItem) return;

    let uomSelect = document.getElementById('dispUomSelect'); 
    let selectedUomType = uomSelect ? uomSelect.value : 'base'; 

    let masterConv = parseFloat(invItem.conversionRate) || parseFloat(invItem.conversion) || 1;
    let convRate = (selectedUomType === 'purch') ? masterConv : 1;
    let friendlyUom = (selectedUomType === 'purch') ? (invItem.purchaseUom || "Bulk") : invItem.uom;
    let finalBaseQty = rawQty * convRate;

    let existing = window.dispatchCart.find(i => (i.itemName || i.name) === itemName);
    if (existing) { 
        existing.rawQty = (parseFloat(existing.rawQty) || 0) + rawQty;
        existing.qty = (parseFloat(existing.qty) || 0) + finalBaseQty; 
        existing.origRawQty = existing.rawQty;
        existing.origBaseQty = existing.qty;
        existing.friendlyUom = friendlyUom; 
        existing.convRate = convRate;
        existing.selectedUom = selectedUomType;
        existing.conversionRate = masterConv; 
        existing.hqStock = parseFloat(invItem.currentStock) || 0; 
    } else {
        window.dispatchCart.push({ 
            itemName: itemName, name: itemName, qty: finalBaseQty, uom: invItem.uom, sourceId: invItem.id, rawQty: rawQty,
            origRawQty: rawQty, origBaseQty: finalBaseQty,            
            friendlyUom: friendlyUom, convRate: convRate, category: invItem.category || "Ingredients", 
            purchaseUom: invItem.purchaseUom || invItem.uom, selectedUom: selectedUomType,
            conversionRate: masterConv, baseUom: invItem.baseUom || invItem.uom, cost: invItem.cost || 0, 
            hqStock: parseFloat(invItem.currentStock) || 0 
        });
    }

    document.getElementById('dispQty').value = ''; document.getElementById('dispItem').value = ''; 
    localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));
    window.renderDispatchCart();
};

window.removeFromDispatchCart = function (index) { 
    window.dispatchCart.splice(index, 1); 
    localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));
    Object.keys(localStorage).forEach(key => { if(key.startsWith('takodeal_draft_qty_')) localStorage.removeItem(key); });
    window.renderDispatchCart(); 
};

window.renderDispatchCart = function() {
    let container = document.getElementById('dispatchItemsList') || document.getElementById('dispatchCartContainer') || document.getElementById('dispatchCartBody');
    if (!container) return;

    if (typeof window.dispatchCart === 'undefined') window.dispatchCart = [];
    
    let isTable = container.tagName.toLowerCase() === 'tbody';

    if (window.dispatchCart.length === 0) {
        let emptyHtml = isTable ? '<tr><td colspan="3" style="padding:20px; text-align:center; color:#94a3b8; font-weight:bold;">Cart is empty.</td></tr>' : '<div style="padding:20px; text-align:center; color:#94a3b8; font-weight:bold;">Cart is empty.</div>';
        container.innerHTML = emptyHtml; return;
    }
    
    let html = '';

    window.dispatchCart.forEach((item, index) => {
        let hqItemObj = window.dispatchInventoryList ? window.dispatchInventoryList.find(i => i.id === item.sourceId || i.name === (item.name || item.itemName)) : null;
        if (hqItemObj) {
            item.name = hqItemObj.name; item.itemName = hqItemObj.name; item.baseUom = hqItemObj.uom || hqItemObj.baseUom || 'units';
            item.purchaseUom = hqItemObj.purchaseUom || hqItemObj.purchUom || item.baseUom;
            item.conversionRate = parseFloat(hqItemObj.conversionRate) || parseFloat(hqItemObj.conversion) || 1;
            item.hqStock = parseFloat(hqItemObj.currentStock) || 0;
            if (!item.selectedUom) item.selectedUom = 'base';
        }

        let pUom = item.purchaseUom || item.purchUom || item.uom || 'units';
        let bUom = item.baseUom || item.uom || 'units';
        let rawQty = parseFloat(item.rawQty) || 0;
        let baseQty = parseFloat(item.qty) || 0;
        let hqStock = parseFloat(item.hqStock || 0);
        
        let uomOptions = '';
        if (pUom.toLowerCase() !== bUom.toLowerCase()) uomOptions += `<option value="purch" ${item.selectedUom === 'purch' ? 'selected' : ''}>${pUom}</option>`;
        uomOptions += `<option value="base" ${item.selectedUom === 'base' ? 'selected' : ''}>${bUom}</option>`;

        let hqColor = hqStock < baseQty ? '#dc2626' : '#16a34a';
        let hqWarningText = hqStock < baseQty ? '⚠️ LOW HQ STOCK' : '🟢 HQ Stock OK';
        let hqBgColor = hqStock < baseQty ? '#fef2f2' : '#dcfce7';
        let hqBorderColor = hqStock < baseQty ? '#fca5a5' : '#bbf7d0';

        // Detect if this was a physical stock count alert to show the extra badge
        let isAudit = (item.requestType === 'Low Stock' || item.requestType === 'Out of Stock' || item.physicalStock !== undefined);
        let branchReportBadge = isAudit ? `<span style="font-size: 11px; color: #d97706; background: #fffbeb; border: 1px dashed #fcd34d; padding: 2px 4px; border-radius: 4px; display: inline-block; margin-top: 4px;">Branch Report (Phys: ${item.physicalStock || 0} | Sys: ${item.systemStock || 0})</span><br>` : '';

        // 🔥 THE ALIGNMENT FIX: Strict fixed widths (80px and 100px) force them into a perfect grid!
        let controlsHtml = `
            <div style="display:flex; justify-content:center; align-items:center; gap: 5px; margin: 0 auto; width: max-content;">
                <input type="number" step="any" id="cartQty_${index}" value="${rawQty || ''}" 
                    oninput="window.updateDispatchQty(${index}, this.value)" 
                    style="width: 80px; min-width: 80px; padding: 8px; border: 1px solid #cbd5e1; border-radius: 6px; text-align: center; outline: none; font-weight: bold; color: #d97706; font-size: 14px; box-sizing: border-box;">
                
                <select onchange="window.updateDispatchUom(${index}, this.value)" 
                    style="width: 100px; min-width: 100px; padding: 8px; border: 1px solid #cbd5e1; border-radius: 6px; background: white; color: #d97706; font-weight: bold; cursor: pointer; outline: none; box-sizing: border-box;">
                    ${uomOptions}
                </select>
            </div>
        `;

        if (isTable) {
            html += `
                <tr style="border-bottom: 1px solid #f1f5f9;">
                    <td style="padding: 15px 10px; width: 45%; vertical-align: middle;">
                        <strong style="color: #0f172a; font-size: 14px;">${item.name || item.itemName}</strong><br>
                        ${branchReportBadge}
                        <span style="font-size: 11px; color: ${hqColor}; background: ${hqBgColor}; border: 1px dashed ${hqBorderColor}; padding: 2px 6px; border-radius: 4px; display: inline-block; margin-top: 4px; font-weight: bold;">
                            🏢 HQ Avail: ${hqStock.toFixed(2)} ${bUom} (${hqWarningText})
                        </span><br>
                        <span id="dispatch_send_text_${index}" style="font-size: 11px; color: #059669; font-weight: bold; display: inline-block; margin-top: 4px;">Sending in ${bUom} (${baseQty.toFixed(2)} ${bUom})</span>
                    </td>
                    <td style="padding: 15px 10px; text-align: center; width: 35%; vertical-align: middle;">
                        ${controlsHtml}
                    </td>
                    <td style="padding: 15px 10px; text-align: right; width: 20%; vertical-align: middle;">
                        <button onclick="window.removeFromDispatchCart(${index})" 
                            style="background: #fef2f2; color: #ef4444; border: 1px solid #fca5a5; padding: 6px 10px; border-radius: 6px; cursor: pointer; font-weight: bold; font-size: 12px;">✖ Remove</button>
                    </td>
                </tr>
            `;
        } else {
            // Fallback for non-table layouts
            html += `
                <div style="display: grid; grid-template-columns: 2fr 1.5fr 1fr; align-items: center; padding: 15px 5px; border-bottom: 1px solid #f1f5f9; gap: 15px;">
                    <div>
                        <strong style="color: #0f172a; font-size: 14px;">${item.name || item.itemName}</strong><br>
                        ${branchReportBadge}
                        <span style="font-size: 11px; color: ${hqColor}; font-weight: bold;">🏢 HQ Avail: ${hqStock.toFixed(2)} ${bUom} (${hqWarningText})</span><br>
                        <span id="dispatch_send_text_${index}" style="font-size: 11px; color: #059669; font-weight: bold;">Sending in ${bUom} (${baseQty.toFixed(2)} ${bUom})</span>
                    </div>
                    <div>${controlsHtml}</div>
                    <div style="text-align: right;">
                        <button onclick="window.removeFromDispatchCart(${index})" style="background: #fef2f2; color: #ef4444; border: 1px solid #fca5a5; padding: 8px 12px; border-radius: 6px; font-weight: bold; cursor: pointer;">✖ Remove</button>
                    </div>
                </div>
            `;
        }
    });

    if (isTable) {
        html += `<tr><td colspan="3" style="padding: 15px; text-align: right; border-top: 2px dashed #e2e8f0;"><button onclick="window.clearDispatchCart()" style="background: #f8fafc; color: #475569; border: 1px dashed #cbd5e1; padding: 8px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 12px; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">🧹 Set Aside / Clear Cart</button></td></tr>`;
    } else {
        html += `<div style="margin-top: 15px; text-align: right; border-top: 2px dashed #e2e8f0; padding-top: 15px;"><button onclick="window.clearDispatchCart()" style="background: #f1f5f9; color: #475569; border: 1px dashed #cbd5e1; padding: 10px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 13px; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">🧹 Set Aside / Clear Cart</button></div>`;
    }

    container.innerHTML = html;
};

window.updateDispatchQty = function(index, val) {
    let item = window.dispatchCart[index];
    item.rawQty = parseFloat(val) || 0;
    let bUom = item.baseUom || item.uom || 'units';
    let masterConv = parseFloat(item.conversionRate) || 1;
    item.convRate = (item.selectedUom === 'purch') ? masterConv : 1;
    item.qty = item.rawQty * item.convRate;
    let textSpan = document.getElementById(`dispatch_send_text_${index}`);
    if(textSpan) textSpan.innerText = `Sending in ${bUom} (${item.qty.toFixed(2)} ${bUom})`;
    localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));
};

window.updateDispatchUom = function(index, val) {
    let item = window.dispatchCart[index];
    item.selectedUom = val;
    let masterConv = parseFloat(item.conversionRate) || 1;
    item.convRate = (item.selectedUom === 'purch') ? masterConv : 1;
    item.qty = item.rawQty * item.convRate;
    localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));
    window.renderDispatchCart();
};

window.clearDispatchCart = async function() {
    if (!window.dispatchCart || window.dispatchCart.length === 0) {
        localStorage.removeItem('takodeal_dispatch_cart'); localStorage.removeItem('takodeal_dispatch_to'); localStorage.removeItem('takodeal_active_po');
        if (typeof window.renderDispatchCart === 'function') window.renderDispatchCart(); return;
    }
    let branch = localStorage.getItem('takodeal_dispatch_to') || "Unknown Branch";
    Swal.fire({title: 'Consolidating...', text: 'Merging into a master request...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        await addDoc(collection(db, "purchase_orders"), {
            branch: branch, items: window.dispatchCart, status: "Pending", type: "Internal Request", requestedBy: "System (Merged / Set Aside)", timestamp: serverTimestamp()
        });

        const draftQ = query(collection(db, "purchase_orders"), where("branch", "==", branch), where("status", "==", "Drafting"));
        const draftSnap = await getDocs(draftQ);
        let deletePromises = [];
        draftSnap.forEach(d => { deletePromises.push(deleteDoc(doc(db, "purchase_orders", d.id))); });

        let activePos = localStorage.getItem('takodeal_active_po') || "";
        let poArray = activePos ? activePos.split(',') : [];
        for (let oldPoId of poArray) {
            if (oldPoId && oldPoId.trim() !== '') deletePromises.push(deleteDoc(doc(db, "purchase_orders", oldPoId.trim())).catch(e => {}));
        }

        await Promise.all(deletePromises);

        window.dispatchCart = []; localStorage.removeItem('takodeal_dispatch_cart'); localStorage.removeItem('takodeal_dispatch_to'); localStorage.removeItem('takodeal_active_po');
        Object.keys(localStorage).forEach(key => { if(key.startsWith('takodeal_draft_qty_')) localStorage.removeItem(key); });

        if (typeof window.renderDispatchCart === 'function') window.renderDispatchCart();
        Swal.fire({title: 'Merged!', text: 'Requests combined and old fragments permanently deleted.', icon: 'success', timer: 2000, showConfirmButton: false, customClass: { popup: 'rounded-2xl' }});
    } catch (error) { Swal.fire('Error', 'Failed to consolidate requests.', 'error'); }
};

// ========================================================
// 🚚 THE DISPATCH DELIVERY SENDER (CLEANED UP)
// ========================================================
window.submitMultiDispatch = async function () {
    let fromBranch = document.getElementById('dispFrom').value;
    let toBranch = document.getElementById('dispTo').value;

    if (!fromBranch || !toBranch) { alert("Please select Source and Destination branches."); return; }
    if (fromBranch === toBranch) { alert("Source and Destination cannot be the same."); return; }

    let btn = document.getElementById('btnSubmitDispatch');
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;

    if (isFranchisee) {
        if (window.dispatchCart.length === 0) { alert("Cart is empty."); return; }
        btn.innerText = "⏳ Sending Request..."; btn.disabled = true;
        try {
            await addDoc(collection(db, "purchase_orders"), { branch: toBranch, items: window.dispatchCart, status: "Pending", requestedBy: window.sessionUser.cashierName, timestamp: serverTimestamp() });
            Swal.fire('📝 Purchase Order Sent!', `HQ has received your request.`, 'success');
            window.dispatchCart = []; window.renderDispatchCart();
        } catch (e) { Swal.fire('Error', 'Failed to send Purchase Order.', 'error'); } 
        finally { btn.innerText = "📝 Request Stock from HQ"; btn.disabled = false; }
        return; 
    }

    for (let i = 0; i < window.dispatchCart.length; i++) {
        let inp = document.getElementById(`cartQty_${i}`);
        if (inp) {
            let val = parseFloat(inp.value) || 0;
            let conv = window.dispatchCart[i].convRate || 1;
            window.dispatchCart[i].rawQty = val; window.dispatchCart[i].qty = val * conv;
        }
    }

    let validCart = [];
    let skippedCart = []; 

    window.dispatchCart.forEach(item => {
        let sentRaw = parseFloat(item.rawQty) || 0;
        let sentBase = parseFloat(item.qty) || 0;
        
        let origRaw = parseFloat(item.origRawQty) || 0;
        let origBase = parseFloat(item.origBaseQty) || 0;

        let isAutoAlert = (item.requestType === 'Low Stock' || item.requestType === 'Out of Stock' || item.requestType === 'Emergency Override' || item.physicalStock !== undefined);

        if (sentBase > 0) validCart.push(item);

        let remainingRaw = origRaw - sentRaw;
        let remainingBase = origBase - sentBase;

        if (remainingBase > 0 || (isAutoAlert && sentBase <= 0)) {
            let badgeText = item.requestType || 'Request';
            if (badgeText === 'Delayed / Backlogged' && isAutoAlert) {
                badgeText = (item.physicalStock <= 0) ? 'Out of Stock' : 'Low Stock';
            }

            skippedCart.push({
                ...item,
                qty: isAutoAlert ? 0 : remainingBase,
                displayQty: isAutoAlert ? 0 : remainingRaw,
                rawQty: isAutoAlert ? 0 : remainingRaw,
                requestType: badgeText 
            });
        }
    });

    if (validCart.length === 0) return Swal.fire('Empty Dispatch', 'You must send a quantity greater than 0 for at least one item.', 'warning'); 

    btn.innerText = "🚀 Processing Delivery..."; btn.disabled = true;

    try {
        let driverName = prompt("Enter the name of the Delivery Driver/Person in charge:");
        if (!driverName) { btn.innerText = "🚀 Send Dispatch Delivery"; btn.disabled = false; return; }

        for (let item of validCart) {
            let itemNameToFind = item.itemName || item.name;
            let invItem = window.dispatchInventoryList.find(i => i.name === itemNameToFind);

            let sourceRef; let currentHqStock = 0;
            if (!invItem) {
                const newInvRef = await addDoc(collection(db, "inventory"), { branch: fromBranch, name: itemNameToFind, uom: item.baseUom || 'units', category: item.category || 'Ingredients', currentStock: 0, conversionRate: item.convRate || 1, purchaseUom: item.purchaseUom || 'units' });
                sourceRef = newInvRef; invItem = { id: newInvRef.id, uom: item.baseUom || 'units', category: item.category || "Ingredients", purchaseUom: item.purchaseUom || 'units', cost: item.cost || 0, reorderLevel: 10 };
            } else {
                sourceRef = doc(db, "inventory", invItem.id);
                let liveSnap = await getDoc(sourceRef);
                if (liveSnap.exists()) currentHqStock = parseFloat(liveSnap.data().currentStock) || 0;
            }

            // Deduct from HQ
            await updateDoc(sourceRef, { currentStock: currentHqStock - item.qty });

            await addDoc(collection(db, "stock_logs"), {
                branch: fromBranch, item: itemNameToFind, uom: item.baseUom || invItem.uom || 'units', oldQty: currentHqStock, newQty: currentHqStock - item.qty, variance: -item.qty,
                type: "Dispatch Delivery", note: `Sent to ${toBranch} (Driver: ${driverName})`, user: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: serverTimestamp()
            });

            await addDoc(collection(db, "stock_logs"), {
                branch: toBranch, item: itemNameToFind, uom: item.baseUom || invItem.uom || 'units', oldQty: 0, newQty: 0, variance: 0,
                type: "Incoming Dispatch", note: `Dispatched from ${fromBranch} (Driver: ${driverName}). Awaiting receipt by cashier.`, user: "System (In Transit)", timestamp: serverTimestamp()
            });

            await addDoc(collection(db, "dispatch_logs"), {
                date: new Date().toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }),
                time: new Date().toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }), timestamp: new Date(),
                item: itemNameToFind, qty: item.qty || 0, uom: item.uom || invItem.uom || 'units', 
                details: `${fromBranch} ➡️ ${toBranch}`, toBranch: toBranch, driver: driverName, status: "In Transit", 
                displayQty: item.rawQty || item.qty || 0, displayUom: item.friendlyUom || item.uom || invItem.uom || 'units', 
                convRate: item.convRate || 1, category: item.category || invItem.category || "Uncategorized"
            });
        }

        if (skippedCart.length > 0) {
            let safeSkippedCart = skippedCart.map(i => ({ ...i, category: i.category || "Uncategorized", purchaseUom: i.purchaseUom || i.uom || "units" }));
            let todayStr = new Date().toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
            
            const pendingQ = query(collection(db, "purchase_orders"), where("branch", "==", toBranch), where("status", "==", "Delayed"));
            const pendingSnap = await getDocs(pendingQ);
            
            if (!pendingSnap.empty) {
                let existingTicket = pendingSnap.docs[0]; let existingItems = existingTicket.data().items || [];
                safeSkippedCart.forEach(skippedItem => {
                    let match = existingItems.find(i => (i.itemName || i.name) === (skippedItem.itemName || skippedItem.name));
                    if (match) { match.qty = (parseFloat(match.qty) || 0) + (parseFloat(skippedItem.qty) || 0); match.displayQty = match.qty; } 
                    else { existingItems.push(skippedItem); }
                });
                await updateDoc(existingTicket.ref, { items: existingItems, timestamp: serverTimestamp() });
            } else {
                await addDoc(collection(db, "purchase_orders"), { branch: toBranch, items: safeSkippedCart, status: "Delayed", type: "Delayed Delivery", originalRequestDate: todayStr, requestedBy: "System (Postponed / Set Aside)", timestamp: serverTimestamp() });
            }
        }

        let activePoStr = localStorage.getItem('takodeal_active_po');
        if (activePoStr) {
            let poIds = activePoStr.split(',');
            for (let id of poIds) {
                if (id) { try { await deleteDoc(doc(db, "purchase_orders", id)); } catch(e){} }
            }
            localStorage.removeItem('takodeal_active_po');
        }

        window.dispatchCart = []; localStorage.removeItem('takodeal_dispatch_cart'); localStorage.removeItem('takodeal_dispatch_to');
        Object.keys(localStorage).forEach(key => { if(key.startsWith('takodeal_draft_qty_')) localStorage.removeItem(key); });

        let extraMessage = skippedCart.length > 0 ? `<br><br>(${skippedCart.length} item(s) unfulfilled were auto-set aside into the Delayed Items tab).` : '';
        
        Swal.fire({ title: '🚚 Dispatch Successful!', html: `${validCart.length} items are now In Transit to ${toBranch} via ${driverName}.${extraMessage}`, icon: 'success', customClass: { popup: 'rounded-2xl shadow-xl' } });
        
        window.renderDispatchCart(); if(typeof window.loadDispatchInventory === 'function') window.loadDispatchInventory(); 
    } catch (e) { Swal.fire('Dispatch Error', e.message || 'Check the console for details.', 'error'); } 
    finally { btn.innerText = "🚀 Send Dispatch Delivery"; btn.disabled = false; }
};

window.logisticsState = { activeBranch: 'All', activeTab: 'requests', timeFilter: 'All', requests: [], deliveries: [] };
window.poUnsubscribe = null;

window.startPOListener = function() {
    if (window.poUnsubscribe) window.poUnsubscribe(); 
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;
    let myBranch = window.sessionUser ? window.sessionUser.branch : "Unknown";

    let q = query(collection(db, "purchase_orders"), where("status", "in", ["Pending", "Delayed", "Drafting"]));
    if (isFranchisee) q = query(collection(db, "purchase_orders"), where("branch", "==", myBranch), where("status", "in", ["Pending", "Delayed", "Drafting"]));

    let initialLoad = true;
    window.poUnsubscribe = window.onSnapshot(q, (snapshot) => {
        let pendingCount = 0; let newOrderArrived = false;
        window.logisticsState.requests = [];
        snapshot.forEach(doc => {
            let data = doc.data(); window.logisticsState.requests.push({id: doc.id, ...data});
            if (data.status === 'Pending') pendingCount++;
        });
        window.logisticsState.requests.sort((a,b) => b.timestamp - a.timestamp);
        snapshot.docChanges().forEach((change) => { if (change.type === "added" && !initialLoad) newOrderArrived = true; });

        let badge = document.getElementById('poNotificationBadge');
        if (badge) { badge.innerText = pendingCount; badge.style.display = pendingCount > 0 ? 'inline-block' : 'none'; }
        window.renderLogisticsUI();

        if (newOrderArrived) {
            window.playManagerPing();
            Swal.fire({ title: '🔔 New Stock Request!', text: 'A branch just reported an inventory variance or sent a Purchase Order.', icon: 'info', toast: true, position: 'top-end', showConfirmButton: false, timer: 5000 });
        }
        initialLoad = false;
    });

    onSnapshot(collection(db, "dispatch_logs"), (snap) => {
        window.logisticsState.deliveries = [];
        snap.forEach(doc => window.logisticsState.deliveries.push({id: doc.id, ...doc.data()}));
        window.logisticsState.deliveries.sort((a,b) => b.timestamp - a.timestamp);
        window.renderLogisticsUI();
    });
};

window.switchLogisticsBranch = function(branch) { window.logisticsState.activeBranch = branch; window.renderLogisticsUI(); };
window.switchLogisticsTab = function(tab) { window.logisticsState.activeTab = tab; window.renderLogisticsUI(); };

window.renderLogisticsUI = function() {
    let reqData = window.logisticsState.requests || [];
    let delData = window.logisticsState.deliveries || [];
    
    let pendingRequests = reqData.filter(r => r.status === 'Pending' || r.status === 'Drafting');
    let delayedRequests = reqData.filter(r => r.status === 'Delayed');

    let branches = new Set(["Cabantian", "Citygate", "Maa"]);
    reqData.forEach(r => { if(r.branch) branches.add(r.branch); });
    delData.forEach(d => { if(d.toBranch) branches.add(d.toBranch); });
    
    let branchTabsHtml = `<button onclick="window.switchLogisticsBranch('All')" style="flex: 1; min-width: 100px; padding: 12px; font-weight: bold; font-size: 13px; border: none; border-bottom: 3px solid ${window.logisticsState.activeBranch === 'All' ? '#10b981' : 'transparent'}; background: ${window.logisticsState.activeBranch === 'All' ? 'white' : 'transparent'}; color: ${window.logisticsState.activeBranch === 'All' ? '#0f172a' : '#64748b'}; cursor: pointer; transition: 0.2s;">🌍 All Branches</button>`;
    
    Array.from(branches).sort().forEach(branch => {
        let branchPending = pendingRequests.filter(r => r.branch === branch).length;
        let badgeHtml = branchPending > 0 ? `<span style="background: #ef4444; color: white; padding: 2px 6px; border-radius: 10px; font-size: 10px; margin-left: 5px;">${branchPending}</span>` : '';
        let isActive = window.logisticsState.activeBranch === branch;
        branchTabsHtml += `<button onclick="window.switchLogisticsBranch('${branch}')" style="flex: 1; min-width: 120px; padding: 12px; font-weight: bold; font-size: 13px; border: none; border-bottom: 3px solid ${isActive ? '#10b981' : 'transparent'}; background: ${isActive ? 'white' : 'transparent'}; color: ${isActive ? '#0f172a' : '#64748b'}; cursor: pointer; transition: 0.2s;">📍 ${branch} ${badgeHtml}</button>`;
    });
    let branchContainer = document.getElementById('logisticsBranchTabs');
    if (branchContainer) branchContainer.innerHTML = branchTabsHtml;

    if (window.logisticsState.activeBranch !== 'All') {
        pendingRequests = pendingRequests.filter(r => r.branch === window.logisticsState.activeBranch);
        delayedRequests = delayedRequests.filter(r => r.branch === window.logisticsState.activeBranch);
        delData = delData.filter(d => d.toBranch === window.logisticsState.activeBranch);
    }

    let dispatchGroups = {};
    delData.forEach(del => {
        let groupKey = del.dispatchId || `${del.date}_${del.driver}`;
        if (!dispatchGroups[groupKey]) dispatchGroups[groupKey] = { dispatchId: groupKey, toBranch: del.toBranch, date: del.date, time: del.time, driver: del.driver, status: del.status, items: [] };
        dispatchGroups[groupKey].items.push(del);
    });

    let listContainer = document.getElementById('logisticsFeedList') || document.getElementById('dispatchLogBody')?.closest('.card');
    if (!listContainer) return;
    
    let activeTab = window.logisticsState.activeTab || 'requests';
    let tabHtml = `
        <div id="logisticsTabContainer" style="display: flex; border-bottom: 2px solid #e2e8f0; margin-bottom: 15px; background: #f8fafc; border-radius: 8px 8px 0 0; overflow: hidden;">
            <button onclick="window.switchLogisticsTab('requests')" style="flex: 1; padding: 14px; border: none; border-bottom: 3px solid ${activeTab==='requests'?'#0ea5e9':'transparent'}; background: ${activeTab==='requests'?'white':'transparent'}; font-weight: 900; color: ${activeTab==='requests'?'#0ea5e9':'#64748b'}; cursor: pointer; font-size: 13px; text-transform: uppercase; transition: 0.2s;">
                📢 Stock Requests (<span id="tabCountReq">${pendingRequests.length}</span>)
            </button>
            <button onclick="window.switchLogisticsTab('delayed')" style="flex: 1; padding: 14px; border: none; border-bottom: 3px solid ${activeTab==='delayed'?'#dc2626':'transparent'}; background: ${activeTab==='delayed'?'white':'transparent'}; font-weight: 900; color: ${activeTab==='delayed'?'#dc2626':'#64748b'}; cursor: pointer; font-size: 13px; text-transform: uppercase; transition: 0.2s; border-left: 1px solid #e2e8f0;">
                ⏳ Delayed Items (<span id="tabCountDelayed">${delayedRequests.length}</span>)
            </button>
            <button onclick="window.switchLogisticsTab('deliveries')" style="flex: 1; padding: 14px; border: none; border-bottom: 3px solid ${activeTab==='deliveries'?'#16a34a':'transparent'}; background: ${activeTab==='deliveries'?'white':'transparent'}; font-weight: 900; color: ${activeTab==='deliveries'?'#16a34a':'#64748b'}; cursor: pointer; font-size: 13px; text-transform: uppercase; transition: 0.2s; border-left: 1px solid #e2e8f0;">
                🚚 Deliveries (<span id="tabCountDel">${Object.keys(dispatchGroups).length}</span>)
            </button>
        </div>
    `;

    let bulkActionBar = `
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; padding: 10px 15px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px;">
            <label style="font-size: 14px; font-weight: bold; color: #334155; cursor: pointer; display: flex; align-items: center; gap: 10px;">
                <input type="checkbox" onclick="document.querySelectorAll('.bulk-log-cb').forEach(cb => cb.checked = this.checked)" style="width:20px; height:20px; accent-color: #0ea5e9; cursor: pointer;"> Select All
            </label>
            <button onclick="window.bulkDeleteLogistics()" style="background: #ef4444; color: white; border: none; padding: 10px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 13px; box-shadow: 0 2px 4px rgba(220,38,38,0.3); transition: 0.2s;">🗑️ Delete Selected</button>
        </div>
    `;

    let html = tabHtml;

    if (activeTab === 'requests') {
        if (pendingRequests.length === 0) { html += `<div style="text-align:center; color:#64748b; padding: 60px; font-weight: bold;">No stock requests found.</div>`; } 
        else {
            html += bulkActionBar; 
            pendingRequests.forEach(req => {
                let dateStr = req.timestamp ? req.timestamp.toDate().toLocaleString('en-US', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : 'Unknown';
                let statBadge = req.status === "Drafting" ? `<div style="font-weight: bold; font-size: 13px; color: #0369a1; background: #bae6fd; padding: 4px 8px; border-radius: 6px;">Drafting in Cart</div>` : `<div style="font-weight: bold; font-size: 13px; color: #d97706; background: #fef3c7; padding: 4px 8px; border-radius: 6px;">Pending</div>`;

                html += `
                    <div style="background: white; border: 1px solid #e2e8f0; border-radius: 8px; padding: 15px; margin-bottom: 15px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); display: flex; justify-content: space-between; align-items: center;">
                        <div style="display: flex; gap: 15px; align-items: center;">
                            <input type="checkbox" class="bulk-log-cb" value="${req.id}" style="width:22px; height:22px; accent-color: #0ea5e9; cursor: pointer;">
                            <div>
                                <h3 style="margin: 0 0 5px 0; color: #b45309; font-size: 16px;">📢 Stock Request from ${req.branch}</h3>
                                <div style="font-size: 13px; color: #92400e; font-weight: 500;">Requested by: ${req.requestedBy || 'Staff'}</div>
                                <div style="font-size: 11px; color: #64748b; margin-top: 5px;">📅 ${dateStr} • <strong>${req.items ? req.items.length : 0} items</strong></div>
                            </div>
                        </div>
                        <div style="display: flex; gap: 10px; align-items: center;">
                            ${statBadge}
                            <button onclick="if(typeof window.reviewStockRequest === 'function') window.reviewStockRequest('${req.id}')" style="background: #0ea5e9; color: white; border: none; padding: 10px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; box-shadow: 0 4px 6px rgba(14,165,233,0.3); transition: 0.2s;">🔍 Review Request</button>
                        </div>
                    </div>
                `;
            });
        }
    } else if (activeTab === 'delayed') {
        if (delayedRequests.length === 0) { html += `<div style="text-align:center; color:#64748b; padding: 60px; font-weight: bold;">No delayed or backlogged items.</div>`; } 
        else {
            html += bulkActionBar; 
            delayedRequests.forEach(req => {
                let dateStr = req.timestamp ? req.timestamp.toDate().toLocaleString('en-US', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : 'Unknown';
                let origDate = req.originalRequestDate || dateStr;

                html += `
                    <div style="background: #fff1f2; border: 1px solid #fca5a5; border-radius: 8px; padding: 15px; margin-bottom: 15px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); display: flex; justify-content: space-between; align-items: center;">
                        <div style="display: flex; gap: 15px; align-items: center;">
                            <input type="checkbox" class="bulk-log-cb" value="${req.id}" style="width:22px; height:22px; accent-color: #0ea5e9; cursor: pointer;">
                            <div>
                                <h3 style="margin: 0 0 5px 0; color: #b91c1c; font-size: 16px;">⏳ Delayed Items for ${req.branch}</h3>
                                <div style="font-size: 11px; color: #ef4444; font-weight: bold;">Originally Requested: ${origDate}</div>
                                <div style="font-size: 11px; color: #64748b; margin-top: 5px;">📅 Set Aside: ${dateStr} • <strong>${req.items ? req.items.length : 0} items</strong></div>
                            </div>
                        </div>
                        <div style="display: flex; gap: 10px; align-items: center;">
                            <button onclick="if(typeof window.reviewStockRequest === 'function') window.reviewStockRequest('${req.id}')" style="background: #ef4444; color: white; border: none; padding: 10px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; box-shadow: 0 4px 6px rgba(220, 38, 38, 0.3); transition: 0.2s;">🛒 Load to Cart</button>
                        </div>
                    </div>
                `;
            });
        }
    } else {
        if (Object.keys(dispatchGroups).length === 0) { html += `<div style="text-align:center; color:#64748b; padding: 60px; font-weight: bold;">No deliveries found.</div>`; } 
        else {
            html += bulkActionBar; 
            for (let key in dispatchGroups) {
                let group = dispatchGroups[key];
                let hasMissing = group.items.some(i => i.status === 'Lost in Transit' || i.status === 'Discrepancy');
                let allReceived = group.items.every(i => i.status === 'Received');
                
                // Upgraded Status Logic to handle Delayed/Loadback items!
                let hasDelayed = group.items.some(i => i.status === 'Delayed' || i.status === 'Loadback' || i.status === 'Partial');
                let hasInTransit = group.items.some(i => i.status === 'In Transit');
                let hasArrived = group.items.some(i => i.status === 'Arrived');
                
                let overallStatus = 'In Transit';
                
                // If the branch has fully processed it, there are no 'In Transit' or 'Arrived' statuses left.
                if (!hasInTransit && !hasArrived) {
                    if (hasMissing) overallStatus = 'Discrepancy / Lost';
                    else if (hasDelayed) overallStatus = 'Partial (Delayed)';
                    else if (allReceived) overallStatus = 'Received';
                    else overallStatus = 'Received'; // Safe fallback
                } else if (hasArrived && !hasInTransit) {
                    overallStatus = 'Arrived at Branch';
                } else {
                    overallStatus = 'In Transit';
                }
        
                let statCol = '#0ea5e9'; // Default Blue
                if (overallStatus === 'Received') statCol = '#16a34a'; // Green
                else if (overallStatus === 'Arrived at Branch') statCol = '#8b5cf6'; // Purple
                else if (overallStatus === 'Partial (Delayed)') statCol = '#d97706'; // Orange
                else if (overallStatus === 'Discrepancy / Lost') statCol = '#dc2626'; // Red
        
                let encodedGroup = encodeURIComponent(JSON.stringify(group));
                let groupFirebaseIds = group.items.map(i => i.id).join(',');
        
                let actionButtons = '';
                if (overallStatus === 'In Transit') {
                    actionButtons = `<button onclick="window.markDispatchArrived('${encodedGroup}')" style="background: #8b5cf6; color: white; border: none; padding: 8px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; transition: 0.2s;">📍 Mark Arrived</button>`;
                }

                html += `
                    <div style="background: white; border: 1px solid #e2e8f0; border-radius: 8px; padding: 15px; margin-bottom: 15px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); display: flex; justify-content: space-between; align-items: center;">
                        <div style="display: flex; gap: 15px; align-items: center;">
                            <input type="checkbox" class="bulk-log-cb" value="${groupFirebaseIds}" style="width:22px; height:22px; accent-color: #0ea5e9; cursor: pointer;">
                            <div>
                                <h3 style="margin: 0 0 5px 0; color: #0f172a; font-size: 16px;">📍 To: ${group.toBranch}</h3>
                                <div style="font-size: 13px; color: #475569; font-weight: 500;">🚚 Driver: ${group.driver || 'Unknown'}</div>
                                <div style="font-size: 11px; color: #64748b; margin-top: 5px;">📅 ${group.date} at ${group.time} • <strong>${group.items.length} items</strong></div>
                            </div>
                        </div>
                        <div style="display: flex; gap: 10px; align-items: center;">
                            <div style="background: ${statCol}; color: white; padding: 8px 12px; border-radius: 6px; font-size: 12px; font-weight: bold;">${overallStatus}</div>
                            ${actionButtons}
                            <button onclick="window.viewDeliveryDetails('${encodedGroup}')" style="background: white; color: #0ea5e9; border: 1px solid #bae6fd; padding: 8px 15px; border-radius: 6px; font-weight: bold; cursor: pointer; transition: 0.2s;">🔍 Full Details</button>
                        </div>
                    </div>
                `;
            }
        }
    }
    // Ensures we wipe out the old table logic completely!
    if (listContainer.tagName === 'TBODY') {
        let card = listContainer.closest('.card');
        card.innerHTML = html;
        card.id = 'logisticsFeedList';
    } else {
        listContainer.innerHTML = html;
    }
};

window.submitMultiDispatch = async function () {
    let fromBranch = document.getElementById('dispFrom').value;
    let toBranch = document.getElementById('dispTo').value;

    if (!fromBranch || !toBranch) { alert("Please select Source and Destination branches."); return; }
    if (fromBranch === toBranch) { alert("Source and Destination cannot be the same."); return; }

    let btn = document.getElementById('btnSubmitDispatch');
    let isFranchisee = window.sessionUser && window.sessionUser.isFranchisee;

    if (isFranchisee) {
        if (window.dispatchCart.length === 0) { alert("Cart is empty."); return; }
        btn.innerText = "⏳ Sending Request..."; btn.disabled = true;
        try {
            await addDoc(collection(db, "purchase_orders"), { branch: toBranch, items: window.dispatchCart, status: "Pending", requestedBy: window.sessionUser.cashierName, timestamp: serverTimestamp() });
            Swal.fire('📝 Purchase Order Sent!', `HQ has received your request.`, 'success');
            window.dispatchCart = []; window.renderDispatchCart();
        } catch (e) { Swal.fire('Error', 'Failed to send Purchase Order.', 'error'); } 
        finally { btn.innerText = "📝 Request Stock from HQ"; btn.disabled = false; }
        return; 
    }

    for (let i = 0; i < window.dispatchCart.length; i++) {
        let inp = document.getElementById(`cartQty_${i}`);
        if (inp) {
            let val = parseFloat(inp.value) || 0;
            let conv = window.dispatchCart[i].convRate || 1;
            window.dispatchCart[i].rawQty = val; window.dispatchCart[i].qty = val * conv;
        }
    }

    let validCart = [];
    let skippedCart = []; 

    window.dispatchCart.forEach(item => {
        let sentRaw = parseFloat(item.rawQty) || 0;
        let sentBase = parseFloat(item.qty) || 0;
        
        let origRaw = parseFloat(item.origRawQty) || 0;
        let origBase = parseFloat(item.origBaseQty) || 0;

        let isAutoAlert = (item.requestType === 'Low Stock' || item.requestType === 'Out of Stock' || item.physicalStock !== undefined);

        if (sentBase > 0) validCart.push(item);

        let remainingRaw = origRaw - sentRaw;
        let remainingBase = origBase - sentBase;

        // 🔥 THE LOGIC FIX: If it's an auto-alert and you sent 0, OR if there's unfulfilled requested stock, send to Delayed!
        if (remainingBase > 0 || (isAutoAlert && sentBase <= 0)) {
            
            // Resurrect the original badge text so it doesn't get corrupted
            let badgeText = item.requestType || 'Request';
            if (badgeText === 'Delayed / Backlogged' && isAudit) {
                badgeText = (item.physicalStock <= 0) ? 'Out of Stock' : 'Low Stock';
            }

            skippedCart.push({
                ...item,
                qty: isAutoAlert ? 0 : remainingBase,
                displayQty: isAutoAlert ? 0 : remainingRaw,
                rawQty: isAutoAlert ? 0 : remainingRaw,
                requestType: badgeText // PROTECT the original badge!
            });
        }
    });

    if (validCart.length === 0) return Swal.fire('Empty Dispatch', 'You must send a quantity greater than 0 for at least one item.', 'warning'); 

    btn.innerText = "🚀 Processing Delivery & Audits..."; btn.disabled = true;

    try {
        let driverName = prompt("Enter the name of the Delivery Driver/Person in charge:");
        if (!driverName) { btn.innerText = "🚀 Send Dispatch Delivery"; btn.disabled = false; return; }

        let totalPenaltiesIssued = 0;

        for (let item of validCart) {
            let itemNameToFind = item.itemName || item.name;
            let invItem = window.dispatchInventoryList.find(i => i.name === itemNameToFind);

            let sourceRef; let currentHqStock = 0;
            if (!invItem) {
                const newInvRef = await addDoc(collection(db, "inventory"), { branch: fromBranch, name: itemNameToFind, uom: item.baseUom || 'units', category: item.category || 'Ingredients', currentStock: 0, conversionRate: item.convRate || 1, purchaseUom: item.purchaseUom || 'units' });
                sourceRef = newInvRef; invItem = { id: newInvRef.id, uom: item.baseUom || 'units', category: item.category || "Ingredients", purchaseUom: item.purchaseUom || 'units', cost: item.cost || 0, reorderLevel: 10 };
            } else {
                sourceRef = doc(db, "inventory", invItem.id);
                let liveSnap = await getDoc(sourceRef);
                if (liveSnap.exists()) currentHqStock = parseFloat(liveSnap.data().currentStock) || 0;
            }

            await updateDoc(sourceRef, { currentStock: currentHqStock - item.qty });

            await addDoc(collection(db, "stock_logs"), {
                branch: fromBranch, item: itemNameToFind, uom: item.baseUom || invItem.uom || 'units', oldQty: currentHqStock, newQty: currentHqStock - item.qty, variance: -item.qty,
                type: "Dispatch Delivery", note: `Sent to ${toBranch} (Driver: ${driverName})`, user: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: serverTimestamp()
            });

            await addDoc(collection(db, "stock_logs"), {
                branch: toBranch, item: itemNameToFind, uom: item.baseUom || invItem.uom || 'units', oldQty: 0, newQty: 0, variance: 0,
                type: "Incoming Dispatch", note: `Dispatched from ${fromBranch} (Driver: ${driverName}). Awaiting receipt by cashier.`, user: "System (In Transit)", timestamp: serverTimestamp()
            });

            if (item.requestType === "Low Stock" || item.requestType === "Out of Stock" || item.physicalStock !== undefined) {
                const branchInvQ = query(collection(db, "inventory"), where("branch", "==", toBranch), where("name", "==", itemNameToFind));
                const branchInvSnap = await getDocs(branchInvQ);
                
                if (!branchInvSnap.empty) {
                    let bDoc = branchInvSnap.docs[0]; let bData = bDoc.data();
                    let sysStock = parseFloat(bData.currentStock) || 0; let physStock = parseFloat(item.physicalStock) || 0;

                    if (sysStock > 0 && physStock < sysStock) {
                        let missingQty = sysStock - physStock;
                        let costPerUnit = parseFloat(bData.baseCost) || parseFloat(bData.cost) || parseFloat(item.cost) || 0;
                        let penaltyValue = missingQty * costPerUnit;

                        await updateDoc(bDoc.ref, { currentStock: physStock });
                        await addDoc(collection(db, "stock_logs"), { branch: toBranch, item: itemNameToFind, uom: bData.uom || 'units', oldQty: sysStock, newQty: physStock, variance: -missingQty, type: "Audit Adjustment (Penalty)", note: `System expected ${sysStock.toFixed(2)}, staff reported ${physStock.toFixed(2)}.`, user: "System (HQ)", timestamp: serverTimestamp() });

                        if (penaltyValue > 0) {
                            await addDoc(collection(db, "staff_deductions"), { staffName: `Team ${toBranch}`, type: "Missing Stock Penalty", amount: penaltyValue, dateAdded: new Date(), status: "Unpaid", remarks: `Missing ${missingQty.toFixed(2)} ${bData.uom} of ${itemNameToFind} before restock.` });
                            await addDoc(collection(db, "manager_alerts"), { type: "STOCK_PENALTY_APPLIED", branch: toBranch, cashier: "Team", message: `🚨 PENALTY APPLIED: ${itemNameToFind} baseline reset to ${physStock}. ₱${penaltyValue.toFixed(2)} penalty issued to Team ${toBranch}.`, timestamp: serverTimestamp(), isRead: false });
                            totalPenaltiesIssued++;
                        }
                    } 
                    else if (sysStock <= 0) {
                        await updateDoc(bDoc.ref, { currentStock: physStock });
                        await addDoc(collection(db, "stock_logs"), { branch: toBranch, item: itemNameToFind, uom: bData.uom || 'units', oldQty: sysStock, newQty: physStock, variance: physStock - sysStock, type: "Negative Stock Wipe", note: `Clean slate reset before restock.`, user: "System (HQ)", timestamp: serverTimestamp() });
                    }
                }
            }

            await addDoc(collection(db, "dispatch_logs"), {
                date: new Date().toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }),
                time: new Date().toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }), timestamp: new Date(),
                item: itemNameToFind, qty: item.qty || 0, uom: item.uom || invItem.uom || 'units', 
                details: `${fromBranch} ➡️ ${toBranch}`, toBranch: toBranch, driver: driverName, status: "In Transit", 
                displayQty: item.rawQty || item.qty || 0, displayUom: item.friendlyUom || item.uom || invItem.uom || 'units', 
                convRate: item.convRate || 1, category: item.category || invItem.category || "Uncategorized"
            });
        }

        if (skippedCart.length > 0) {
            let safeSkippedCart = skippedCart.map(i => ({ ...i, category: i.category || "Uncategorized", purchaseUom: i.purchaseUom || i.uom || "units" }));
            let todayStr = new Date().toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
            
            const pendingQ = query(collection(db, "purchase_orders"), where("branch", "==", toBranch), where("status", "==", "Delayed"));
            const pendingSnap = await getDocs(pendingQ);
            
            if (!pendingSnap.empty) {
                let existingTicket = pendingSnap.docs[0]; let existingItems = existingTicket.data().items || [];
                safeSkippedCart.forEach(skippedItem => {
                    let match = existingItems.find(i => (i.itemName || i.name) === (skippedItem.itemName || skippedItem.name));
                    if (match) { match.qty = (parseFloat(match.qty) || 0) + (parseFloat(skippedItem.qty) || 0); match.displayQty = match.qty; } 
                    else { existingItems.push(skippedItem); }
                });
                await updateDoc(existingTicket.ref, { items: existingItems, timestamp: serverTimestamp() });
            } else {
                await addDoc(collection(db, "purchase_orders"), { branch: toBranch, items: safeSkippedCart, status: "Delayed", type: "Delayed Delivery", originalRequestDate: todayStr, requestedBy: "System (Postponed / Set Aside)", timestamp: serverTimestamp() });
            }
        }

        let activePoStr = localStorage.getItem('takodeal_active_po');
        if (activePoStr) {
            let poIds = activePoStr.split(',');
            for (let id of poIds) {
                if (id) {
                    try { await deleteDoc(doc(db, "purchase_orders", id)); } catch(e){}
                }
            }
            localStorage.removeItem('takodeal_active_po');
        }

        window.dispatchCart = []; localStorage.removeItem('takodeal_dispatch_cart'); localStorage.removeItem('takodeal_dispatch_to');
        Object.keys(localStorage).forEach(key => { if(key.startsWith('takodeal_draft_qty_')) localStorage.removeItem(key); });

        let extraMessage = skippedCart.length > 0 ? `<br><br>(${skippedCart.length} item(s) unfulfilled were auto-set aside into the Delayed Items tab).` : '';
        let penaltyMessage = totalPenaltiesIssued > 0 ? `<br><br>🚨 <b>${totalPenaltiesIssued} Penalty Deduction(s)</b> automatically issued to Team ${toBranch} for missing stock!` : '';
        
        Swal.fire({ title: '🚚 Dispatch Successful!', html: `${validCart.length} items are now In Transit to ${toBranch} via ${driverName}.${penaltyMessage}${extraMessage}`, icon: 'success', customClass: { popup: 'rounded-2xl shadow-xl' } });
        
        window.renderDispatchCart(); if(typeof window.loadDispatchInventory === 'function') window.loadDispatchInventory(); 
    } catch (e) { Swal.fire('Dispatch Error', e.message || 'Check the console for details.', 'error'); } 
    finally { btn.innerText = "🚀 Send Dispatch Delivery"; btn.disabled = false; }
};

window.viewDeliveryDetails = function(encodedGroup) {
    let group = JSON.parse(decodeURIComponent(encodedGroup));
    
    let arrivedTimeStr = '<span style="color:#ef4444; font-style:italic;">Pending</span>';
    let arrivedItem = group.items.find(i => i.arrivedAt);
    if (arrivedItem && arrivedItem.arrivedAt) {
        let aDate = arrivedItem.arrivedAt.seconds ? new Date(arrivedItem.arrivedAt.seconds * 1000) : new Date(arrivedItem.arrivedAt);
        arrivedTimeStr = aDate.toLocaleDateString('en-PH', { month: 'short', day: 'numeric' }) + ' ' + aDate.toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' });
    }

    let receiverName = '<span style="color:#ef4444; font-style:italic;">Pending</span>';
    let receivedTimeStr = '<span style="color:#ef4444; font-style:italic;">Pending</span>';
    let receivedItem = group.items.find(i => i.receivedBy);
    if (receivedItem) {
        receiverName = receivedItem.receivedBy;
        if (receivedItem.receivedAt) {
            let rDate = receivedItem.receivedAt.seconds ? new Date(receivedItem.receivedAt.seconds * 1000) : new Date(receivedItem.receivedAt);
            receivedTimeStr = rDate.toLocaleDateString('en-PH', { month: 'short', day: 'numeric' }) + ' ' + rDate.toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' });
        }
    }

    let headerEl = document.getElementById('dispatchDetailsHeader');
    if(headerEl) {
        headerEl.innerHTML = `
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
                <div style="border-right: 1px dashed #cbd5e1; padding-right: 15px;">
                    <div style="font-size: 11px; color: #64748b; font-weight: bold; text-transform: uppercase;">Dispatch Info</div>
                    <div style="margin-top: 5px; color: #0f172a; font-size: 15px;"><strong>📍 To:</strong> ${group.toBranch}</div>
                    <div style="margin-top: 5px; color: #334155;"><strong>🚚 Driver:</strong> ${group.driver}</div>
                    <div style="margin-top: 5px; color: #475569; font-size: 12px;"><strong>📅 Sent:</strong> ${group.date} at ${group.time}</div>
                </div>
                <div>
                    <div style="font-size: 11px; color: #0f766e; font-weight: bold; text-transform: uppercase;">Receiving Info</div>
                    <div style="margin-top: 5px;"><strong>👤 Received By:</strong> <span style="color: #0f766e; font-weight: bold;">${receiverName}</span></div>
                    <div style="margin-top: 5px; color: #475569;"><strong>📍 Arrived at Branch:</strong> ${arrivedTimeStr}</div>
                    <div style="margin-top: 5px; color: #475569;"><strong>✅ Confirmed Received:</strong> ${receivedTimeStr}</div>
                </div>
            </div>
        `;
    }
    
    let tbody = document.getElementById('dispatchDetailsBody');
    let html = '';
    let canRecall = true; let hasMissing = false; 
    
    group.items.forEach(item => {
        if (item.status !== 'In Transit') canRecall = false;
        if (item.status === 'Lost in Transit' || item.status === 'Discrepancy') hasMissing = true;

        let statColor = item.status === 'Received' ? '#16a34a' : (item.status === 'In Transit' ? '#0ea5e9' : (item.status === 'Arrived' ? '#8b5cf6' : '#dc2626'));
        let varText = item.variance ? `<span style="color:#dc2626; font-weight:bold;">${item.variance} ${item.uom}</span>` : `<span style="color:#94a3b8;">0</span>`;
        let receivedQty = item.receivedDisplayQty !== undefined ? item.receivedDisplayQty : (item.status === 'In Transit' || item.status === 'Arrived' ? '---' : 0);
        let expectedQty = item.displayQty || item.qty;
        let displayUom = item.displayUom || item.uom;

        let remarksHtml = item.receivingRemarks ? `<div style="font-size:11px; color:#ef4444; margin-top:4px; font-style:italic;">Reason: ${item.receivingRemarks}</div>` : '';
        
        html += `
            <tr style="border-bottom: 1px solid #e2e8f0;">
                <td style="padding:12px; font-weight:bold; color:#334155;">${item.item}</td>
                <td style="padding:12px; font-weight:bold; color:#0f172a; text-align:center;">${expectedQty} <span style="font-size:11px; color:#64748b;">${displayUom}</span></td>
                <td style="padding:12px; font-weight:bold; color:#0ea5e9; text-align:center;">${receivedQty} <span style="font-size:11px; color:#64748b;">${displayUom}</span></td>
                <td style="padding:12px; text-align:center;">${varText}</td>
                <td style="padding:12px; text-align:center;">
                    <span style="background:${statColor}15; color:${statColor}; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold; border: 1px solid ${statColor}50;">${item.status}</span>
                    ${remarksHtml}
                </td>
            </tr>
        `;
    });
    
    if(tbody) tbody.innerHTML = html;

    let footerEl = document.getElementById('dispatchDetailsFooter');
    if (footerEl) {
        footerEl.innerHTML = '';
        if (canRecall) { footerEl.innerHTML += `<button onclick="window.recallDispatch('${encodedGroup}')" style="background: #f59e0b; color: white; border: none; padding: 12px 20px; border-radius: 6px; font-weight: bold; cursor: pointer; box-shadow: 0 4px 6px rgba(245, 158, 11, 0.3); font-size: 14px; transition: 0.2s; width: 100%; margin-bottom: 10px;">🔙 Back Load / Recall Dispatch</button>`; } 
        if (hasMissing) { footerEl.innerHTML += `<button onclick="window.resolveMissingDispatchItems('${encodedGroup}')" style="background: #dc2626; color: white; border: none; padding: 12px 20px; border-radius: 6px; font-weight: bold; cursor: pointer; box-shadow: 0 4px 6px rgba(220, 38, 38, 0.3); font-size: 14px; transition: 0.2s; width: 100%;">🕵️ Resolve Missing Items</button>`; }
        if (!canRecall && !hasMissing) { footerEl.innerHTML = `<span style="font-size: 12px; color: #64748b; font-weight: bold; background: #e2e8f0; padding: 8px 15px; border-radius: 6px; display: block; text-align: center;">🔒 This delivery has been fully processed by the branch.</span>`; }
    }

    document.getElementById('dispatchDetailsModal').style.display = 'flex';
};

window.markDispatchArrived = async function(encodedGroup) {
    let group = JSON.parse(decodeURIComponent(encodedGroup));
    if (!confirm(`Mark delivery to ${group.toBranch} as ARRIVED?\n\nThe branch staff will now be notified and can begin receiving the items.`)) return;

    Swal.fire({title: 'Updating Status...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        let promises = [];
        group.items.forEach(item => {
            if (item.status === 'In Transit') promises.push(updateDoc(doc(db, "dispatch_logs", item.id), { status: 'Arrived', arrivedAt: serverTimestamp() }));
        });
        await Promise.all(promises);
        Swal.fire('Arrived!', 'Delivery marked as arrived at the branch.', 'success');
    } catch (e) { console.error(e); Swal.fire('Error', 'Failed to update status.', 'error'); }
};

window.resolveMissingDispatchItems = async function(encodedGroup) {
    let group = JSON.parse(decodeURIComponent(encodedGroup));
    let lostItems = group.items.filter(i => i.status === 'Lost in Transit' || i.status === 'Discrepancy');
    
    if (lostItems.length === 0) return;

    let itemsListHtml = lostItems.map(i => `<li style="margin-bottom: 5px;"><b>${i.item}</b>: Missing <b style="color:#dc2626;">${Math.abs(parseFloat(i.variance) || 0)} ${i.uom}</b></li>`).join('');

    const { value: action } = await Swal.fire({
        title: '🕵️ Resolve Missing Items',
        html: `
            <div style="text-align: left; font-size: 13px; color: #334155; margin-bottom: 15px;">
                The cashier at <b>${group.toBranch}</b> reported receiving less than what was sent. Please double check with the driver. What happened to these items?
                <ul style="margin-top: 10px; color: #0f172a; background: #f8fafc; padding: 10px 10px 10px 25px; border-radius: 6px; border: 1px solid #e2e8f0;">
                    ${itemsListHtml}
                </ul>
            </div>
        `,
        input: 'radio',
        inputOptions: {
            'return': '📦 The driver brought them back (Return to HQ Inventory)',
            'requeue': '🔄 They were genuinely lost/forgotten (Re-queue as a Stock Request)'
        },
        inputValidator: (value) => {
            if (!value) { return 'You need to select an action!'; }
        },
        showCancelButton: true,
        confirmButtonText: 'Confirm Resolution',
        confirmButtonColor: '#0ea5e9',
        customClass: { popup: 'rounded-2xl shadow-xl' }
    });

    if (!action) return;

    Swal.fire({title: 'Processing Resolution...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        if (action === 'return') {
            // 1. Return to HQ Inventory Safely
            for (let item of lostItems) {
                let varianceQty = Math.abs(parseFloat(item.variance) || 0);
                let originBranch = item.fromBranch || "Main Office";
                
                const invQ = query(collection(db, "inventory"), where("branch", "==", originBranch), where("name", "==", item.item));
                const invSnap = await getDocs(invQ);
                
                if (!invSnap.empty) {
                    let invDoc = invSnap.docs[0];
                    let currentStock = parseFloat(invDoc.data().currentStock) || 0;
                    await updateDoc(invDoc.ref, { currentStock: currentStock + varianceQty });
                    
                    // Trace Log for Security
                    await addDoc(collection(db, "stock_logs"), {
                        branch: originBranch, item: item.item, uom: item.baseUom || item.uom,
                        oldQty: currentStock, newQty: currentStock + varianceQty, variance: varianceQty,
                        type: "Dispatch Returned (Backload)", note: `Items bounced from ${group.toBranch} and returned to HQ.`,
                        user: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: serverTimestamp()
                    });
                }
                // Mark Dispatch as cleared
                await updateDoc(doc(db, "dispatch_logs", item.id), { status: 'Returned to HQ' });
            }
            Swal.fire('✅ Returned to HQ', 'The missing items have been successfully returned to your Main Office inventory.', 'success');
        } 
        else if (action === 'requeue') {
            // 2. Re-queue as a Stock Request
            let poItems = lostItems.map(item => {
                let varianceQty = Math.abs(parseFloat(item.variance) || 0);
                let cRate = parseFloat(item.convRate) || 1;
                let displayQty = varianceQty / cRate; 
                return { itemName: item.item, name: item.item, qty: varianceQty, displayQty: displayQty, uom: item.baseUom || item.uom, displayUom: item.displayUom || item.purchaseUom || item.uom, requestType: 'Lost in Transit', physicalStock: 0, systemStock: 0 };
            });

            await addDoc(collection(db, "purchase_orders"), { branch: group.toBranch, items: poItems, status: "Pending", type: "Lost Item Replacement", requestedBy: "System (HQ Resolved)", timestamp: serverTimestamp() });

            for (let item of lostItems) {
                await updateDoc(doc(db, "dispatch_logs", item.id), { status: 'Lost (Re-queued)' });
            }
            Swal.fire('✅ Re-Queued', 'Lost items have been instantly sent to the Stock Requests feed so you can dispatch them again.', 'success');
        }

        document.getElementById('dispatchDetailsModal').style.display = 'none';
        if (typeof window.loadDispatchLogs === 'function') window.loadDispatchLogs();

    } catch (e) {
        console.error("Resolution Error:", e);
        Swal.fire('Error', 'Failed to resolve items. Check console.', 'error');
    }
};

window.recallDispatch = async function(encodedGroup) {
    let group = JSON.parse(decodeURIComponent(encodedGroup));
    if (!confirm("⚠️ RECALL DISPATCH?\n\nThis will remove the delivery from the destination branch, refund the inventory back to HQ, and load the items into your Dispatch Cart to edit. Proceed?")) return;

    Swal.fire({title: 'Recalling Delivery...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        if (typeof window.dispatchCart === 'undefined') window.dispatchCart = [];
        let branchSelect = document.getElementById('dispTo');
        if(branchSelect) branchSelect.value = group.toBranch;

        for (let item of group.items) {
            let originBranch = item.fromBranch || "Main Office";
            const invQ = query(collection(db, "inventory"), where("branch", "==", originBranch), where("name", "==", item.item));
            const invSnap = await getDocs(invQ);
            
            if (!invSnap.empty) {
                let invDoc = invSnap.docs[0];
                let currentStock = parseFloat(invDoc.data().currentStock) || 0;
                let refundQty = parseFloat(item.qty) || 0; 
                
                await updateDoc(invDoc.ref, { currentStock: currentStock + refundQty });
                await addDoc(collection(db, "stock_logs"), { branch: originBranch, item: item.item, oldQty: currentStock, newQty: currentStock + refundQty, variance: refundQty, type: "Dispatch Recalled", note: `Recalled delivery originally sent to ${group.toBranch}`, user: localStorage.getItem('cashierName') || 'Manager', timestamp: serverTimestamp() });
            }

            window.dispatchCart.push({
                id: item.sourceId || item.id, sourceId: item.sourceId || item.id, itemName: item.item, name: item.item,
                rawQty: parseFloat(item.displayQty) || parseFloat(item.qty) || 0, qty: parseFloat(item.qty) || 0,
                uom: item.baseUom || item.uom, baseUom: item.baseUom || item.uom, friendlyUom: item.displayUom || item.uom,
                purchaseUom: item.purchaseUom || item.displayUom || item.uom, selectedUom: (item.displayUom !== item.uom) ? 'purch' : 'base',
                convRate: parseFloat(item.convRate) || 1, conversionRate: parseFloat(item.convRate) || 1, category: item.category || "Ingredients"
            });

            await deleteDoc(doc(db, "dispatch_logs", item.id));
        }

        localStorage.setItem('takodeal_dispatch_cart', JSON.stringify(window.dispatchCart));

        if (typeof window.renderDispatchCart === 'function') window.renderDispatchCart();
        if (typeof window.switchView === 'function') window.switchView('dispatch');
        
        document.getElementById('dispatchDetailsModal').style.display = 'none';
        Swal.fire({title: 'Recalled!', text: 'Dispatch reverted. Items are back in your Dispatch Cart.', icon: 'success', timer: 2500, showConfirmButton: false});

    } catch (e) { console.error(e); Swal.fire('Error', 'Failed to recall dispatch.', 'error'); }
};

window.bulkDeleteLogistics = async function() {
    let checkboxes = document.querySelectorAll('.bulk-log-cb:checked');
    if (checkboxes.length === 0) return Swal.fire('No Items Selected', 'Please check the boxes of the items you want to delete.', 'info');

    let isRequests = window.logisticsState.activeTab !== 'deliveries';
    let targetType = isRequests ? `stock requests` : `deliveries`;

    let confirmDelete = await Swal.fire({ title: 'Bulk Delete?', text: `Are you sure you want to permanently delete ${checkboxes.length} ${targetType}? This cannot be undone.`, icon: 'warning', showCancelButton: true, confirmButtonColor: '#dc2626', cancelButtonColor: '#64748b', confirmButtonText: 'Yes, Delete All!', customClass: { popup: 'rounded-2xl shadow-xl' }});
    if (!confirmDelete.isConfirmed) return;

    Swal.fire({title: 'Erasing Data...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        let promises = [];
        checkboxes.forEach(cb => {
            if (isRequests) {
                promises.push(deleteDoc(doc(db, "purchase_orders", cb.value)));
            } else {
                let ids = cb.value.split(',');
                ids.forEach(id => { if (id) promises.push(deleteDoc(doc(db, "dispatch_logs", id))); });
            }
        });

        await Promise.all(promises);
        Swal.fire({ title: 'Deleted!', text: 'Selected items have been permanently deleted.', icon: 'success', timer: 1500, showConfirmButton: false, customClass: { popup: 'rounded-2xl' } });
    } catch (e) { console.error("Bulk Delete Error:", e); Swal.fire('Error', 'Failed to delete selected items.', 'error'); }
};

window.deleteDeliveryGroup = async function(encodedGroup) {
    let group = JSON.parse(decodeURIComponent(encodedGroup));
    if (!confirm(`⚠️ Are you sure you want to permanently delete the delivery to ${group.toBranch}?\n\nThis will instantly remove all items inside it from the system.`)) return;

    Swal.fire({title: 'Deleting...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        let promises = [];
        group.items.forEach(item => { promises.push(deleteDoc(doc(db, "dispatch_logs", item.id))); });
        await Promise.all(promises);

        Swal.fire({title: 'Deleted!', text: 'Delivery deleted successfully.', icon: 'success', timer: 1500, showConfirmButton: false});
    } catch(e) { console.error(e); Swal.fire('Error', 'Failed to delete delivery.', 'error'); }
};

// Auto-start the new Logistics engine
setTimeout(() => { if (typeof window.startPOListener === 'function') window.startPOListener(); }, 1500);

// 🟢 NEW: Updates the dropdown to show "Packs" vs "grams" based on the item
window.updateDispatchUomLabel = async function() {
    let itemName = document.getElementById('dispItem').value.trim();
    let uomDrop = document.getElementById('dispUomSelect');
    let toBranch = document.getElementById('dispTo').value;

    let aiContainer = document.getElementById('dispAiTracker');
    if (!aiContainer) {
        let qtyContainer = document.getElementById('dispQty').parentElement.parentElement;
        qtyContainer.insertAdjacentHTML('afterend', `<div id="dispAiTracker" style="width: 100%; margin-top: 10px; flex-basis: 100%;"></div>`);
        aiContainer = document.getElementById('dispAiTracker');
    }

    // 1. If NO ITEM is typed at all, clear everything
    if (!itemName) { 
        uomDrop.innerHTML = '<option value="base">Units</option>'; 
        if(aiContainer) aiContainer.innerHTML = '';
        return; 
    }

    // 🔥 THE FIX: Always load the proper Units, even if the destination branch is blank!
    let invItem = window.dispatchInventoryList.find(i => i.name === itemName);
    if (invItem) {
        let baseUom = invItem.uom || 'units'; 
        let purchUom = invItem.purchaseUom || 'Bulk';
        
        // Prevent duplicate unit names if purchase and base are the same
        if (baseUom.toLowerCase() !== purchUom.toLowerCase()) {
            uomDrop.innerHTML = `<option value="purch">${purchUom}</option><option value="base">${baseUom}</option>`;
        } else {
            uomDrop.innerHTML = `<option value="base">${baseUom}</option>`;
        }
    }

    // 🛑 HALT the AI Tracker if no destination is selected, but keep the units loaded!
    if (!toBranch) {
        if(aiContainer) aiContainer.innerHTML = '<span style="color:#d97706; font-size:11px; font-weight:bold;">⚠️ Select a Destination Branch to activate the AI Stock Radar.</span>';
        return; 
    }

    if(aiContainer) {
        aiContainer.innerHTML = '<span style="color:#0ea5e9; font-size:11px; font-weight:bold; animation: pulse 1s infinite;">🤖 AI Scanning Branch Data...</span>';
        try {
            const invQ = window.query(window.collection(window.db, "inventory"), window.where("branch", "==", toBranch), window.where("name", "==", itemName));
            const invSnap = await window.getDocs(invQ);
            let currentStock = 0; let bUom = 'units';
            if (!invSnap.empty) {
                currentStock = parseFloat(invSnap.docs[0].data().currentStock) || 0;
                bUom = invSnap.docs[0].data().uom || 'units';
            }

            let pastDate = new Date();
            pastDate.setDate(pastDate.getDate() - 14);
            const logsQ = window.query(window.collection(window.db, "stock_logs"), window.where("branch", "==", toBranch), window.where("item", "==", itemName), window.where("timestamp", ">=", pastDate));
            const logsSnap = await window.getDocs(logsQ);

            let totalBurn = 0;
            logsSnap.forEach(doc => {
                let log = doc.data();
                let v = parseFloat(log.variance) || 0;
                let t = (log.type || "").toLowerCase();
                if (v < 0 && (t.includes("sales") || t.includes("deduction") || t.includes("waste") || t.includes("spoilage") || t.includes("store use") || t.includes("prep") || t.includes("adjustment") || t.includes("voided") || t.includes("penalty") || t.includes("audit") || t.includes("count"))) {
                    totalBurn += Math.abs(v);
                }
            });

            let dailyBurn = totalBurn / 14;
            let daysLeft = dailyBurn > 0 ? (currentStock / dailyBurn) : Infinity;
            let daysText = daysLeft === Infinity ? "∞" : daysLeft.toFixed(1) + " Days";
            let statusColor = currentStock <= 0 ? "#dc2626" : (daysLeft <= 3 ? "#ea580c" : "#16a34a");

            aiContainer.innerHTML = `
                <div style="background: #f8fafc; border: 1px dashed #cbd5e1; padding: 10px; border-radius: 8px; font-size: 11px; color: #475569; display: flex; flex-direction: column; gap: 4px; box-shadow: inset 0 2px 4px rgba(0,0,0,0.02);">
                    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 4px;">
                        <strong style="color: #0f172a;">🤖 AI Stock Radar (${toBranch})</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Current Live Stock:</span>
                        <strong style="color: ${currentStock <= 0 ? '#dc2626' : '#334155'};">${currentStock.toFixed(2)} ${bUom}</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Avg. Daily Burn (14-day):</span>
                        <strong style="color: #b45309;">${dailyBurn.toFixed(2)} ${bUom}/day</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between;">
                        <span>Estimated Runway:</span>
                        <strong style="color: ${statusColor};">${daysText}</strong>
                    </div>
                </div>
            `;
        } catch(e) {
            console.error("AI Tracker Error:", e);
            aiContainer.innerHTML = '<span style="color:#ef4444; font-size:11px;">Error loading AI data.</span>';
        }
    }
};

window.removeFromDispatchCart = function (index) {
  dispatchCart.splice(index, 1);
  renderDispatchCart();
};

// --- THE MENU EDITOR ENGINE (WITH CUSTOM ARRANGER) ---
window.globalMenuItemsCache = []; // Stores the menu in memory for arranging

window.loadMenuEditor = async function() {
  const tbody = document.getElementById('menuTableBody');
  if(!tbody) return;
  tbody.innerHTML = '<tr><td colspan="4" class="text-center">Fetching global menu...</td></tr>';

  let catFilterEl = document.getElementById('menuEditorCatFilter');
  let selectedCat = catFilterEl ? catFilterEl.value : 'All';

  // 🔥 INJECT THE SAVE LAYOUT BUTTON DYNAMICALLY
  let headerDiv = catFilterEl ? catFilterEl.closest('div') : null;
  if (headerDiv && !document.getElementById('btnSaveMenuOrder')) {
      let btnHtml = `<button id="btnSaveMenuOrder" class="btn-refresh" style="background: #8b5cf6; color: white; border: none; margin-left: 10px; box-shadow: 0 2px 4px rgba(139,92,246,0.3);" onclick="window.saveMenuItemLayout()">💾 Save Display Order</button>`;
      headerDiv.insertAdjacentHTML('beforeend', btnHtml);
  }

  try {
    const snap = await getDocs(collection(db, "menu"));
    
    // Fetch Custom Layout
    let layoutOrder = [];
    try {
        const layoutSnap = await getDoc(doc(db, "settings", "pos_item_layout"));
        if (layoutSnap.exists()) layoutOrder = layoutSnap.data().items || [];
    } catch(e) {}

    let items = [];
    let uniqueCategories = new Set();

    snap.forEach(doc => {
      let d = doc.data();
      items.push({ id: doc.id, ...d });
      if (d.category) uniqueCategories.add(d.category.trim());
    });

    if (items.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" class="text-center">Menu is empty. Click "Add Menu Item" to start.</td></tr>';
      return;
    }

    if (catFilterEl) {
        let optionsHtml = '<option value="All">All Categories</option>';
        Array.from(uniqueCategories).sort().forEach(cat => {
            let isSelected = (cat === selectedCat) ? 'selected' : '';
            optionsHtml += `<option value="${cat}" ${isSelected}>${cat}</option>`;
        });
        catFilterEl.innerHTML = optionsHtml;
    }

    // 🔥 SORT BY CUSTOM LAYOUT FIRST, THEN ALPHABETICAL
    items.sort((a, b) => {
        let idxA = layoutOrder.indexOf(a.id);
        let idxB = layoutOrder.indexOf(b.id);
        if (idxA !== -1 && idxB !== -1) return idxA - idxB;
        if (idxA !== -1) return -1;
        if (idxB !== -1) return 1;
        return (a.name || '').localeCompare(b.name || '');
    });

    window.globalMenuItemsCache = items;
    window.renderMenuEditorUI();

  } catch (error) {
    console.error("Menu Engine Error:", error);
    tbody.innerHTML = '<tr><td colspan="4" class="text-center" style="color: red;">Error loading menu.</td></tr>';
  }
};

// ==========================================
// 🖱️ DRAG & DROP MENU ARRANGER ENGINE
// ==========================================
window.draggedMenuItemId = null;

window.handleMenuDragStart = function(e, id) {
    window.draggedMenuItemId = id;
    e.dataTransfer.effectAllowed = 'move';
    e.target.style.opacity = '0.5'; // Makes the dragged item slightly transparent
};

window.handleMenuDragOver = function(e) {
    e.preventDefault(); // Necessary to allow dropping
    e.dataTransfer.dropEffect = 'move';
};

window.handleMenuDragEnter = function(e) {
    e.preventDefault();
    let tr = e.target.closest('tr');
    if (tr) tr.style.borderTop = "3px solid #8b5cf6"; // Show a purple drop-zone line!
};

window.handleMenuDragLeave = function(e) {
    let tr = e.target.closest('tr');
    if (tr) tr.style.borderTop = ""; // Remove the line when dragging away
};

window.handleMenuDrop = function(e, targetId) {
    e.stopPropagation();
    e.preventDefault();
    
    let tr = e.target.closest('tr');
    if (tr) tr.style.borderTop = "";
    
    // Stop if dropped on itself or outside
    if (!window.draggedMenuItemId || window.draggedMenuItemId === targetId) return;

    // Find the items in global memory
    let fromIdx = window.globalMenuItemsCache.findIndex(i => i.id === window.draggedMenuItemId);
    let toIdx = window.globalMenuItemsCache.findIndex(i => i.id === targetId);

    if (fromIdx >= 0 && toIdx >= 0) {
        // Cut the dragged item out of the array
        let item = window.globalMenuItemsCache.splice(fromIdx, 1)[0];
        // Paste it exactly at the new targeted location
        window.globalMenuItemsCache.splice(toIdx, 0, item);
        
        // Redraw the screen instantly!
        window.renderMenuEditorUI(); 
    }
};

window.handleMenuDragEnd = function(e) {
    e.target.style.opacity = '1';
    // Clean up any stuck purple lines just in case
    document.querySelectorAll('#menuTableBody tr').forEach(t => t.style.borderTop = "");
    window.draggedMenuItemId = null;
};

window.renderMenuEditorUI = function() {
    const tbody = document.getElementById('menuTableBody');
    let catFilterEl = document.getElementById('menuEditorCatFilter');
    let selectedCat = catFilterEl ? catFilterEl.value : 'All';
    let html = '';
    let count = 0;

    let visibleItems = window.globalMenuItemsCache.filter(item => {
        let cat = item.category || 'Uncategorized';
        return selectedCat === 'All' || cat === selectedCat;
    });

    visibleItems.forEach(data => {
      count++;
      let safePrice = parseFloat(data.price) || 0;
      let safeName = data.name ? data.name.replace(/'/g, "\\'") : 'Unnamed';
      let safeCat = (data.category || 'Uncategorized').replace(/'/g, "\\'");
      
      let imgHtml = data.image 
          ? `<img src="${data.image}" style="width:40px; height:40px; border-radius:6px; object-fit:cover; display:inline-block; vertical-align:middle; border:1px solid #e2e8f0;">` 
          : `<div style="width:40px; height:40px; border-radius:6px; background:#f1f5f9; display:inline-flex; align-items:center; justify-content:center; font-size:18px; vertical-align:middle; border:1px solid #e2e8f0;">🍲</div>`;

      // 🔥 THE BEAUTIFUL DRAG HANDLE
      let dragHandle = `<span style="color: #94a3b8; font-size: 18px; margin-right: 10px; cursor: grab;" title="Hold and drag to reorder">↕️</span>`;

      html += `
        <tr draggable="true"
            ondragstart="window.handleMenuDragStart(event, '${data.id}')"
            ondragover="window.handleMenuDragOver(event)"
            ondragenter="window.handleMenuDragEnter(event)"
            ondragleave="window.handleMenuDragLeave(event)"
            ondrop="window.handleMenuDrop(event, '${data.id}')"
            ondragend="window.handleMenuDragEnd(event)"
            style="border-bottom: 1px solid #f1f5f9; background: white; transition: background 0.2s;"
            onmouseover="this.style.background='#f8fafc'"
            onmouseout="this.style.background='white'">
          <td style="padding: 12px; display: flex; align-items: center;">${dragHandle}${imgHtml}<strong style="margin-left: 8px;"> ${data.name}</strong></td>
          <td style="padding: 12px;"><span class="badge badge-closed">${data.category || 'Uncategorized'}</span></td>
          <td style="padding: 12px; font-weight: 600; color: var(--primary);">${formatMoney(safePrice)}</td>
          <td style="padding: 12px; display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button class="btn-refresh" style="background: white; border: 1px solid var(--primary); color: var(--primary); padding: 6px 12px; font-size: 12px; border-radius: 4px; cursor: pointer;" onclick="openBomEditor('${safeName}')">🍟 Recipe/Addons</button>
            <button class="btn-refresh" onclick="window.editMenuItem('${data.id}', '${safeName}', '${safeCat}', ${safePrice})">✏️ Edit</button>
            <label style="cursor: pointer; background: #f0fdf4; border: 1px solid #16a34a; color: #16a34a; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; margin: 0; display: inline-flex; align-items: center;">
                📷 Pic
                <input type="file" accept="image/jpeg, image/png, image/webp" style="display:none;" onchange="window.uploadMenuImage(event, '${data.id}')">
            </label>
            <button class="btn-refresh" style="color: var(--danger); border-color: var(--danger);" onclick="deleteMenuItem('${data.id}', '${safeName}')">🗑️</button>
          </td>
        </tr>
      `;
    });
    
    tbody.innerHTML = count > 0 ? html : `<tr><td colspan="4" class="text-center">No items found in category: ${selectedCat}.</td></tr>`;
};

window.saveMenuItemLayout = async function() {
    // Extracts the IDs in their exact new order
    let layoutIds = window.globalMenuItemsCache.map(i => i.id);
    
    let btn = document.getElementById('btnSaveMenuOrder');
    if (btn) btn.innerText = "⏳ Saving...";

    try {
        await setDoc(doc(db, "settings", "pos_item_layout"), { items: layoutIds }, { merge: true });
        Swal.fire({
            title: '✅ Layout Saved!',
            text: 'Menu item arrangement saved. Cashier apps will update instantly.',
            icon: 'success',
            customClass: { popup: 'rounded-2xl' }
        });
    } catch(e) {
        console.error(e);
        Swal.fire('Error', 'Failed to save layout to cloud.', 'error');
    } finally {
        if (btn) btn.innerText = "💾 Save Display Order";
    }
};

window.addMenuItem = async function () {
  let name = prompt("Enter new item name (e.g., Spicy Takoyaki):");
  if (!name) return;

  let category = prompt("Enter Category (e.g., Takoyaki, Milk Tea, Coffee):");
  if (!category) return;

  let priceStr = prompt(`Enter Base Price for ${name} (₱):`);
  if (!priceStr) return;

  let price = parseFloat(priceStr);
  if (isNaN(price) || price < 0) { alert("❌ Error: Invalid price."); return; }

  try {
    await addDoc(collection(db, "menu"), { name: name, category: category, price: price });
    alert(`✅ Success! ${name} added to the global menu.`);
    window.loadMenuEditor();
  } catch (error) {
    console.error(error); alert("❌ Failed to add item.");
  }
};

// ==========================================
// ✏️ EDIT MENU ITEM (WITH GRAB & FOODPANDA)
// ==========================================
window.editMenuItem = async function (docId, currentName, currentCat, currentPrice) {
    Swal.fire({title: 'Loading Pricing Data...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});
    
    // Fetch existing platform prices
    let grabPrice = currentPrice;
    let fpPrice = currentPrice;
    try {
        const itemRef = doc(db, "menu", docId);
        const itemSnap = await getDoc(itemRef);
        if (itemSnap.exists()) {
            grabPrice = itemSnap.data().grabPrice || currentPrice;
            fpPrice = itemSnap.data().foodpandaPrice || currentPrice;
        }
    } catch(e) { console.error("Error fetching prices:", e); }
    
    Swal.close();

    const { value: formValues, isConfirmed } = await Swal.fire({
        title: '✏️ Edit Menu Item',
        html: `
            <div style="text-align: left; margin-top: 10px;">
                <label style="font-size: 12px; font-weight: bold; color: #475569;">Item Name:</label>
                <input type="text" id="swal-menu-name" class="input-box" value="${currentName}" style="width: 100%; padding: 10px; border-radius: 6px; border: 1px solid #cbd5e1; margin-bottom: 10px; outline: none;">

                <label style="font-size: 12px; font-weight: bold; color: #475569;">Category:</label>
                <input type="text" id="swal-menu-cat" class="input-box" value="${currentCat}" style="width: 100%; padding: 10px; border-radius: 6px; border: 1px solid #cbd5e1; margin-bottom: 10px; outline: none;">

                <label style="font-size: 12px; font-weight: bold; color: #475569;">Base Price (₱):</label>
                <input type="number" id="swal-menu-price" class="input-box" value="${currentPrice}" style="width: 100%; padding: 10px; border-radius: 6px; border: 1px solid #cbd5e1; margin-bottom: 15px; outline: none; font-weight: bold;">
                
                <div style="background: #f8fafc; padding: 15px; border-radius: 8px; border: 1px dashed #cbd5e1;">
                    <label style="font-size: 12px; font-weight: 900; color: #16a34a; display: block; margin-bottom: 5px;">🟢 GRAB Price (₱):</label>
                    <input type="number" id="swal-menu-grab" class="input-box" value="${grabPrice}" style="width: 100%; padding: 10px; border-radius: 6px; border: 2px solid #bbf7d0; background: #f0fdf4; color: #16a34a; margin-bottom: 10px; outline: none; font-weight: 900;">

                    <label style="font-size: 12px; font-weight: 900; color: #d70f64; display: block; margin-bottom: 5px;">🐼 Foodpanda Price (₱):</label>
                    <input type="number" id="swal-menu-fp" class="input-box" value="${fpPrice}" style="width: 100%; padding: 10px; border-radius: 6px; border: 2px solid #fbcfe8; background: #fdf2f8; color: #d70f64; outline: none; font-weight: 900;">
                </div>
            </div>
        `,
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonColor: '#0ea5e9',
        confirmButtonText: 'Save Changes',
        customClass: { popup: 'rounded-2xl shadow-xl' },
        preConfirm: () => {
            return {
                name: document.getElementById('swal-menu-name').value.trim(),
                category: document.getElementById('swal-menu-cat').value.trim(),
                price: parseFloat(document.getElementById('swal-menu-price').value),
                grabPrice: parseFloat(document.getElementById('swal-menu-grab').value),
                foodpandaPrice: parseFloat(document.getElementById('swal-menu-fp').value)
            };
        }
    });

    if (!isConfirmed || !formValues.name || isNaN(formValues.price)) return;

    Swal.fire({title: 'Syncing Database...', text: 'Updating menu and linked recipes...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        await updateDoc(doc(db, "menu", docId), { 
            name: formValues.name, 
            category: formValues.category, 
            price: formValues.price, 
            basePrice: formValues.price,
            grabPrice: formValues.grabPrice,
            foodpandaPrice: formValues.foodpandaPrice
        });

        if (currentName !== formValues.name) {
            const bomQ = query(collection(db, "bom"), where("menuItem", "==", currentName));
            const bomSnap = await getDocs(bomQ);
            let updatePromises = [];
            bomSnap.forEach(bDoc => {
                updatePromises.push(updateDoc(doc(db, "bom", bDoc.id), { menuItem: formValues.name }));
            });
            await Promise.all(updatePromises);
        }
        
        Swal.fire({
            title: '✅ Saved!',
            text: `${formValues.name} pricing has been updated globally.`,
            icon: 'success',
            timer: 1500,
            showConfirmButton: false,
            customClass: { popup: 'rounded-2xl' }
        });
        
        window.loadMenuEditor();
    } catch (error) {
        console.error(error); Swal.fire('Error', 'Failed to update item.', 'error');
    }
};

// --- 🖼️ IMAGE UPLOAD ENGINE ---
window.uploadMenuImage = async function(event, docId) {
    const file = event.target.files[0];
    if (!file) return;

    // Strict Size Limit (2MB max) to ensure Customer App loads fast
    if (file.size > 2 * 1024 * 1024) {
        alert("⚠️ Image is too large! Please choose a picture under 2MB.");
        return;
    }

    // Give visual feedback on the button
    const label = event.target.parentElement;
    const originalHTML = label.innerHTML;
    label.innerText = "⏳ Uploading...";
    label.style.opacity = "0.7";

    try {
        // 1. Create a clean, unique file name
        const fileExt = file.name.split('.').pop();
        const fileName = `menu_images/${docId}_${Date.now()}.${fileExt}`;
        const storageReference = ref(window.storage, fileName);

        // 2. Upload physical file to Firebase Storage
        const snapshot = await uploadBytes(storageReference, file);
        
        // 3. Get the live, public URL of the uploaded image
        const downloadURL = await getDownloadURL(snapshot.ref);

        // 4. Update the Firestore Database so the Customer App sees it
        await updateDoc(doc(db, "menu", docId), {
            image: downloadURL
        });

        alert("✅ Image uploaded and linked successfully!");
        window.loadMenuEditor(); // Refresh table to show the new thumbnail
        
    } catch (e) {
        console.error("Upload error:", e);
        alert("❌ Failed to upload image. Ensure Firebase Storage is fully activated.");
        label.innerHTML = originalHTML;
        label.style.opacity = "1";
    }
};

// --- DETAILED BRANCH ANALYTICS ENGINE (UPGRADED WITH TRUE COGS) ---
window.openBranchDetails = async function (branch) {
  document.getElementById('analyticsModal').style.display = 'flex';
  document.getElementById('modalBranchName').innerText = `📊 ${branch} Analytics`;

  const startDateInput = document.getElementById('dashStartDate');
  const endDateInput = document.getElementById('dashEndDate');
  const startDay = new Date(startDateInput.value);
  const endDay = new Date(endDateInput.value);

  document.getElementById('modalDateDisplay').innerText = `${startDay.toLocaleDateString('en-PH', { month: 'short', day: 'numeric' })} - ${endDay.toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' })}`;

  document.getElementById('mdlNet').innerText = "Loading...";
  document.getElementById('tbCatBody').innerHTML = '<tr><td colspan="5" class="text-center">Calculating Margins...</td></tr>';

  const startOfDay = new Date(startDay.setHours(0, 0, 0, 0));
  const endOfDay = new Date(endDay.setHours(23, 59, 59, 999));

  try {
    // 1. FETCH SHIFT FIRST to establish time boundaries
    const shiftQ = query(collection(db, "shifts"), where("branch", "==", branch), where("startTime", ">=", startOfDay), orderBy("startTime", "desc"), limit(1));
    const shiftSnap = await getDocs(shiftQ);

    if (shiftSnap.empty) {
        document.getElementById('tbCatBody').innerHTML = '<tr><td colspan="5" class="text-center" style="padding: 30px; color: #64748b;">No shift found for this date.</td></tr>';
        document.getElementById('modalDateDisplay').innerText = "No Active Shift";
        return; 
    }

    let shiftData = shiftSnap.docs[0].data();
    let shiftDocId = shiftSnap.docs[0].id;
    let sTime = shiftData.startTime.toDate();
    let eTime = shiftData.active ? new Date() : shiftData.endTime.toDate();

    document.getElementById('modalDateDisplay').innerText = `Shift: ${sTime.toLocaleTimeString('en-PH', {hour: '2-digit', minute:'2-digit'})} to ${shiftData.active ? 'Present' : eTime.toLocaleTimeString('en-PH', {hour: '2-digit', minute:'2-digit'})}`;

    // 🔥 LIGHTNING FAST PARALLEL DATA FETCH 🔥
    const txQ = query(collection(db, "transactions"), where("branch", "==", branch), where("timestamp", ">=", sTime), where("timestamp", "<=", eTime));
    const parkedQ = query(collection(db, "parked_orders"), where("branch", "==", branch), where("timestamp", ">=", sTime), where("timestamp", "<=", eTime));
    const expQ = query(collection(db, "expenses"), where("shiftId", "==", shiftDocId));
    const invQ = collection(db, "inventory"); // Get global inventory for costs
    const bomQ = collection(db, "bom"); // Get recipes for COGS
    const menuQ = collection(db, "menu");

    // Blast all 6 queries at the exact same time!
    const [txSnap, parkedSnap, expSnap, invSnap, bomSnap, menuSnap] = await Promise.all([
        getDocs(txQ), getDocs(parkedQ), getDocs(expQ), getDocs(invQ), getDocs(bomQ), getDocs(menuQ)
    ]);

    let netSales = 0; let totalItems = 0; let transCount = 0; let voidCount = 0;
    let categories = {};
    let payments = {};
    let transHtml = '';

    let allTx = [];
    txSnap.forEach(doc => allTx.push({ id: doc.id, ...doc.data() }));

    parkedSnap.forEach(doc => {
        let p = doc.data();
        allTx.push({
            id: doc.id,
            receiptId: "PARKED-" + doc.id.substring(0,4).toUpperCase(),
            customerName: p.name || p.customerName || "Guest",
            netTotal: p.total || p.netTotal || 0,
            status: "Parked",
            paymentMethod: "Unpaid",
            cart: p.items || p.cart || [],
            timestamp: p.timestamp,
            cashier: p.cashier || 'Unknown',
            orderType: p.orderType || 'Dine-In'
        });
    });

    // Sort transactions by time (newest first)
    allTx.sort((a, b) => {
        let tA = a.timestamp ? (a.timestamp.toDate ? a.timestamp.toDate() : new Date(a.timestamp)) : 0;
        let tB = b.timestamp ? (b.timestamp.toDate ? b.timestamp.toDate() : new Date(b.timestamp)) : 0;
        return tB - tA;
    });

    // Process Inventory Costs
    let inventoryCosts = {};
    invSnap.forEach(doc => {
        let data = doc.data();
        inventoryCosts[data.name] = parseFloat(data.baseCost) || 0;
    });

    // Process Recipe COGS
    let recipeCosts = {};
    bomSnap.forEach(doc => {
        let data = doc.data();
        if (!recipeCosts[data.menuItem]) recipeCosts[data.menuItem] = 0;
        let ingCost = inventoryCosts[data.ingredientName] || 0;
        recipeCosts[data.menuItem] += (ingCost * (data.qty || 1));
    });

    // Process Menu Categories
    let menuCategories = {};
    menuSnap.forEach(doc => {
        menuCategories[doc.data().name] = doc.data().category || 'Uncategorized';
    });

    allTx.forEach(tx => {
      let timeStr = tx.timestamp ? (tx.timestamp.toDate ? tx.timestamp.toDate() : new Date(tx.timestamp)).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }) : 'Unknown';

      let safeCustomer = tx.customerName ? tx.customerName.replace(/'/g, "\\'") : 'Guest';
      let safeCart = encodeURIComponent(JSON.stringify(tx.cart || []));

      if (tx.status === "Voided") {
        voidCount++;
        transHtml += `<tr style="opacity: 0.5;"><td>${timeStr}</td><td>${tx.receiptId}</td><td>${safeCustomer}</td><td>-</td><td><span class="badge badge-closed"><span class="status-dot red"></span> VOID</span></td><td style="text-decoration: line-through;">${formatMoney(tx.netTotal)}</td><td></td></tr>`;
      } else {
        transCount++;
        netSales += (tx.netTotal || 0);

        // Track Payments
        let payMethod = tx.paymentMethod || "Unknown";
        if (!payments[payMethod]) payments[payMethod] = 0;
        payments[payMethod] += (tx.netTotal || 0);

        // Track True Categories, Sales, and Advanced COGS
        if (tx.cart && Array.isArray(tx.cart)) {
          tx.cart.forEach(item => {
            let qty = item.qty || 1;
            totalItems += qty;

            let itemName = item.name || item.itemName;
            let cat = menuCategories[itemName] || item.category || 'Uncategorized';

            if (!categories[cat]) categories[cat] = { qty: 0, sales: 0, cogs: 0 };

            categories[cat].qty += qty;

            // Calculate Sales
            let lineRevenue = item.lineTotalFinal !== undefined ? item.lineTotalFinal : ((item.variantPrice || item.basePrice || 0) * qty);
            categories[cat].sales += lineRevenue;

            // Calculate Base Recipe COGS
            let baseCogs = (recipeCosts[itemName] || 0) * qty;
            let addonCogs = 0;

            // Calculate Add-on COGS
            if (item.addons) {
                for (let key in item.addons) {
                    let addon = item.addons[key];
                    if (addon.qty > 0 && addon.linkedIngredient && addon.deductQty > 0) {
                        let aCost = inventoryCosts[addon.linkedIngredient] || 0;
                        addonCogs += (aCost * addon.deductQty * addon.qty * qty);
                    }
                }
            }

            categories[cat].cogs += (baseCogs + addonCogs);
          });
        }

        // SMART DIGITAL PAYMENT VERIFICATION UI
        let isDigital = payMethod.toLowerCase() !== "cash" && !payMethod.toLowerCase().includes("store use");
        let verifyBadge = "";
        let verifyBtn = "";

        if (isDigital) {
            if (tx.paymentVerified) {
                verifyBadge = `<br><span style="color: #16a34a; font-size: 10px; font-weight: bold;">✅ Verified by Manager</span>`;
            } else {
                verifyBadge = `<br><span style="color: #ea580c; font-size: 10px; font-weight: bold; animation: pulse 2s infinite;">⏳ Awaiting Verification</span>`;
                verifyBtn = `<button class="btn-bulk-verify" data-txid="${tx.id}" onclick="window.verifyDigitalPayment('${tx.id}', '${tx.receiptId}')" style="background: #16a34a; border: 1px solid #15803d; color: white; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">✅ Verify</button>`;
            }
        }

        let txTimeMs = tx.timestamp ? (tx.timestamp.toDate ? tx.timestamp.toDate().getTime() : new Date(tx.timestamp).getTime()) : Date.now();
        let minutesElapsed = Math.floor((Date.now() - txTimeMs) / 60000);

        let statusDisplay = '';
        if (tx.status === "Parked") {
            statusDisplay = `<span style="background: #fef3c7; color: #d97706; border: 1px solid #fcd34d; padding: 4px 8px; border-radius: 6px; font-weight: bold; font-size: 11px;">⏸️ PARKED (Unpaid)</span>`;
        } else if (minutesElapsed < 10) {
            let timeLeft = 10 - minutesElapsed;
            statusDisplay = `<span class="live-prep-timer" data-time="${txTimeMs}" style="background: #fef08a; color: #b45309; border: 1px solid #fde047; padding: 4px 8px; border-radius: 6px; font-weight: 900; font-size: 11px; display: inline-flex; align-items: center; gap: 4px; box-shadow: 0 0 8px rgba(250, 204, 21, 0.6); animation: pulse 1.5s infinite;">🍳 COOKING (${timeLeft}m)</span>`;
        } else {
            statusDisplay = `<span class="badge badge-active"><span class="status-dot green"></span> PAID</span>`;
        }

        transHtml += `<tr style="border-bottom: 1px solid #f1f5f9; ${isDigital && !tx.paymentVerified ? 'background: #fffbeb;' : ''}">
            <td style="padding: 10px;">${timeStr}</td>
            <td style="padding: 10px;"><strong>${tx.receiptId}</strong></td>
            <td style="padding: 10px; color: #475569; font-weight: bold;">${safeCustomer}</td>
            <td style="padding: 10px;">${payMethod}${verifyBadge}</td>
            <td style="padding: 10px;">${statusDisplay}</td>
            <td style="font-weight: 600; color: var(--primary); padding: 10px;">${formatMoney(tx.netTotal)}</td>
            <td style="padding: 10px; text-align: center; display: flex; gap: 5px; justify-content: center;">
                <button onclick="window.viewReceiptDetails('${tx.receiptId}', '${safeCustomer}', '${timeStr}', '${payMethod}', ${tx.netTotal}, '${safeCart}')" style="background: white; border: 1px solid #cbd5e1; color: #334155; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">🔍 View</button>
                ${verifyBtn}
            </td>
        </tr>`;
      }
    });

    // Process Drawer Cash & Audit Engine
    let dateExpenses = 0;
    expSnap.forEach(doc => dateExpenses += (doc.data().amount || 0));

    const prevShiftQ = query(collection(db, "shifts"), where("branch", "==", branch), where("status", "==", "Closed"), orderBy("endTime", "desc"), limit(1));
    const prevShiftSnap = await getDocs(prevShiftQ);
    let lastClosingCash = prevShiftSnap.empty ? 0 : (prevShiftSnap.docs[0].data().declaredCash || 0);

    let startingCash = 0;

    if (shiftData.active) {
      startingCash = shiftData.startingCash || 0;
      let cashSales = payments['Cash'] || 0;
      let expectedDrawerCash = startingCash + cashSales - dateExpenses;

      document.getElementById('mdlDrawerCash').innerText = formatMoney(expectedDrawerCash);
      document.getElementById('mdlDrawerMath').innerHTML = `
        <b>Entered Float:</b> ${formatMoney(startingCash)}<br>
        <b>Expenses Paid:</b> ${formatMoney(dateExpenses)}
      `;

      const auditEl = document.getElementById('mdlAuditAlert');
      if (startingCash === lastClosingCash) {
        auditEl.innerHTML = `<span style="color: #16a34a;">✅ Matches Last Closing (₱${lastClosingCash})</span>`;
      } else {
        let diff = startingCash - lastClosingCash;
        let sign = diff > 0 ? "+" : "";
        auditEl.innerHTML = `<span style="color: #dc2626;">⚠️ DISCREPANCY: ${sign}${diff} vs Last Close</span>`;
      }
    } else {
      document.getElementById('mdlDrawerCash').innerText = "No Active Shift";
      document.getElementById('mdlDrawerMath').innerText = "Register is currently closed.";
      document.getElementById('mdlAuditAlert').innerText = "";
    }

    // INJECT KPIs
    document.getElementById('mdlNet').innerText = formatMoney(netSales);
    document.getElementById('mdlItems').innerText = totalItems;
    document.getElementById('mdlTrans').innerText = transCount;
    document.getElementById('mdlVoids').innerText = voidCount;

    // INJECT ADVANCED CATEGORIES WITH MARGINS
    let catHtml = '';
    let sortedCats = Object.keys(categories).sort((a, b) => categories[b].sales - categories[a].sales);

    sortedCats.forEach(cat => {
        let data = categories[cat];
        let profit = data.sales - data.cogs;
        let margin = data.sales > 0 ? (profit / data.sales) * 100 : 0;
        let marginColor = margin > 50 ? '#16a34a' : (margin > 30 ? '#f59e0b' : '#dc2626');

        catHtml += `
            <tr style="border-bottom: 1px solid #f1f5f9;">
                <td style="font-weight: bold; color: #334155; padding: 10px;">${cat}</td>
                <td style="padding: 10px;">${data.qty} items</td>
                <td style="font-weight: bold; color: #d97706; padding: 10px;">${formatMoney(data.sales)}</td>
                <td style="font-weight: bold; color: #ef4444; padding: 10px;">${formatMoney(data.cogs)}</td>
                <td style="font-weight: 900; color: ${marginColor}; padding: 10px;">${margin.toFixed(1)}%</td>
            </tr>
        `;
    });

    let catTableHead = document.getElementById('tbCatBody').previousElementSibling.querySelector('tr');
    if (catTableHead) {
        catTableHead.innerHTML = '<th style="text-align:left; padding:10px;">Category</th><th style="text-align:left; padding:10px;">Sold</th><th style="text-align:left; padding:10px;">Gross</th><th style="text-align:left; padding:10px;">Est. COGS</th><th style="text-align:left; padding:10px;">Margin</th>';
    }

    document.getElementById('tbCatBody').innerHTML = catHtml || '<tr><td colspan="5" class="text-center">No items sold.</td></tr>';

    // INJECT PAYMENTS
    let payHtml = '';
    for (let p in payments) {
      payHtml += `<tr><td style="padding: 10px;"><strong>${p}</strong></td><td style="color: var(--success); font-weight: 600; padding: 10px;">${formatMoney(payments[p])}</td></tr>`;
    }
    document.getElementById('tbPayBody').innerHTML = payHtml || '<tr><td colspan="2" class="text-center">No payments logged.</td></tr>';

    // INJECT TRANSACTIONS
    let transTableHead = document.getElementById('tbTransBody').previousElementSibling.querySelector('tr');
    if (transTableHead) {
        transTableHead.innerHTML = '<th style="text-align:left; padding:10px;">Time</th><th style="text-align:left; padding:10px;">Receipt ID</th><th style="text-align:left; padding:10px; color: #0284c7;">Customer</th><th style="text-align:left; padding:10px;">Payment</th><th style="text-align:left; padding:10px;">Status</th><th style="text-align:left; padding:10px;">Total</th><th style="text-align:center; padding:10px;">Action</th>';
    }
    
    document.getElementById('tbTransBody').innerHTML = transHtml || '<tr><td colspan="7" class="text-center">No transactions on this date.</td></tr>';

  } catch (error) {
    console.error("Analytics Error:", error);
    document.getElementById('tbCatBody').innerHTML = '<tr><td colspan="5" class="text-center" style="color: red;">Error loading analytics.</td></tr>';
  }
};

