window.openAddPayableModal = async function() {
    let modal = document.getElementById('addPayableModal');
    if(modal) modal.style.display = 'flex';
    
    // Safely clear main inputs
    let suppName = document.getElementById('paySupplierName');
    if(suppName) suppName.value = '';
    
    let invNum = document.getElementById('suppInvoice');
    if(invNum) invNum.value = '';
    
    let amountBox = document.getElementById('suppAmount');
    if(amountBox) amountBox.value = '';
    
    // 🔥 THE FIX: Use the new modern cart engine variables!
    window.payableCart = [];
    if(typeof window.renderPayableCart === 'function') window.renderPayableCart();

    // Clear the new item search inputs
    let itemInput = document.getElementById('payItemSearch');
    if (itemInput) itemInput.value = '';
    
    let qtyInput = document.getElementById('payItemQty');
    if (qtyInput) qtyInput.value = '';
    
    let costInput = document.getElementById('payItemCost');
    if (costInput) costInput.value = '';

    let subInput = document.getElementById('payItemSubtotal');
    if (subInput) subInput.value = '';

    let label = document.getElementById('payItemQtyLabel');
    if(label) label.innerHTML = "NO. OF PACKS";

    let prevCostLabel = document.getElementById('payItemPrevCost');
    if(prevCostLabel) prevCostLabel.innerHTML = "Prev Cost: ₱0.00";

    try {
        // Fetch live inventory for the datalist
        const q = window.query(window.collection(window.db, "inventory"), window.where("branch", "==", "Main Office"));
        const snap = await window.getDocs(q);
        
        // Store it in global memory so the UI can auto-calculate totals!
        window.globalInventoryList = []; 
        let datalistHtml = '<datalist id="payItemOptions">';
        
        snap.forEach(docSnap => {
            let data = docSnap.data();
            data.id = docSnap.id;
            window.globalInventoryList.push(data);
            datalistHtml += `<option value="${data.name}">${data.name} (${data.purchaseUom || data.uom})</option>`;
        });
        datalistHtml += '</datalist>';

        let existingList = document.getElementById('payItemOptions');
        if (existingList) existingList.remove();
        document.body.insertAdjacentHTML('beforeend', datalistHtml);
    } catch (e) { 
        console.error("Modal Opener Error:", e); 
    }
};

// ========================================================
// 📦 SUPPLIER DELIVERY CART & MATH ENGINE
// ========================================================
window.updatePayItemDetails = function() {
    let itemName = document.getElementById('payItemSearch').value.trim();
    let label = document.getElementById('payItemQtyLabel');
    let costInput = document.getElementById('payItemCost');
    let prevCostLabel = document.getElementById('payItemPrevCost');

    if (!itemName) {
        if(label) label.innerHTML = "QTY";
        if(costInput) costInput.value = "";
        if(prevCostLabel) prevCostLabel.innerHTML = "Prev Cost: ₱0.00";
        window.calcPayItemSubtotal();
        return;
    }

    let item = window.globalInventoryList.find(i => i.name === itemName && i.branch === "Main Office");
    if (item) {
        let pUom = item.purchaseUom || item.uom || 'units';
        let bUom = item.baseUom || item.uom || 'units';
        let cRate = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;

        if(label) label.innerHTML = `No. of <span style="color:#0ea5e9;">${pUom}s</span> <br><span style="font-size:9px; font-weight:bold; text-transform:none; color:#94a3b8;">(1 = ${cRate} ${bUom})</span>`;

        let pCost = parseFloat(item.purchaseCost) || parseFloat(item.purchCost) || parseFloat(item.cost) || 0;
        if (pCost === 0 && item.baseCost) pCost = parseFloat(item.baseCost) * cRate;

        if(costInput) costInput.value = pCost > 0 ? pCost.toFixed(2) : "";
        if(prevCostLabel) prevCostLabel.innerHTML = `Prev Cost: <span style="color:#dc2626;">₱${pCost.toFixed(2)}</span>`;

        window.calcPayItemSubtotal();
    }
};

window.calcPayItemSubtotal = function() {
    let qty = parseFloat(document.getElementById('payItemQty').value) || 0;
    let cost = parseFloat(document.getElementById('payItemCost').value) || 0;
    let sub = qty * cost;
    document.getElementById('payItemSubtotal').value = sub > 0 ? sub.toFixed(2) : "";
};

window.payableCart = window.payableCart || [];

window.addPayableItem = function() {
    let itemName = document.getElementById('payItemSearch').value.trim();
    let qty = parseFloat(document.getElementById('payItemQty').value);
    let cost = parseFloat(document.getElementById('payItemCost').value);
    let subtotal = parseFloat(document.getElementById('payItemSubtotal').value);

    if (!itemName || isNaN(qty) || qty <= 0 || isNaN(cost) || cost < 0) {
        return Swal.fire('Missing Data', 'Please enter a valid item, quantity, and unit cost.', 'warning');
    }

    let item = window.globalInventoryList.find(i => i.name === itemName && i.branch === "Main Office");
    if (!item) return Swal.fire('Error', 'Item not found in Main Office inventory.', 'error');

    let pUom = item.purchaseUom || item.uom || 'units';
    let bUom = item.baseUom || item.uom || 'units';
    let cRate = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;

    window.payableCart.push({
        id: item.id,
        name: item.name,
        purchQty: qty,
        purchUom: pUom,
        baseQty: qty * cRate,
        baseUom: bUom,
        unitCost: cost,
        subtotal: subtotal
    });

    // Reset fields for the next item
    document.getElementById('payItemSearch').value = '';
    document.getElementById('payItemQty').value = '';
    document.getElementById('payItemCost').value = '';
    document.getElementById('payItemSubtotal').value = '';
    document.getElementById('payItemPrevCost').innerText = 'Prev Cost: ₱0.00';
    document.getElementById('payItemQtyLabel').innerText = 'No. of Packs';

    window.renderPayableCart();
};

window.renderPayableCart = function() {
    let list = document.getElementById('payCartList');
    let grandTotal = 0;
    let html = '';

    window.payableCart.forEach((item, index) => {
        grandTotal += item.subtotal;
        html += `
            <li style="display: flex; justify-content: space-between; align-items: center; padding: 10px 10px; border-bottom: 1px dashed #cbd5e1; font-size: 13px; background: white; border-radius: 6px; margin-bottom: 4px;">
                <div style="flex: 2; color: #1e293b; font-weight: bold;">
                    ${item.name} <br>
                    <span style="color: #64748b; font-size: 11px;">${item.purchQty} <span style="color:#0ea5e9;">${item.purchUom}</span> @ ₱${item.unitCost.toFixed(2)}</span>
                    <div style="color: #10b981; font-size: 10px; margin-top: 2px;">Adds +${item.baseQty} ${item.baseUom} to stock</div>
                </div>
                <div style="flex: 1; text-align: right; color: #0f766e; font-weight: 900; font-size: 15px;">
                    ₱${item.subtotal.toFixed(2)}
                </div>
                <button onclick="window.payableCart.splice(${index}, 1); window.renderPayableCart();" style="margin-left: 15px; background: #fef2f2; color: #dc2626; border: 1px solid #fca5a5; border-radius: 6px; padding: 6px 10px; cursor: pointer; font-size: 11px; font-weight: bold; transition: 0.2s;">✖</button>
            </li>
        `;
    });

    list.innerHTML = html;

    // 🔥 AUTO-LINK TO THE INVOICE TOTAL BOX 🔥
    let totalBox = document.getElementById('payableAmount'); // Make sure this ID matches your HTML!
    if (totalBox) {
        totalBox.value = grandTotal > 0 ? grandTotal.toFixed(2) : "";
        // Flash it green to show it updated automatically
        totalBox.style.transition = "background-color 0.3s";
        totalBox.style.backgroundColor = "#dcfce7";
        setTimeout(() => totalBox.style.backgroundColor = "white", 500);
    }
};

window.removePayableItem = function(index) { window.payableItemsCart.splice(index, 1); window.renderPayableItems(); };

window.renderPayableItems = function() {
    let container = document.getElementById('payItemsList');
    if (window.payableItemsCart.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding: 10px; font-style: italic;">No physical items linked. This will just log the cash payable.</div>'; return;
    }
    let html = '';
    window.payableItemsCart.forEach((item, index) => {
        html += `<div style="display:flex; justify-content:space-between; align-items:center; padding: 6px 5px; border-bottom: 1px dashed #cbd5e1; background: white; border-radius: 4px; margin-bottom: 4px;">
                <span><strong style="color: #0f766e;">${item.purchQty} ${item.purchUom}</strong> ${item.name} <br><span style="font-size:10px; color:#64748b;">(Adds +${item.baseQtyToAdd} ${item.baseUom} to stock)</span></span>
                <button onclick="window.removePayableItem(${index})" style="color: #ef4444; background: #fef2f2; border: 1px solid #fecaca; border-radius: 4px; padding: 2px 6px; cursor: pointer; font-weight: bold;">✖</button>
            </div>`;
    });
    container.innerHTML = html;
};

// ========================================================
// 📦 MASTER SAVE: PAYABLES & AVERAGE COSTING ENGINE
// ========================================================
window.saveNewPayable = async function() {
    // Automatically add pending item in the box if they forgot to click '+'
    let pendingItemBox = document.getElementById('payItemSearch');
    let pendingQtyBox = document.getElementById('payItemQty');
    if (pendingItemBox && pendingItemBox.value && pendingQtyBox && pendingQtyBox.value) {
        window.addPayableItem(); 
    }

    // Safely grab values regardless of old or new HTML IDs
    let suppBox = document.getElementById('paySupplierName') || document.getElementById('suppName');
    let invBox = document.getElementById('payInvoiceNum') || document.getElementById('suppInvoice');
    let amtBox = document.getElementById('payAmount') || document.getElementById('suppAmount');
    let termsBox = document.getElementById('payTerms') || document.getElementById('suppTerms');

    let supplier = suppBox ? suppBox.value.trim() : '';
    let invoice = invBox ? invBox.value.trim() : '';
    let amount = amtBox ? parseFloat(amtBox.value) : 0;
    
    // Safely parse the terms. If it's text like "Cash / COD", force it to be 0 days!
    let termsRaw = termsBox ? termsBox.value : "0";
    let terms = parseInt(termsRaw);
    if (isNaN(terms)) {
        terms = 0;
    }

    if (!supplier || isNaN(amount) || amount <= 0) { 
        Swal.fire('Missing Details', 'Please enter Supplier Name and a valid Amount.', 'warning'); 
        return; 
    }

    let btn = document.getElementById('btnSavePayable');
    if(btn) { btn.innerText = "⏳ Uploading & Saving..."; btn.disabled = true; }

    try {
        // 🔥 UPLOAD THE INVOICE PHOTO TO FIREBASE STORAGE
        let photoUrl = "";
        let fileInput = document.getElementById('payPhotoProof') || document.getElementById('suppPhoto');
        
        if (fileInput && fileInput.files.length > 0) {
            const file = fileInput.files[0];
            const fileExt = file.name.split('.').pop();
            const fileName = `payables/inv_${Date.now()}.${fileExt}`;
            const storageRef = window.ref(window.storage, fileName);
            const snapshot = await window.uploadBytes(storageRef, file);
            photoUrl = await window.getDownloadURL(snapshot.ref);
        }

        // Calculate exact due date
        let deliveryDate = new Date(); 
        let dueDate = new Date(); 
        dueDate.setDate(deliveryDate.getDate() + terms);
        
        await window.addDoc(window.collection(window.db, "payables"), {
            supplier: supplier, invoiceNum: invoice, amount: amount, termsDays: terms, deliveryDate: deliveryDate, dueDate: dueDate, status: "Unpaid",
            hasLinkedItems: window.payableCart.length > 0, linkedItems: window.payableCart,
            photoUrl: photoUrl, 
            loggedBy: window.sessionUser ? window.sessionUser.cashierName : "Manager", timestamp: window.serverTimestamp()
        });

        if (window.payableCart.length > 0) {
            // 🧠 AVERAGE COST & INVENTORY INJECTION ENGINE
            for (let item of window.payableCart) {
                const invRef = window.doc(window.db, "inventory", item.id);
                const invSnap = await window.getDoc(invRef);
                
                if (invSnap.exists()) {
                    let invData = invSnap.data();
                    let currentStockBase = parseFloat(invData.currentStock) || 0;
                    let conv = parseFloat(invData.conversionRate) || parseFloat(invData.conversion) || 1;
                    
                    // Convert current system stock into "Purchase UOMs" so we can average the prices properly
                    let currentStockPurch = currentStockBase / conv;
                    let currentPurchCost = parseFloat(invData.purchaseCost) || parseFloat(invData.purchCost) || parseFloat(invData.cost) || 0;
                    
                    // 📊 Moving Average Formula: ((Old Stock * Old Price) + (New Stock * New Price)) / Total Stock
                    let oldTotalValue = currentStockPurch * currentPurchCost;
                    let newTotalValue = item.purchQty * item.unitCost;
                    let combinedStockPurch = currentStockPurch + item.purchQty;
                    
                    // Failsafe: If math results in <= 0, just adopt the new price!
                    let newAveragePurchCost = combinedStockPurch > 0 ? ((oldTotalValue + newTotalValue) / combinedStockPurch) : item.unitCost;
                    let newAverageBaseCost = newAveragePurchCost / conv;
                    
                    await window.updateDoc(invRef, { 
                        currentStock: currentStockBase + item.baseQty,
                        purchaseCost: newAveragePurchCost,
                        purchCost: newAveragePurchCost,
                        cost: newAveragePurchCost,
                        baseCost: newAverageBaseCost // Very important for menu profitability!
                    });

                    // Drop an audit log so you can see exactly how the price changed!
                    let priceNote = item.unitCost !== currentPurchCost 
                        ? `Price shifted from ₱${currentPurchCost.toFixed(2)} to Avg ₱${newAveragePurchCost.toFixed(2)}` 
                        : `Price stable at ₱${newAveragePurchCost.toFixed(2)}`;

                    await window.addDoc(window.collection(window.db, "stock_logs"), {
                        branch: "Main Office",
                        item: item.name,
                        uom: item.baseUom,
                        oldQty: currentStockBase,
                        newQty: currentStockBase + item.baseQty,
                        variance: item.baseQty,
                        type: "Supplier Delivery",
                        note: `Received ${item.purchQty} ${item.purchUom}. ${priceNote}`,
                        user: window.sessionUser ? window.sessionUser.cashierName : "Manager",
                        timestamp: window.serverTimestamp()
                    });
                }
            }
        }

        Swal.fire({
            title: '✅ Success!',
            text: 'Invoice logged, costs averaged, and inventory added to Main Office.',
            icon: 'success',
            confirmButtonColor: '#0f766e',
            customClass: { popup: 'rounded-2xl shadow-2xl' }
        });

        let modal = document.getElementById('addPayableModal');
        if(modal) modal.style.display = 'none';
        
        if (fileInput) fileInput.value = '';
        
        // 🔥 THE FIX: Safely clear out the inputs using the variables we already mapped!
        window.payableCart = [];
        window.renderPayableCart();
        
        if (suppBox) suppBox.value = '';
        if (invBox) invBox.value = '';
        if (amtBox) amtBox.value = '';
        
        let itemSearch = document.getElementById('payItemSearch');
        let itemQty = document.getElementById('payItemQty');
        let itemCost = document.getElementById('payItemCost');
        let itemSub = document.getElementById('payItemSubtotal');
        
        if (itemSearch) itemSearch.value = '';
        if (itemQty) itemQty.value = '';
        if (itemCost) itemCost.value = '';
        if (itemSub) itemSub.value = '';
        
        // Instant Table Refresh
        window.loadPayablesDashboard();
        if (typeof window.loadInventoryData === 'function') window.loadInventoryData();
        
    } catch (e) { 
        console.error(e);
        Swal.fire('Error', `Failed to save. Error: ${e.message}`, 'error'); 
    } finally { 
        if(btn) { btn.innerText = "💾 Log Delivery & Track Deadline"; btn.disabled = false; } 
    }
};

