window.openAddBranchModal = function() {
    document.getElementById('addBranchModal').style.display = 'flex';
    document.getElementById('newBranchName').value = '';
    
    // 🗺️ LAUNCH THE LEAFLET MAP ENGINE
    setTimeout(() => {
        if (!window.branchMapInstance) {
            // Default center perfectly over Davao City
            window.branchMapInstance = L.map('branchMap').setView([7.1907, 125.4553], 13);
            L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                attribution: '© OpenStreetMap contributors'
            }).addTo(window.branchMapInstance);
            
            window.branchMarker = L.marker([7.1907, 125.4553], {draggable: true}).addTo(window.branchMapInstance);
            
            // Listen for dragging the pin to save exact coordinates
            window.branchMarker.on('dragend', function(event) {
                var position = window.branchMarker.getLatLng();
                document.getElementById('newBranchLat').value = position.lat;
                document.getElementById('newBranchLng').value = position.lng;
            });

            // Set default hidden values immediately
            document.getElementById('newBranchLat').value = 7.1907;
            document.getElementById('newBranchLng').value = 125.4553;
        }
        window.branchMapInstance.invalidateSize(); // Fixes rendering glitch inside hidden modals
    }, 300);
};

// ==========================================
// 🏢 BRANCH CREATION ENGINE (WITH TRUE GPS SYNC)
// ==========================================
window.saveNewBranch = async function() {
    let name = document.getElementById('newBranchName').value.trim();
    // 🔥 Grab the hidden GPS coordinates from the Leaflet Map!
    let lat = document.getElementById('newBranchLat') ? document.getElementById('newBranchLat').value : null;
    let lng = document.getElementById('newBranchLng') ? document.getElementById('newBranchLng').value : null;
    
    if (!name) return Swal.fire('Error', 'Branch name is required!', 'error');
    
    if (window.globalActiveBranches.includes(name)) {
        return Swal.fire('Duplicate', 'A branch with this name already exists!', 'warning');
    }

    let btn = document.getElementById('btnSaveNewBranch');
    btn.innerText = "⏳ Provisioning..."; btn.disabled = true;

    try {
        let payload = { 
            name: name, 
            isCore: false, 
            createdAt: serverTimestamp() 
        };
        
        // 🔥 Inject the exact map coordinates into the payload!
        if (lat && lng) {
            payload.lat = parseFloat(lat);
            payload.lng = parseFloat(lng);
        }

        await addDoc(collection(db, "branches"), payload);
        
        Swal.fire({
            title: '🎉 Branch Online!',
            text: `${name} is now officially integrated into the TAKODEÁL system with GPS tracking!`,
            icon: 'success',
            confirmButtonColor: '#8b5cf6', 
            customClass: { popup: 'rounded-2xl shadow-xl' }
        });
        
        window.autoSetupNewBranch(name); 
        
        document.getElementById('addBranchModal').style.display = 'none';
        window.loadBranchManager();
    } catch (e) {
        console.error(e); Swal.fire('Error', 'Failed to add branch.', 'error');
    } finally {
        btn.innerText = "🚀 Launch Branch"; btn.disabled = false;
    }
};

window.deleteBranch = async function(docId, name) {
    if (!confirm(`⚠️ CRITICAL WARNING!\n\nAre you sure you want to delete the branch: ${name}?`)) return;
    let confirmText = prompt(`Type DELETE to confirm removal of ${name}:`);
    if (confirmText !== "DELETE") return;

    try {
        await deleteDoc(doc(db, "branches", docId));
        alert(`🗑️ ${name} has been taken offline.`);
        
        // 🔥 THE FIX: Passed the 'name' variable directly into the Automator!
        window.autoCleanupDeletedBranch(name);
        
        window.loadBranchManager();
    } catch (e) { console.error(e); alert("Failed to delete branch."); }
};

// ⚙️ CENTRAL SETTINGS CONTROLLER (WITH ROYALTY ENGINE)
window.updateReceiptPreview = function() {
    let header = document.getElementById('settingHeaderName').value || 'TAKODEAL';
    let addr = document.getElementById('settingAddress').value || 'Branch Address';
    let contact = document.getElementById('settingContact').value || '09xx';
    let footer = document.getElementById('settingFooterMsg').value || 'Acknowledgement Receipt\nThank you!';
    let pSize = document.getElementById('settingPrinterSize').value;

    // Simulate what the thermal printer does (strip accents)
    let cleanHeader = header.toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    // Widen paper for 80mm preview
    let width = pSize === '80mm' ? '360px' : '280px';
    document.getElementById('receiptPreviewBox').style.width = width;

    document.getElementById('prevHeader').innerText = cleanHeader;
    document.getElementById('prevAddress').innerText = addr;
    document.getElementById('prevContact').innerText = `Contact: ${contact}`;
    document.getElementById('prevFooter').innerHTML = footer.split('\n').join('<br>');
};

window.uploadedLogoBase64 = "";

window.handleLogoUpload = function(event) {
    const file = event.target.files[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = function(e) {
            window.uploadedLogoBase64 = e.target.result;
            document.getElementById('logoPreviewImg').src = window.uploadedLogoBase64;
            document.getElementById('logoPreviewContainer').style.display = 'inline-block';
            document.getElementById('logoUploadPrompt').style.display = 'none';
            // 🔥 THE FIX: Hide the file picker so it stops blocking the X button!
            document.getElementById('logoUploader').style.display = 'none'; 
        }
        reader.readAsDataURL(file);
    }
};

window.removeLogo = function(event) {
    if (event) { event.preventDefault(); event.stopPropagation(); }
    window.uploadedLogoBase64 = "";
    document.getElementById('logoPreviewContainer').style.display = 'none';
    document.getElementById('logoUploadPrompt').style.display = 'block';
    document.getElementById('logoUploader').value = "";
    // 🔥 THE FIX: Bring the file picker back!
    document.getElementById('logoUploader').style.display = 'block'; 
};

window.openBranchSettings = function(docId) {
    let d = window.globalBranchData[docId];
    if (!d) return;

    document.getElementById('settingBranchId').value = docId;
    document.getElementById('branchSettingsTitle').innerText = `⚙️ ${d.name} Settings`;
    document.getElementById('settingAddress').value = d.address || '';
    document.getElementById('settingContact').value = d.contact || '';
    document.getElementById('settingLat').value = d.lat || '';
    document.getElementById('settingLng').value = d.lng || '';
    document.getElementById('settingWifi').value = d.wifi || '';
    
    // Default to 58mm to fix the squished text bug!
    document.getElementById('settingPrinterSize').value = d.printerSize || '58mm';
    
    document.getElementById('settingHeaderName').value = d.headerName || 'TAKODEAL';
    document.getElementById('settingFooterMsg').value = d.footerMessage || 'Acknowledgement Receipt\nThank you!';
    document.getElementById('settingRoyalty').value = d.royaltyPercent || 0;
    
    document.getElementById('logoWidthScale').value = d.logoWidthScale || "1";
    document.getElementById('logoHeightScale').value = d.logoHeightScale || "1";

    if (d.receiptLogoBase64) {
        window.uploadedLogoBase64 = d.receiptLogoBase64;
        document.getElementById('logoPreviewImg').src = d.receiptLogoBase64;
        document.getElementById('logoPreviewContainer').style.display = 'inline-block';
        document.getElementById('logoUploadPrompt').style.display = 'none';
    } else {
        window.removeLogo();
    }
    if (document.getElementById('settingMallBranch')) document.getElementById('settingMallBranch').checked = d.isMallBranch || false;
    document.getElementById('branchSettingsModal').style.display = 'flex';
};

window.saveBranchSettings = async function() {
    let docId = document.getElementById('settingBranchId').value;
    let latVal = document.getElementById('settingLat').value;
    let lngVal = document.getElementById('settingLng').value;

    let payload = {
        address: document.getElementById('settingAddress').value.trim(),
        contact: document.getElementById('settingContact').value.trim(),
        wifi: document.getElementById('settingWifi').value.trim(),
        printerSize: document.getElementById('settingPrinterSize').value,
        headerName: document.getElementById('settingHeaderName').value.trim(),
        footerMessage: document.getElementById('settingFooterMsg').value.trim(),
        royaltyPercent: parseFloat(document.getElementById('settingRoyalty').value) || 0,
        receiptLogoBase64: window.uploadedLogoBase64, 
        logoWidthScale: parseFloat(document.getElementById('logoWidthScale').value) || 1,
        logoHeightScale: parseFloat(document.getElementById('logoHeightScale').value) || 1,
        isMallBranch: document.getElementById('settingMallBranch') ? document.getElementById('settingMallBranch').checked : false,
        lat: latVal ? parseFloat(latVal) : null,
        lng: lngVal ? parseFloat(lngVal) : null
    };

    try {
        await updateDoc(doc(db, "branches", docId), payload);
        Swal.fire({toast: true, position: 'top-end', icon: 'success', title: 'Settings Pushed to Cashier!', showConfirmButton: false, timer: 2000});
        document.getElementById('branchSettingsModal').style.display = 'none';
        window.loadBranchManager();
    } catch (e) { console.error(e); alert("Failed to push settings."); }
};

