// 🌍 BRANCH ECOSYSTEM AUTOMATOR
// ==========================================

window.autoSetupNewBranch = async function(branchName) {
    try {
        // 1. Add Default Shifts to Schedule Manager
        const schedRef = doc(db, "settings", "global_schedule");
        const schedSnap = await getDoc(schedRef);
        if (schedSnap.exists()) {
            let data = schedSnap.data();
            if (!data.branchConfig) data.branchConfig = {};
            if (!data.branchConfig[branchName]) {
                data.branchConfig[branchName] = [
                    // 🔥 THE FIX: Added the 'active' and 'days' arrays so the calendar doesn't crash!
                    { id: 'shift_1', name: 'Morning (9am-5:30pm)', active: true, days: [0,1,2,3,4,5,6] },
                    { id: 'shift_2', name: 'Mid (4:30pm-12:30am)', active: true, days: [0,1,2,3,4,5,6] },
                    { id: 'shift_3', name: 'Night 1 (6:30pm-3am)', active: true, days: [0,1,2,3,4,5,6] }
                ];
                await updateDoc(schedRef, { branchConfig: data.branchConfig });
            }
        }

        // 2. Clone Cabantian's Live Inventory (with 0 stock)
        const cabantianInv = collection(db, "inventory_Cabantian");
        const newBranchInv = collection(db, "inventory_" + branchName);
        const snap = await getDocs(cabantianInv);
        
        snap.forEach(async (docSnap) => {
            let item = docSnap.data();
            item.stock = 0; // Reset stock to 0 for the new branch
            await setDoc(doc(newBranchInv, docSnap.id), item);
        });

        console.log("✅ Auto-Setup Complete for", branchName);
    } catch(e) { console.error("Auto Setup Error:", e); }
};

window.autoCleanupDeletedBranch = async function(branchName) {
    try {
        // Remove from Schedule Manager
        const schedRef = doc(db, "settings", "global_schedule");
        const schedSnap = await getDoc(schedRef);
        if (schedSnap.exists()) {
            let data = schedSnap.data();
            let needsUpdate = false;
            
            if (data.branchConfig && data.branchConfig[branchName]) {
                delete data.branchConfig[branchName];
                needsUpdate = true;
            }
            
            if (data.currentSchedule) {
                for (let day in data.currentSchedule) {
                    if (data.currentSchedule[day][branchName]) {
                        delete data.currentSchedule[day][branchName];
                        needsUpdate = true;
                    }
                }
            }
            if (needsUpdate) await updateDoc(schedRef, { branchConfig: data.branchConfig, currentSchedule: data.currentSchedule });
        }
        console.log("🗑️ Auto-Cleanup Complete for", branchName);
    } catch(e) { console.error("Auto Cleanup Error:", e); }
};

// 🔥 UNIVERSAL NICKNAME FORMATTER (For Step 3)
window.formatDisplayName = function(realName) {
    if (!realName || realName === "N/A" || realName === "UNFILLED" || realName === "-") return realName;
    let profile = window.findEmployeeProfile(realName);
    if (profile) return profile.scheduleNickname || profile.scheduleName || profile.cashierName || realName;
    return realName;
};

window.deleteCurrentStaff = async function() {
    // 🔥 BULLETPROOF EXTRACTOR: Grabs the ID and Name directly from the active modal!
    const getVal = (id) => {
        let els = document.querySelectorAll(`[id="${id}"]`);
        let activeEl = Array.from(els).find(el => {
            let modal = el.closest('[id="employeeProfileModal"]');
            return modal && modal.style.display !== 'none';
        });
        return activeEl ? activeEl.value : (els[0] ? els[0].value : '');
    };

    let docId = getVal('empProfileId');
    let expectedName = getVal('empFullName').trim();

    if (!docId) {
        return Swal.fire('Error', 'No profile selected to delete. Please save the profile first.', 'error');
    }

    // Prompt the user to type the name manually to prevent accidental clicks
    let typedName = prompt(`⚠️ WARNING: This will permanently delete ${expectedName} and remove them from the entire system.\n\nTo confirm, type their exact Full Name:`);

    if (!typedName) return; // User clicked cancel or left it blank

    // Check if the typed name matches the expected name (case-insensitive)
    if (typedName.trim().toLowerCase() !== expectedName.toLowerCase()) {
        return alert("❌ Deletion Failed: Staff name did not match exactly.");
    }

    Swal.fire({title: 'Deleting Staff...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        // 1. Permanently delete from Firebase Cloud!
        await deleteDoc(doc(db, "cashiers", docId));

        // 2. Clear them out of the local app memory
        if (window.globalStaffData && window.globalStaffData[docId]) {
            delete window.globalStaffData[docId];
        }

        Swal.fire('✅ Deleted!', `${expectedName} has been permanently removed from the system.`, 'success');

        // 3. Close the modal and instantly refresh the HR table
        document.querySelectorAll('[id="employeeProfileModal"]').forEach(el => el.style.display = 'none');
        window.loadHRModule();

    } catch (error) {
        console.error("Error deleting staff:", error);
        Swal.fire('Error', 'Failed to delete staff member. Check your internet connection.', 'error');
    }
};

