// ========================================================
// 📈 7-DAY REVENUE TREND & TOP 5 CATEGORY CHART ENGINE
// ========================================================
window.chartFilters = { cash: true, gcash: true, grab: true, foodpanda: true };
window.revenueChartInstance = null;
window.categoryMixChartInstance = null;

window.toggleChartFilter = function(filterType) {
    window.chartFilters[filterType] = !window.chartFilters[filterType];
    const cashBtn = document.getElementById('btnFilterCash');
    const gcashBtn = document.getElementById('btnFilterGcash');
    const grabBtn = document.getElementById('btnFilterGrab');
    const fpBtn = document.getElementById('btnFilterFoodpanda');

    if (cashBtn) { cashBtn.style.background = window.chartFilters.cash ? '#334155' : '#e2e8f0'; cashBtn.style.color = window.chartFilters.cash ? '#ffffff' : '#94a3b8'; }
    if (gcashBtn) { gcashBtn.style.background = window.chartFilters.gcash ? '#0284c7' : '#e2e8f0'; gcashBtn.style.color = window.chartFilters.gcash ? '#ffffff' : '#94a3b8'; }
    if (grabBtn) { grabBtn.style.background = window.chartFilters.grab ? '#00b14f' : '#e2e8f0'; grabBtn.style.color = window.chartFilters.grab ? '#ffffff' : '#94a3b8'; }
    if (fpBtn) { fpBtn.style.background = window.chartFilters.foodpanda ? '#d70f64' : '#e2e8f0'; fpBtn.style.color = window.chartFilters.foodpanda ? '#ffffff' : '#94a3b8'; }

    window.renderDashboardCharts();
};

window.renderDashboardCharts = async function() {
    const lineCanvas = document.getElementById('revenueTrendChart');
    const pieCanvas = document.getElementById('categoryMixChart');
    if (!lineCanvas) return;

    try {
        const toLocalISODate = (d) => new Date(d.getTime() - (d.getTimezoneOffset() * 60000)).toISOString().split('T')[0];
        
        const startDateInput = document.getElementById('dashStartDate');
        const endDateInput = document.getElementById('dashEndDate');
        
        let startDay = startDateInput && startDateInput.value ? new Date(startDateInput.value) : new Date();
        startDay.setHours(8, 30, 0, 0); // 🔥 8:30 AM Business Day
        
        let endDay = endDateInput && endDateInput.value ? new Date(endDateInput.value) : new Date();
        endDay.setDate(endDay.getDate() + 1);
        endDay.setHours(3, 59, 59, 999); // 🔥 3:59 AM Next Day

        let daysDiff = Math.round((endDay - startDay) / (1000 * 60 * 60 * 24));
        let isMonthly = daysDiff > 31; 
        
        let labels = [];
        let dateKeys = []; 

        // 🔥 THE CHART FIX: If you select 1 to 6 days, FORCE it to look back 7 days automatically!
        if (daysDiff <= 6) {
            let anchorDate = new Date(endDay.getTime());
            anchorDate.setDate(anchorDate.getDate() - 1); 
            
            for (let i = 6; i >= 0; i--) {
                let d = new Date(anchorDate.getTime());
                d.setDate(anchorDate.getDate() - i);
                dateKeys.push(toLocalISODate(d));
                labels.push(d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));
            }
            
            // Push the database query window backward so it actually fetches all 7 days of data!
            startDay = new Date(anchorDate.getTime());
            startDay.setDate(startDay.getDate() - 6);
            startDay.setHours(8, 30, 0, 0);
            
            daysDiff = 7; 
        } 
        else if (isMonthly) {
            let curr = new Date(startDay.getFullYear(), startDay.getMonth(), 1);
            let endMonth = new Date(endDay.getFullYear(), endDay.getMonth(), 1);
            while (curr <= endMonth) {
                let y = curr.getFullYear();
                let m = String(curr.getMonth() + 1).padStart(2, '0');
                dateKeys.push(`${y}-${m}`);
                labels.push(curr.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }));
                curr.setMonth(curr.getMonth() + 1);
            }
        } else {
            for (let i = 0; i < daysDiff; i++) {
                let d = new Date(startDay);
                d.setDate(startDay.getDate() + i);
                dateKeys.push(toLocalISODate(d));
                labels.push(d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));
            }
        }

        let titleEl = document.getElementById('revenueChartTitle');
        if (titleEl) {
            let spanIcon = `<span style="font-size: 20px;">📈</span>`;
            if (isMonthly) {
                titleEl.innerHTML = `${spanIcon} Monthly Gross Revenue Trend`;
            } else {
                titleEl.innerHTML = `${spanIcon} ${daysDiff}-Day Gross Revenue Trend`;
            }
        }

        const q = window.query(window.collection(window.db, "transactions"), window.where("timestamp", ">=", startDay), window.where("timestamp", "<=", endDay));
        const snap = await window.getDocs(q);

        const menuSnap = await window.getDocs(window.collection(window.db, "menu"));
        let menuCategories = {};
        menuSnap.forEach(doc => { menuCategories[doc.data().name] = doc.data().category || 'Uncategorized'; });

        const branchColors = {
            "Cabantian": { border: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)" },
            "Citygate":  { border: "#8b5cf6", bg: "rgba(139, 92, 246, 0.1)" },
            "Maa":       { border: "#0284c7", bg: "rgba(2, 132, 199, 0.1)" },
            "Main Office": { border: "#10b981", bg: "rgba(16, 185, 129, 0.1)" }
        };

        let activeBranches = window.globalActiveBranches ? window.globalActiveBranches.filter(b => b !== "Main Office") : ["Cabantian", "Citygate", "Maa"];
        if (window.sessionUser && window.sessionUser.isFranchisee) activeBranches = window.sessionUser.allowedBranches;
        
        let branchSalesData = {};
        activeBranches.forEach(b => { 
            branchSalesData[b] = {}; 
            dateKeys.forEach(k => branchSalesData[b][k] = 0); 
        });

        let categorySales = {}; 
        
        let liveBusinessDay = new Date();
        // 🔥 Apply the new 8:30 AM logic to the Pie Chart as well!
        if (liveBusinessDay.getHours() < 8 || (liveBusinessDay.getHours() === 8 && liveBusinessDay.getMinutes() < 30)) {
            liveBusinessDay.setDate(liveBusinessDay.getDate() - 1);
        }
        let todayStr = toLocalISODate(liveBusinessDay);

        snap.forEach(docSnap => {
            let tx = docSnap.data();
            if (tx.status === "Voided") return;

            let txBranch = tx.branch || "Unknown";
            let txDateObj = tx.timestamp ? (tx.timestamp.toDate ? tx.timestamp.toDate() : new Date(tx.timestamp)) : null;

            if (txDateObj) {
                let businessDateObj = new Date(txDateObj.getTime());
                if (businessDateObj.getHours() < 8 || (businessDateObj.getHours() === 8 && businessDateObj.getMinutes() < 30)) {
                    businessDateObj.setDate(businessDateObj.getDate() - 1);
                }
                let exactLocalStr = toLocalISODate(businessDateObj);

                let keyToUse = "";
                if (isMonthly) {
                    let y = businessDateObj.getFullYear();
                    let m = String(businessDateObj.getMonth() + 1).padStart(2, '0');
                    keyToUse = `${y}-${m}`;
                } else {
                    keyToUse = exactLocalStr;
                }

                if (branchSalesData[txBranch] && branchSalesData[txBranch][keyToUse] !== undefined) {
                    let txGross = parseFloat(tx.subTotalBeforeDiscount);
                    if (isNaN(txGross) || txGross < tx.netTotal) txGross = parseFloat(tx.netTotal) || 0;

                    if (tx.splitDetails && Array.isArray(tx.splitDetails)) {
                        tx.splitDetails.forEach(split => {
                            let method = (split.method || '').toLowerCase();
                            if ((method === 'cash' && window.chartFilters.cash) || 
                                (method.includes('gcash') && window.chartFilters.gcash) || 
                                (method.includes('grab') && window.chartFilters.grab) || 
                                (method.includes('foodpanda') && window.chartFilters.foodpanda)) {
                                let ratio = (tx.netTotal > 0) ? (parseFloat(split.amount) / parseFloat(tx.netTotal)) : 0;
                                branchSalesData[txBranch][keyToUse] += (txGross * ratio);
                            }
                        });
                    } else {
                        let method = (tx.paymentMethod || 'cash').toLowerCase();
                        let isCash = (method === 'cash' || method === '' || method.includes('store use')) && window.chartFilters.cash;
                        let isGcash = method.includes('gcash') && window.chartFilters.gcash;
                        let isGrab = method.includes('grab') && window.chartFilters.grab;
                        let isFoodpanda = method.includes('foodpanda') && window.chartFilters.foodpanda;
                        let isOtherDigital = !isCash && !isGcash && !isGrab && !isFoodpanda && window.chartFilters.gcash; 

                        if (isCash || isGcash || isGrab || isFoodpanda || isOtherDigital) {
                            branchSalesData[txBranch][keyToUse] += txGross;
                        }
                    }
                }
            }

            if (txDateObj) {
                let businessDateObj = new Date(txDateObj.getTime());
                if (businessDateObj.getHours() < 8 || (businessDateObj.getHours() === 8 && businessDateObj.getMinutes() < 30)) {
                    businessDateObj.setDate(businessDateObj.getDate() - 1);
                }
                
                if (toLocalISODate(businessDateObj) === todayStr && pieCanvas && tx.cart && window.isBranchAllowed(txBranch)) {
                    tx.cart.forEach(item => {
                        let itemName = item.name || item.itemName;
                        let cat = menuCategories[itemName] || item.category || "Uncategorized";
                        let lineTotal = item.lineTotalFinal !== undefined ? item.lineTotalFinal : ((item.variantPrice || item.basePrice || 0) * (item.qty || 1));
                        if (!categorySales[cat]) categorySales[cat] = 0;
                        categorySales[cat] += lineTotal;
                    });
                }
            }
        });

        let lineDatasets = [];
        activeBranches.forEach(branch => {
            let color = branchColors[branch] || { border: "#0f766e", bg: "rgba(15, 118, 110, 0.1)" };
            lineDatasets.push({
                label: branch, 
                data: dateKeys.map(k => branchSalesData[branch][k]), 
                borderColor: color.border, backgroundColor: color.bg, borderWidth: 3, tension: 0.4, fill: true, pointRadius: 4, pointHoverRadius: 6
            });
        });

        if (window.revenueChartInstance) window.revenueChartInstance.destroy();
        window.revenueChartInstance = new Chart(lineCanvas.getContext('2d'), {
            type: 'line', data: { labels: labels, datasets: lineDatasets },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'top', labels: { font: { weight: 'bold', size: 12 } } }, tooltip: { callbacks: { label: function(context) { return ` ${context.dataset.label}: ₱${context.parsed.y.toLocaleString(undefined, {minimumFractionDigits: 2})}`; } } } }, scales: { y: { beginAtZero: true, ticks: { callback: function(value) { return '₱' + value.toLocaleString(); } } } } }
        });

        if (pieCanvas) {
            let sortedCats = Object.keys(categorySales).map(cat => ({ name: cat, sales: categorySales[cat] })).sort((a, b) => b.sales - a.sales);
            let top5 = sortedCats.slice(0, 5); 
            
            if (window.categoryMixChartInstance) window.categoryMixChartInstance.destroy();
            const ctxPie = pieCanvas.getContext('2d');
            
            if (top5.length === 0) {
                window.categoryMixChartInstance = new Chart(ctxPie, { type: 'doughnut', data: { labels: ["No Sales Today"], datasets: [{ data: [1], backgroundColor: ['#e2e8f0'] }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { tooltip: { enabled: false }, legend: { display: false } } } });
            } else {
                window.categoryMixChartInstance = new Chart(ctxPie, {
                    type: 'doughnut',
                    data: { labels: top5.map(c => c.name), datasets: [{ data: top5.map(c => c.sales), backgroundColor: ['#0ea5e9', '#f59e0b', '#8b5cf6', '#10b981', '#ef4444'], borderWidth: 2, borderColor: '#ffffff' }] },
                    options: { responsive: true, maintainAspectRatio: false, cutout: '65%', plugins: { legend: { position: 'right', labels: { font: { weight: 'bold', size: 11 } } }, tooltip: { callbacks: { label: function(context) { return ` ${context.label}: ₱${context.parsed.toLocaleString(undefined, {minimumFractionDigits: 2})}`; } } } } }
                });
            }
        }
    } catch(e) { console.error("Chart Error:", e); }
};

// ========================================================
// 🧠 PHASE 5: SMART BURN RATE & AI DELIVERY SCHEDULER
// ========================================================
window.globalForecasterData = []; 
window.isForecasterLoading = false; 

window.loadForecasterEngine = async function() {
    let branchSelect = document.getElementById('forecasterBranchSelect');
    let branch = branchSelect ? branchSelect.value : 'Cabantian';
    let grid = document.getElementById('forecasterGrid');
    if (!grid) return;

    window.isForecasterLoading = true; // Lock the search bar to prevent crashes

    let btnRun = document.getElementById('btnRunForecaster') || document.querySelector('button[onclick="window.loadForecasterEngine()"]');
    if (btnRun) { btnRun.innerText = "⏳ Scanning..."; btnRun.disabled = true; }

    grid.innerHTML = '<div style="grid-column: 1/-1; text-align: center; padding: 40px; color: #0ea5e9; font-weight: bold; font-size: 16px;">⏳ Deep scanning stock history... Please wait.</div>';

    try {
        let today = new Date();
        let fourteenDaysAgo = new Date();
        fourteenDaysAgo.setDate(today.getDate() - 14);
        let fourteenDaysMs = fourteenDaysAgo.getTime();

        // 1. Fetch Live Inventory & Extract Categories
        const invQ = query(collection(db, "inventory"), where("branch", "==", branch));
        const invSnap = await getDocs(invQ);
        
        let inventoryItems = [];
        let categories = new Set();
        invSnap.forEach(doc => {
            let data = doc.data();
            data.id = doc.id;
            inventoryItems.push(data);
            if (data.category && typeof data.category === 'string' && data.category.trim() !== "") {
                categories.add(data.category.trim());
            }
        });

        if (inventoryItems.length === 0) {
            grid.innerHTML = `<div style="grid-column: 1/-1; text-align: center; padding: 40px; color: #dc2626; font-weight: bold; font-size: 16px;">No inventory found for ${branch}. Please add items first.</div>`;
            window.isForecasterLoading = false;
            return;
        }

        // Populate Category Dropdown dynamically
        let catDrop = document.getElementById('fcCategory');
        if (catDrop) {
            let currentVal = catDrop.value;
            let catHtml = '<option value="All">All Categories</option>';
            Array.from(categories).sort().forEach(c => { catHtml += `<option value="${c}">${c}</option>`; });
            catDrop.innerHTML = catHtml;
            if (currentVal !== "All" && Array.from(categories).includes(currentVal)) catDrop.value = currentVal; 
            else catDrop.value = "All";
        }

        // 2. 🔥 THE INDESTRUCTIBLE MATH FIX: Simple WHERE clause prevents ALL Firebase Index crashes!
        const logsQ = query(collection(db, "stock_logs"), where("branch", "==", branch));
        const logsSnap = await getDocs(logsQ);

        let burnData = {};
        
        logsSnap.forEach(doc => {
            let log = doc.data();
            let logTimeMs = 0;
            if (log.timestamp) {
                if (log.timestamp.toDate) logTimeMs = log.timestamp.toDate().getTime();
                else logTimeMs = new Date(log.timestamp).getTime();
            }
            
            // Only process logs that happened in the last 14 days
            if (logTimeMs >= fourteenDaysMs) {
                let v = parseFloat(log.variance) || 0;
                let t = (log.type || "").toLowerCase();
                let itemName = (log.item || "").trim().toLowerCase(); 
                
                // Matches Sales, Waste, Prep, and Adjustments!
                if (v < 0 && (t.includes("deduction") || t.includes("waste") || t.includes("spoilage") || t.includes("store use") || t.includes("prep") || t.includes("adjustment") || t.includes("voided") || t.includes("penalty"))) {
                    if (!burnData[itemName]) burnData[itemName] = 0;
                    burnData[itemName] += Math.abs(v);
                }
            }
        });

        // 3. Process Burn Rate Data
        window.globalForecasterData = inventoryItems.map(item => {
            let normalizedItemName = (item.name || "").trim().toLowerCase();
            let totalBurn = burnData[normalizedItemName] || 0;
            let dailyBurn = totalBurn / 14;
            let stock = parseFloat(item.currentStock) || 0;
            let daysLeft = dailyBurn > 0 ? (stock / dailyBurn) : Infinity;

            return { ...item, totalBurn, dailyBurn, daysLeft };
        });

        // Sort by most critical (lowest days left)
        window.globalForecasterData.sort((a, b) => a.daysLeft - b.daysLeft);
        
        window.isForecasterLoading = false; 
        window.filterForecaster(); 

    } catch(e) {
        console.error("Forecaster Error:", e);
        window.isForecasterLoading = false;
        // If it ever fails again, it will print the exact Firebase error directly to the screen so we can see it!
        grid.innerHTML = `<div style="grid-column: 1/-1; text-align: center; padding: 40px; color: #dc2626; font-weight: bold;">❌ Database Error: ${e.message}</div>`;
    } finally {
        if (btnRun) { btnRun.innerText = "🔄 Run Calculation"; btnRun.disabled = false; }
    }
};

window.filterForecaster = function() {
    if (window.isForecasterLoading) return; // 🔥 SAFETY LOCK: Prevents typing from interrupting loading!

    let grid = document.getElementById('forecasterGrid');
    if (!grid) return;

    let searchInput = document.getElementById('fcSearch');
    let search = searchInput ? searchInput.value.toLowerCase() : "";
    let catDrop = document.getElementById('fcCategory');
    let cat = catDrop ? catDrop.value : "All";

    if (!window.globalForecasterData || window.globalForecasterData.length === 0) {
        grid.innerHTML = '<div style="grid-column: 1/-1; text-align: center; padding: 40px; color: #94a3b8; font-weight: bold; font-size: 16px;">Data not loaded. Please click "Run Calculation".</div>';
        return;
    }

    let filtered = window.globalForecasterData.filter(item => {
        let matchSearch = (item.name || "").toLowerCase().includes(search);
        let matchCat = cat === "All" || item.category === cat;
        return matchSearch && matchCat;
    });

    let html = '';
    let catsObj = {};
    
    // Group by category to make it clean!
    filtered.forEach(item => {
        let c = item.category || "Uncategorized";
        if (!catsObj[c]) catsObj[c] = [];
        catsObj[c].push(item);
    });

    Object.keys(catsObj).sort().forEach(category => {
        html += `<div style="grid-column: 1/-1; background: #e2e8f0; padding: 12px 20px; font-weight: 900; color: #334155; border-radius: 8px; text-transform: uppercase; margin-top: 10px; font-size: 15px; border-left: 4px solid #94a3b8;">📁 ${category}</div>`;
        
        catsObj[category].forEach(item => {
            let stockColor = item.currentStock <= 0 ? "#dc2626" : (item.daysLeft <= 3 ? "#ea580c" : "#334155");
            let burnColor = item.dailyBurn > 0 ? "#16a34a" : "#94a3b8";
            
            let daysBoxBg = item.daysLeft <= 0 ? "#fef2f2" : (item.daysLeft <= 3 ? "#fffbeb" : "#f0fdf4");
            let daysBoxCol = item.daysLeft <= 0 ? "#dc2626" : (item.daysLeft <= 3 ? "#d97706" : "#16a34a");
            let daysBoxBorder = item.daysLeft <= 0 ? "#fca5a5" : (item.daysLeft <= 3 ? "#fcd34d" : "#bbf7d0");
            
            let daysText = item.daysLeft === Infinity ? "∞" : item.daysLeft.toFixed(1);
            let statusText = item.currentStock < 0 ? "NEGATIVE STOCK (Audit Needed)" : (item.daysLeft <= 0 ? "Out of Stock Now" : (item.daysLeft <= 3 ? "Critical (Reorder Immediately)" : "Sufficient Stock"));
            let statusColor = item.currentStock < 0 ? "#dc2626" : (item.daysLeft <= 0 ? "#dc2626" : (item.daysLeft <= 3 ? "#ea580c" : "#16a34a"));

            // 🔥 THE PAR LEVEL INTEGRATION 🔥
            let conv = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;
            let bUom = item.uom || 'units';
            let pUom = item.purchaseUom || item.purchUom || bUom;
            
            let targetParBase = parseFloat(item.maintainingStock) || 0;
            let parHtml = '';

            if (targetParBase > 0) {
                let deficitBase = targetParBase - item.currentStock;
                let isDeficit = deficitBase > 0;
                
                // Helper to cleanly format [Pack] + [Piece] based on Conversion Rates
                let formatDualQty = (totalBase) => {
                    let wPurch = 0; let rBase = totalBase;
                    if (conv > 1 && pUom.toLowerCase() !== bUom.toLowerCase()) {
                        wPurch = Math.floor(totalBase / conv);
                        rBase = totalBase - (wPurch * conv);
                        if (totalBase < 0) {
                            wPurch = Math.ceil(totalBase / conv);
                            rBase = totalBase - (wPurch * conv);
                        }
                    }
                    let str = '';
                    if (wPurch !== 0) str += `<strong style="font-size: 16px;">${wPurch}</strong> <span style="font-size:10px; color:#64748b; text-transform: uppercase;">${pUom}</span> `;
                    if (rBase !== 0 || wPurch === 0) str += `<strong style="font-size: 16px;">${rBase.toFixed(1)}</strong> <span style="font-size:10px; color:#64748b; text-transform: uppercase;">${bUom}</span>`;
                    return str;
                };

                let defStr = isDeficit ? formatDualQty(deficitBase) : '<span style="color:#16a34a; font-size: 13px;">✅ Stock is Full</span>';
                
                parHtml = `
                    <div style="background: #f0fdf4; border: 1px dashed #16a34a; padding: 12px; border-radius: 8px; margin-bottom: 15px;">
                        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
                            <span style="font-size: 11px; color: #15803d; font-weight: 800; text-transform: uppercase;">Target Par Level:</span>
                            <span style="color: #16a34a;">${formatDualQty(targetParBase)}</span>
                        </div>
                        <div style="display: flex; justify-content: space-between; align-items: center; border-top: 1px dashed #bbf7d0; padding-top: 8px;">
                            <span style="font-size: 11px; color: #b91c1c; font-weight: 800; text-transform: uppercase;">Qty to Restock:</span>
                            <span style="color: #dc2626;">${isDeficit ? '+ ' + defStr : defStr}</span>
                        </div>
                    </div>
                `;
                
                // Adjust status text to match par level override
                if (isDeficit) {
                    statusText = "Below Par Level (Needs Restock)";
                    statusColor = "#d97706";
                } else {
                    statusText = "At or Above Par Level";
                    statusColor = "#16a34a";
                }
            }

            html += `
            <div style="background: white; border: 1px solid #cbd5e1; border-radius: 12px; padding: 20px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); display: flex; flex-direction: column; justify-content: space-between; transition: 0.2s;" onmouseover="this.style.transform='translateY(-2px)'; this.style.boxShadow='0 10px 15px -3px rgba(0,0,0,0.1)';" onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='0 4px 6px -1px rgba(0,0,0,0.05)';">
                <div style="display: flex; gap: 15px; margin-bottom: 20px;">
                    <div style="width: 45px; height: 45px; border-radius: 8px; background: #f8fafc; border: 1px solid #e2e8f0; display: flex; align-items: center; justify-content: center; font-size: 24px; flex-shrink: 0;">📦</div>
                    <div>
                        <div style="font-weight: 900; color: #0f172a; font-size: 15px;">${item.name}</div>
                        <div style="font-size: 11px; color: #94a3b8; font-weight: bold; text-transform: uppercase;">${item.branch}</div>
                    </div>
                </div>
                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; padding-bottom: 15px; border-bottom: 1px dashed #e2e8f0;">
                    <div>
                        <div style="font-size: 13px; color: #64748b; margin-bottom: 5px;">Current Stock: <strong style="color: ${stockColor}; font-size: 15px;">${item.currentStock.toFixed(1)} <span style="font-size: 11px;">${item.uom}</span></strong></div>
                        <div style="font-size: 13px; color: #64748b;">Daily Burn Rate: <strong style="color: ${burnColor}; font-size: 14px;">${item.dailyBurn.toFixed(2)} <span style="font-size: 11px;">${item.uom} / day</span></strong></div>
                    </div>
                    <div style="background: ${daysBoxBg}; border: 2px dashed ${daysBoxBorder}; color: ${daysBoxCol}; padding: 10px; border-radius: 8px; text-align: center; min-width: 70px;">
                        <div style="font-size: 20px; font-weight: 900; line-height: 1;">${daysText}</div>
                        <div style="font-size: 10px; font-weight: bold; text-transform: uppercase; margin-top: 4px;">Days Left</div>
                    </div>
                </div>
                ${parHtml}
                <div style="display: flex; justify-content: space-between; align-items: center; font-size: 12px; font-weight: bold;">
                    <span style="display: flex; align-items: center; gap: 5px; color: ${statusColor};"><span style="background: ${statusColor}; color: white; border-radius: 4px; padding: 2px 4px; font-size: 10px;">Status</span> ${statusText}</span>
                </div>
            </div>`;
        });
    });

    if (html === '') html = '<div style="grid-column: 1/-1; text-align: center; padding: 40px; color: #64748b; font-weight: bold; font-size: 15px;">No items match your filter.</div>';
    grid.innerHTML = html;
};

window.generateAiDispatchList = async function() {
    if (window.isForecasterLoading) return Swal.fire('Loading', 'Please wait for the calculation to finish scanning before generating a list.', 'info');
    
    if (!window.globalForecasterData || window.globalForecasterData.length === 0) {
        return Swal.fire('No Data', 'Please click "Run Calculation" first to scan the inventory.', 'warning');
    }

    let targetDateStr = document.getElementById('fcTargetDate').value;
    let bufferDays = parseInt(document.getElementById('fcBuffer').value) || 0;
    let branchSelect = document.getElementById('forecasterBranchSelect');
    let branch = branchSelect ? branchSelect.value : 'Cabantian';

    if (!targetDateStr) return Swal.fire('Missing Date', 'Please select your target Next Delivery Date.', 'warning');

    let targetDate = new Date(targetDateStr);
    let today = new Date();
    today.setHours(0,0,0,0); targetDate.setHours(0,0,0,0);
    
    let timeDiff = targetDate.getTime() - today.getTime();
    let daysUntilDelivery = Math.ceil(timeDiff / (1000 * 3600 * 24));

    if (daysUntilDelivery < 0) return Swal.fire('Invalid Date', 'The delivery date cannot be in the past.', 'error');

    let totalDaysToCover = daysUntilDelivery + bufferDays;
    let itemsToDispatch = [];

    // 🔥 THE NEW FORECASTER BRAIN: Prioritizes Par Levels first, falls back to Burn Rate!
    window.globalForecasterData.forEach(item => {
        let targetPar = parseFloat(item.maintainingStock) || 0;
        let deficit = 0;
        let requestType = "";

        if (targetPar > 0) {
            deficit = targetPar - item.currentStock;
            requestType = "Maintaining Stock (Par Fill)";
        } else if (item.dailyBurn > 0) {
            let requiredStockForPeriod = item.dailyBurn * totalDaysToCover;
            deficit = requiredStockForPeriod - item.currentStock;
            requestType = "Restock (AI Forecast)";
        }

        if (deficit > 0) {
            let convRate = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;
            let purchQtyNeeded = Math.ceil(deficit / convRate); 
            let pUom = item.purchaseUom || item.purchUom || item.uom || 'units';
            let bUom = item.uom || 'units';
            
            itemsToDispatch.push({
                itemName: item.name, name: item.name, sourceId: item.id, qty: purchQtyNeeded * convRate, rawQty: purchQtyNeeded,
                origRawQty: purchQtyNeeded, origBaseQty: purchQtyNeeded * convRate, uom: bUom, baseUom: bUom,
                purchaseUom: pUom, displayUom: pUom, friendlyUom: pUom, selectedUom: (pUom.toLowerCase() !== bUom.toLowerCase()) ? 'purch' : 'base',
                convRate: convRate, conversionRate: convRate, category: item.category || 'Ingredients', hqStock: 0, requestType: requestType
            });
        }
    });

    if (itemsToDispatch.length === 0) return Swal.fire('Sufficient Stock', `Based on current settings and burn rates, ${branch} has enough stock. No dispatch needed.`, 'success');

    Swal.fire({title: 'Generating Auto-Request...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});

    try {
        // 🔥 Sends an official Stock Request automatically!
        await window.addDoc(window.collection(window.db, "purchase_orders"), {
            branch: branch,
            items: itemsToDispatch,
            status: "Pending",
            type: "AI Auto-Forecast",
            requestedBy: "TAKODEÁL AI FORECASTER",
            timestamp: window.serverTimestamp()
        });

        Swal.fire({
            title: '⚡ AI Schedule Complete!', 
            html: `Generated a smart stock request of <b style="color: #0ea5e9;">${itemsToDispatch.length} items</b> to sustain ${branch}.<br><br>It has been sent directly to your Logistics Feed for review!`,
            icon: 'success', 
            confirmButtonText: 'Review in Logistics Feed', 
            confirmButtonColor: '#0ea5e9', 
            customClass: { popup: 'rounded-2xl' }
        }).then(() => {
            if (typeof window.loadDispatchLogs === 'function') window.loadDispatchLogs();
            window.activeLogisticsTab = 'Requests';
            window.renderLogisticsFeed();
        });
    } catch (e) {
        console.error(e);
        Swal.fire('Error', 'Failed to generate AI request.', 'error');
    }
};

// Start the watchdog 3 seconds after the Manager App loads!
setTimeout(window.initVersionWatchdog, 3000);

// ========================================================
// 📱 RESPONSIVE MOBILE ENGINE & TABLE AUTO-WRAPPER
// ========================================================
document.addEventListener("DOMContentLoaded", () => {
    
    // 1. INJECT BULLETPROOF MOBILE CSS GLOBALLY
    if (!document.getElementById('manager-mobile-fixes')) {
        const mobileStyle = document.createElement('style');
        mobileStyle.id = 'manager-mobile-fixes';
        mobileStyle.innerHTML = `
            /* Prevent the entire app body from scrolling sideways */
            body, html { overflow-x: hidden !important; width: 100%; max-width: 100vw; }
            
            /* Make the table wrapper actually scrollable */
            .mobile-table-wrapper {
                width: 100% !important;
                max-width: 100vw !important;
                overflow-x: auto !important;
                -webkit-overflow-scrolling: touch !important;
                border-radius: 8px;
                border: 1px solid #e2e8f0;
                margin-bottom: 15px;
                background: white;
            }

            /* 📱 TRIGGER MOBILE MODE ON PHONES & SMALL TABLETS */
            @media (max-width: 850px) {
                /* Force side-by-side grids to stack vertically */
                div[style*="grid-template-columns"] {
                    grid-template-columns: 1fr !important;
                    gap: 15px !important;
                }

                /* Force Flex containers to wrap their contents so buttons don't hide */
                div[style*="display: flex"] {
                    flex-wrap: wrap !important;
                }

                /* Exclude flex-wrap from certain structural elements so they don't break */
                .sidebar-header, .brand-container, td > div[style*="display: flex"], .swal2-title, .swal2-header {
                    flex-wrap: nowrap !important;
                }

                /* Make standard inputs and dropdowns full width */
                input[type="text"], input[type="number"], input[type="date"], input[type="month"], select, textarea {
                    width: 100% !important;
                    min-width: 100% !important;
                    box-sizing: border-box !important;
                }

                /* Make action buttons stretch to full width so they are easy to tap */
                button {
                    flex: 1 1 100% !important;
                    width: 100% !important;
                    margin-bottom: 5px !important;
                    white-space: normal !important;
                    height: auto !important;
                }

                /* Prevent table cells from squishing */
                table th, table td {
                    white-space: nowrap !important;
                }

                /* Make SweetAlert Modals fit the phone screen perfectly */
                .swal2-popup {
                    width: 95% !important;
                    max-width: 95% !important;
                    padding: 20px 15px !important;
                    margin: 10px auto !important;
                    box-sizing: border-box !important;
                }
                
                /* Reduce padding on the main view container to maximize screen space */
                .view-container {
                    padding: 10px !important;
                }
            }
        `;
        document.head.appendChild(mobileStyle);
    }

    // 2. THE TABLE AUTO-WRAPPER (MUTATION OBSERVER)
    const tableObserver = new MutationObserver(() => {
        // Find every table currently on the screen
        document.querySelectorAll('table').forEach(table => {
            // If the table isn't already wrapped, wrap it!
            if (!table.parentElement.classList.contains('mobile-table-wrapper') && !table.closest('.mobile-table-wrapper')) {
                let wrapper = document.createElement('div');
                wrapper.className = 'mobile-table-wrapper';
                
                // Move the table inside our smooth-scrolling wrapper
                table.parentNode.insertBefore(wrapper, table);
                wrapper.appendChild(table);
                
                // Force the table to stay wide so the user can swipe through it
                table.style.minWidth = "800px"; 
                table.style.width = "100%";
            }
        });
    });

    // Tell the observer to actively watch the whole app for changes
    tableObserver.observe(document.body, { childList: true, subtree: true });
});

// ========================================================
// 📦 MAIN OFFICE AI SUPPLIER PURCHASE ORDER ENGINE
// ========================================================
window.generateSupplierPurchaseOrders = async function() {
    Swal.fire({ 
        title: '🤖 AI Analyzing HQ Stock...', 
        text: 'Scanning Main Office inventory against Target Par Levels...', 
        allowOutsideClick: false, 
        didOpen: () => Swal.showLoading() 
    });

    try {
        // 1. Fetch strictly Main Office inventory
        const q = window.query(window.collection(window.db, "inventory"), window.where("branch", "==", "Main Office"));
        const invSnap = await window.getDocs(q);
        
        let supplierOrders = {};
        let itemsScanned = 0;

        invSnap.forEach(docSnap => {
            let item = docSnap.data();
            itemsScanned++;
            
            let conv = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;
            let currentStockBase = parseFloat(item.currentStock) || 0;
            let currentStockPurch = currentStockBase / conv;

            // 🧠 Priority 1: Target Par Levels (Maintaining Stock)
            let targetParBase = parseFloat(item.maintainingStock) || 0;
            let targetParPurch = targetParBase / conv;
            
            // Priority 2: Fallback to old HQ Low Stock Alert if Par Level isn't set
            let reorderLevelBase = parseFloat(item.reorderLevel) || parseFloat(item.lowStockAlert) || 0;
            let reorderLevelPurch = reorderLevelBase / conv;

            let deficitPurch = 0;
            let isCritical = false;

            if (targetParPurch > 0) {
                // Par Level Engine
                if (currentStockPurch < targetParPurch) {
                    deficitPurch = Math.ceil(targetParPurch - currentStockPurch);
                    isCritical = true;
                }
            } else if (reorderLevelPurch > 0) {
                // Standard Reorder Level Engine
                if (currentStockPurch <= reorderLevelPurch) {
                    let neededStock = (reorderLevelPurch * 2) - currentStockPurch;
                    deficitPurch = Math.ceil(neededStock > 0 ? neededStock : reorderLevelPurch);
                    isCritical = true;
                }
            }

            // If it triggered an alert, add it to the Supplier Cart!
            if (isCritical && deficitPurch > 0) {
                let supplier = item.supplier || "General Supplier";
                let purchUom = item.purchaseUom || item.purchUom || item.uom || 'units';
                let cost = parseFloat(item.purchaseCost) || parseFloat(item.purchCost) || parseFloat(item.cost) || 0;

                if (!supplierOrders[supplier]) supplierOrders[supplier] = [];

                supplierOrders[supplier].push({
                    itemName: item.name,
                    purchQty: deficitPurch,
                    purchUom: purchUom,
                    estCost: (deficitPurch * cost)
                });
            }
        });

        let html = '';
        let totalPOCost = 0;
        let totalItemsToOrder = 0;

        // 2. Build the Beautiful UI Grouped by Supplier
        for (let supplier in supplierOrders) {
            let items = supplierOrders[supplier];
            let supplierTotal = items.reduce((sum, i) => sum + i.estCost, 0);
            totalPOCost += supplierTotal;
            totalItemsToOrder += items.length;

            let itemListHtml = items.map(i => `
                <div style="display:flex; justify-content:space-between; font-size:13px; padding:10px 0; border-bottom:1px dashed #cbd5e1; align-items: center;">
                    <span style="color: #334155; font-weight: bold; font-size: 14px;">📦 ${i.itemName}</span>
                    <div style="text-align: right;">
                        <span style="color: #0ea5e9; font-weight: 900; font-size: 16px;">${i.purchQty} <span style="font-size: 11px; color: #64748b;">${i.purchUom}</span></span><br>
                        <span style="color: #dc2626; font-size: 12px; font-weight: bold;">₱${i.estCost.toLocaleString(undefined, {minimumFractionDigits: 2})}</span>
                    </div>
                </div>
            `).join('');

            html += `
                <div style="background:#f8fafc; border:1px solid #cbd5e1; border-radius:12px; padding:20px; margin-bottom:20px; text-align:left; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);">
                    <div style="display:flex; justify-content:space-between; border-bottom:2px solid #8b5cf6; padding-bottom:12px; margin-bottom:10px; align-items: center;">
                        <strong style="color:#6d28d9; font-size:16px; display: flex; align-items: center; gap: 8px;"><span>🚚</span> ${supplier}</strong>
                        <strong style="background: #fef2f2; color:#dc2626; border: 1px solid #fca5a5; padding: 6px 12px; border-radius: 8px; font-size:14px; box-shadow: 0 2px 4px rgba(220,38,38,0.1);">₱${supplierTotal.toLocaleString(undefined, {minimumFractionDigits: 2})}</strong>
                    </div>
                    ${itemListHtml}
                </div>
            `;
        }

        if (Object.keys(supplierOrders).length === 0) {
            return Swal.fire('Optimal Inventory', 'All Main Office inventory levels are currently optimal. No supplier reorders needed!', 'success');
        }

        Swal.fire({
            title: '<div style="display: flex; align-items: center; gap: 10px; color: #0f172a;"><span style="font-size: 28px;">🤖</span> AI Supplier Orders</div>',
            html: `
                <div style="text-align: left; font-size: 13px; color: #64748b; margin-bottom: 20px; background: #f1f5f9; padding: 10px; border-radius: 8px; border: 1px dashed #cbd5e1;">Scanned ${itemsScanned} items in Main Office. Found <b>${totalItemsToOrder} item(s)</b> below Target Par Levels.</div>
                <div style="max-height: 50vh; overflow-y: auto; padding-right: 5px;">${html}</div>
                <div style="background: #f0fdf4; border: 2px dashed #16a34a; padding: 20px; border-radius: 12px; font-size: 16px; font-weight: 900; color: #15803d; text-align: right; margin-top: 15px; display: flex; justify-content: space-between; align-items: center; box-shadow: 0 4px 6px rgba(22, 163, 74, 0.1);">
                    <span style="font-size: 12px; color: #166534; text-transform: uppercase;">Total Procurement Cost:</span>
                    <span style="font-size: 24px;">₱${totalPOCost.toLocaleString(undefined, {minimumFractionDigits: 2})}</span>
                </div>
            `,
            width: 700,
            showCancelButton: true,
            showConfirmButton: false, // Hide confirm since we don't have a direct PDF API linked to this specific modal yet
            cancelButtonText: 'Close Window',
            cancelButtonColor: '#64748b',
            customClass: { popup: 'rounded-2xl shadow-2xl' }
        });

    } catch(e) {
        console.error("PO Aggregator Error:", e);
        Swal.fire('Error', 'Failed to generate AI supplier orders. Check console.', 'error');
    }
};

