window.openStorefrontPreview = function() {
    let modal = document.getElementById('storefrontPreviewModal');
    let iframe = document.getElementById('storefrontIframe');
    
    // Check if the URL is saved in the browser memory
    let savedUrl = localStorage.getItem('takodeal_customer_app_url');
    
    // If not, ask the manager to paste it!
    if (!savedUrl) {
        savedUrl = prompt("Enter your Live Customer App URL (e.g. https://takodeal-customer.vercel.app):");
        if (savedUrl) {
            localStorage.setItem('takodeal_customer_app_url', savedUrl);
        } else {
            return; // Cancelled
        }
    }
    
    if (iframe.src !== savedUrl) {
        iframe.src = savedUrl;
    }
    
    modal.style.display = 'flex';
    window.togglePreviewDevice('mobile'); // Default to mobile view
};

// Also give them a way to reset the URL if they make a typo!
window.resetStorefrontUrl = function() {
    let newUrl = prompt("Update your Live Customer App URL:", localStorage.getItem('takodeal_customer_app_url'));
    if (newUrl) {
        localStorage.setItem('takodeal_customer_app_url', newUrl);
        document.getElementById('storefrontIframe').src = newUrl;
    }
};

window.togglePreviewDevice = function(deviceType) {
    let frame = document.getElementById('previewDeviceFrame');
    let btnMobile = document.getElementById('btnPreviewMobile');
    let btnDesktop = document.getElementById('btnPreviewDesktop');

    if (deviceType === 'mobile') {
        // Morph into an iPhone shape
        frame.style.width = '390px';
        frame.style.height = '844px';
        frame.style.borderRadius = '40px';
        frame.style.borderWidth = '14px';

        btnMobile.style.background = '#3b82f6';
        btnMobile.style.color = 'white';
        btnDesktop.style.background = 'transparent';
        btnDesktop.style.color = '#94a3b8';
    } else {
        // Morph into a Desktop Monitor shape
        frame.style.width = '100%';
        frame.style.height = '100%';
        frame.style.borderRadius = '8px';
        frame.style.borderWidth = '4px';

        btnDesktop.style.background = '#3b82f6';
        btnDesktop.style.color = 'white';
        btnMobile.style.background = 'transparent';
        btnMobile.style.color = '#94a3b8';
    }
};

// ========================================================
// ⚖️ YIELD COST CALCULATOR ENGINE (PURCHASE UOM MATH)
// ========================================================
window.yieldInventoryList = [];

window.loadYieldCalculator = async function() {
    let select = document.getElementById('yieldItemSelect');
    if (!select) return;
    
    select.innerHTML = '<option value="">⏳ Scanning inventory...</option>';
    
    try {
        const q = query(collection(db, "inventory"), where("branch", "==", "Main Office"));
        const snap = await getDocs(q);
        
        window.yieldInventoryList = [];
        let html = '<option value="">-- Select Raw Ingredient --</option>';
        
        snap.forEach(docSnap => {
            let data = docSnap.data();
            data.id = docSnap.id;
            window.yieldInventoryList.push(data);
        });
        
        window.yieldInventoryList.sort((a,b) => a.name.localeCompare(b.name)).forEach(item => {
            html += `<option value="${item.id}">${item.name} (Current Base Cost: ₱${parseFloat(item.baseCost || 0).toFixed(4)} / ${item.uom})</option>`;
        });
        
        select.innerHTML = html;
        window.loadYieldLogs();
    } catch(e) {
        console.error(e);
        select.innerHTML = '<option value="">❌ Error loading items</option>';
    }
};

window.handleYieldItemSelect = function() {
    let id = document.getElementById('yieldItemSelect').value;
    let item = window.yieldInventoryList.find(i => i.id === id);
    if (item) {
        let pUom = item.purchaseUom || item.purchUom || item.uom || 'units';
        let bUom = item.baseUom || item.uom || 'units';

        // 🔥 THE FIX: Inject the Purchase UOM exactly next to the input boxes!
        let rawUomEl = document.getElementById('yieldRawUom');
        let netUomEl = document.getElementById('yieldNetUom');
        if (rawUomEl) rawUomEl.innerText = pUom;
        if (netUomEl) netUomEl.innerText = pUom;

        document.getElementById('yieldResultCost').innerHTML = `₱0.00 <span style="font-size: 14px; font-weight: normal; color: #64748b;">/ ${bUom}</span>`;
        window.calcYieldMath();
    }
};

window.calcYieldMath = function() {
    let id = document.getElementById('yieldItemSelect').value;
    let item = window.yieldInventoryList.find(i => i.id === id);
    let bUom = item ? (item.baseUom || item.uom || 'unit') : 'unit';
    
    // Grab the true conversion rate from memory
    let conv = item ? (parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1) : 1;

    let totalCost = parseFloat(document.getElementById('yieldTotalCost').value) || 0;
    let netYieldPurch = parseFloat(document.getElementById('yieldNetQty').value) || 0;

    // 🔥 THE FIX: Multiply their Purchase UOM input by the Conversion Rate to get Total Grams/Base!
    let netYieldBase = netYieldPurch * conv; 

    if (netYieldBase > 0 && totalCost > 0) {
        let costPerBaseUnit = totalCost / netYieldBase;
        document.getElementById('yieldResultCost').innerHTML = `₱${costPerBaseUnit.toFixed(4)} <span style="font-size: 14px; font-weight: normal; color: #64748b;">/ ${bUom}</span>`;
    } else {
        document.getElementById('yieldResultCost').innerHTML = `₱0.00 <span style="font-size: 14px; font-weight: normal; color: #64748b;">/ ${bUom}</span>`;
    }
};

window.saveYieldCost = async function() {
    let id = document.getElementById('yieldItemSelect').value;
    let totalCost = parseFloat(document.getElementById('yieldTotalCost').value) || 0;
    
    // These inputs are now mathematically logged as Purchase UOM
    let rawQtyPurch = parseFloat(document.getElementById('yieldRawQty').value) || 0;
    let netYieldPurch = parseFloat(document.getElementById('yieldNetQty').value) || 0;
    
    if (!id || totalCost <= 0 || rawQtyPurch <= 0 || netYieldPurch <= 0) {
        return Swal.fire('Missing Data', 'Please fill out all fields with valid numbers.', 'warning');
    }

    let item = window.yieldInventoryList.find(i => i.id === id);
    let conv = parseFloat(item.conversionRate) || parseFloat(item.conversion) || 1;
    let bUom = item.baseUom || item.uom || 'units';
    let pUom = item.purchaseUom || item.purchUom || 'units';

    // 🔥 Calculate the True Base Cost!
    let netYieldBase = netYieldPurch * conv;
    let costPerBaseUnit = totalCost / netYieldBase;
    
    // Determine the True Purchase Cost as well to keep Inventory accurate
    let costPerPurchUnit = costPerBaseUnit * conv;

    let cashier = window.sessionUser ? window.sessionUser.cashierName : "Manager";

    try {
        Swal.fire({title: 'Updating Globally...', text: 'Recalculating BOMs for all branches...', allowOutsideClick: false, didOpen: () => Swal.showLoading()});
        
        // 1. Update this specific item in Main Office
        await updateDoc(doc(db, "inventory", id), {
            baseCost: costPerBaseUnit,
            purchaseCost: costPerPurchUnit,
            purchCost: costPerPurchUnit,
            cost: costPerPurchUnit
        });

        // 2. Cascade update to all OTHER branches for this item!
        const syncQ = query(collection(db, "inventory"), where("name", "==", item.name));
        const syncSnap = await getDocs(syncQ);
        let promises = [];
        syncSnap.forEach(d => {
            if (d.id !== id) promises.push(updateDoc(doc(db, "inventory", d.id), { 
                baseCost: costPerBaseUnit,
                purchaseCost: costPerPurchUnit,
                purchCost: costPerPurchUnit,
                cost: costPerPurchUnit 
            }));
        });
        await Promise.all(promises);

        // 3. Log the Yield Test with explicit UOM indicators
        await addDoc(collection(db, "yield_logs"), {
            itemName: item.name,
            totalCost: totalCost,
            rawQty: rawQtyPurch, 
            netYield: netYieldPurch, 
            newBaseCost: costPerBaseUnit,
            purchUom: pUom, 
            baseUom: bUom,
            loggedBy: cashier,
            timestamp: serverTimestamp()
        });

        Swal.fire({
            title: '✅ Yield Applied!', 
            text: `The base cost for ${item.name} is now ₱${costPerBaseUnit.toFixed(4)}/${bUom}. All recipes using this ingredient will automatically recalculate.`, 
            icon: 'success',
            customClass: { popup: 'rounded-2xl' }
        });
        
        // Reset inputs
        document.getElementById('yieldTotalCost').value = '';
        document.getElementById('yieldRawQty').value = '';
        document.getElementById('yieldNetQty').value = '';
        document.getElementById('yieldResultCost').innerHTML = `₱0.00 <span style="font-size: 14px; font-weight: normal; color: #64748b;">/ ${bUom}</span>`;
        
        window.loadYieldLogs();
        
    } catch(e) {
        console.error(e);
        Swal.fire('Error', 'Failed to update yield cost.', 'error');
    }
};

window.loadYieldLogs = async function() {
    let tbody = document.getElementById('yieldLogsBody');
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="6" class="text-center">Loading logs...</td></tr>';
    
    try {
        const q = query(collection(db, "yield_logs"), orderBy("timestamp", "desc"), limit(50));
        const snap = await getDocs(q);
        
        let html = '';
        snap.forEach(docSnap => {
            let d = docSnap.data();
            let dateStr = d.timestamp ? d.timestamp.toDate().toLocaleString('en-PH', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'Unknown';
            let wastePct = (((d.rawQty - d.netYield) / d.rawQty) * 100).toFixed(1);
            
            // Use the saved UOMs so the history looks perfect
            let pUomDisp = d.purchUom || 'units';
            let bUomDisp = d.baseUom || 'units';

            html += `
                <tr style="border-bottom: 1px solid #f1f5f9; background: white;">
                    <td style="padding: 15px; color: #64748b; font-size: 12px;">${dateStr}</td>
                    <td style="padding: 15px; font-weight: bold; color: #0f172a; font-size: 15px;">${d.itemName}</td>
                    <td style="padding: 15px;">
                        <div style="font-size: 14px; font-weight: bold; color: #dc2626;">Cost: ₱${d.totalCost.toLocaleString(undefined, {minimumFractionDigits: 2})}</div>
                        <div style="font-size: 12px; color: #64748b; margin-top: 4px;">Raw: ${d.rawQty} ${pUomDisp}</div>
                    </td>
                    <td style="padding: 15px; font-weight: bold; color: #16a34a; font-size: 15px;">
                        ${d.netYield} ${pUomDisp} <br>
                        <span style="font-size: 11px; color: #ef4444; font-weight: normal;">(Waste: ${wastePct}%)</span>
                    </td>
                    <td style="padding: 15px; font-weight: 900; color: #0ea5e9; font-size: 16px;">₱${d.newBaseCost.toFixed(4)} <span style="font-size:11px; font-weight:normal; color:#64748b;">/${bUomDisp}</span></td>
                    <td style="padding: 15px; color: #475569; font-size: 13px;">👤 ${d.loggedBy}</td>
                </tr>
            `;
        });
        
        tbody.innerHTML = html || '<tr><td colspan="6" class="text-center" style="padding: 30px; color: #64748b;">No yield calculations logged yet.</td></tr>';
        
    } catch(e) {
        console.error(e);
        tbody.innerHTML = '<tr><td colspan="6" class="text-center" style="color: red;">Error loading logs.</td></tr>';
    }
};

// ========================================================
// 🗑️ MANAGER DIRECT WASTE LOGGING ENGINE
// ========================================================
window.mgrWasteCart = [];
window.mgrWasteInventoryList = [];

window.openManagerWasteModal = async function() {
    document.getElementById('managerWasteModal').style.display = 'flex';
    
    // 1. Populate the Branch Dropdown
    let branchSelect = document.getElementById('mgrWasteBranch');
    let options = '';
    window.globalActiveBranches.forEach(b => {
        options += `<option value="${b}">📍 ${b}</option>`;
    });
    branchSelect.innerHTML = options;
    
    // Auto-select the branch they are currently viewing in the tab!
    if (window.activeWasteBranch && window.activeWasteBranch !== 'All') {
        branchSelect.value = window.activeWasteBranch;
    } else if (window.sessionUser && window.sessionUser.isFranchisee) {
        branchSelect.value = window.sessionUser.branch;
    }
    
    // Lock branch if Franchisee
    if (window.sessionUser && window.sessionUser.isFranchisee) {
        branchSelect.disabled = true;
    }

    // 2. Reset the modal UI
    window.mgrWasteCart = [];
    window.renderMgrWasteCart();
    document.getElementById('mgrWastePhoto').value = '';
    document.getElementById('mgrWasteQty').value = '';
    document.getElementById('mgrWasteItem').value = '';
    
    // 3. Load the specific branch inventory
    await window.loadManagerWasteInventory();
};

window.loadManagerWasteInventory = async function() {
    let branch = document.getElementById('mgrWasteBranch').value;
    let itemInput = document.getElementById('mgrWasteItem');
    let datalist = document.getElementById('mgrWasteDatalist');
    
    itemInput.value = '';
    itemInput.placeholder = '⏳ Fetching stock...';
    itemInput.disabled = true;
    
    try {
        const q = query(collection(db, "inventory"), where("branch", "==", branch));
        const snap = await getDocs(q);
        
        window.mgrWasteInventoryList = [];
        let html = '';
        
        snap.forEach(docSnap => {
            let data = docSnap.data();
            data.id = docSnap.id;
            window.mgrWasteInventoryList.push(data);
        });
        
        window.mgrWasteInventoryList.sort((a,b) => (a.name||'').localeCompare(b.name||''));
        
        window.mgrWasteInventoryList.forEach(item => {
            html += `<option value="${item.name}">Live Stock: ${parseFloat(item.currentStock||0).toFixed(1)} ${item.uom}</option>`;
        });
        
        datalist.innerHTML = html;
        itemInput.placeholder = 'Type to search item...';
        itemInput.disabled = false;
    } catch(e) {
        console.error("Manager Waste Inventory Error:", e);
        itemInput.placeholder = '❌ Error loading stock';
    }
};

window.updateMgrWasteUom = function() {
    let itemName = document.getElementById('mgrWasteItem').value.trim();
    let uomDrop = document.getElementById('mgrWasteUom');
    
    if (!itemName) {
        uomDrop.innerHTML = '<option value="base" data-conv="1">Units</option>';
        return;
    }
    
    let invItem = window.mgrWasteInventoryList.find(i => i.name === itemName);
    if (invItem) {
        let bUom = invItem.baseUom || invItem.uom || 'units';
        let pUom = invItem.purchaseUom || invItem.purchUom || 'Bulk';
        let conv = parseFloat(invItem.conversionRate) || parseFloat(invItem.conversion) || 1;
        
        if (bUom.toLowerCase() !== pUom.toLowerCase() && conv !== 1) {
            uomDrop.innerHTML = `
                <option value="purch" data-conv="${conv}">${pUom}</option>
                <option value="base" data-conv="1" selected>${bUom}</option>
            `;
        } else {
            uomDrop.innerHTML = `<option value="base" data-conv="1" selected>${bUom}</option>`;
        }
    }
};

window.addMgrWasteToCart = function() {
    let itemName = document.getElementById('mgrWasteItem').value.trim();
    let rawQty = parseFloat(document.getElementById('mgrWasteQty').value);
    let reason = document.getElementById('mgrWasteReason').value;
    let branch = document.getElementById('mgrWasteBranch').value;
    
    if (!itemName || isNaN(rawQty) || rawQty <= 0) {
        return Swal.fire('Error', 'Please select an item and enter a valid quantity.', 'error');
    }
    
    let invItem = window.mgrWasteInventoryList.find(i => i.name === itemName);
    if (!invItem) return Swal.fire('Error', 'Item not found in inventory.', 'error');
    
    let uomDrop = document.getElementById('mgrWasteUom');
    let convRate = 1;
    let displayUom = invItem.baseUom || invItem.uom || 'units';
    
    if (uomDrop && uomDrop.tagName === 'SELECT') {
        let selOpt = uomDrop.options[uomDrop.selectedIndex];
        convRate = parseFloat(selOpt.getAttribute('data-conv')) || 1;
        displayUom = selOpt.text;
    }
    
    let baseQty = rawQty * convRate;
    let costPerUnit = parseFloat(invItem.baseCost) || parseFloat(invItem.cost) || 0;
    let valueLost = baseQty * costPerUnit;
    
    let photoInput = document.getElementById('mgrWastePhoto');
    let photoFile = photoInput.files.length > 0 ? photoInput.files[0] : null;

    window.mgrWasteCart.push({
        id: invItem.id,
        name: itemName,
        branch: branch,
        rawQty: rawQty,
        displayUom: displayUom,
        baseQty: baseQty,
        baseUom: invItem.baseUom || invItem.uom || 'units',
        reason: reason,
        valueLost: valueLost,
        file: photoFile
    });
    
    document.getElementById('mgrWasteItem').value = '';
    document.getElementById('mgrWasteQty').value = '';
    document.getElementById('mgrWastePhoto').value = '';
    if(uomDrop) uomDrop.innerHTML = '<option value="base" data-conv="1">Units</option>';
    
    window.renderMgrWasteCart();
};

window.removeMgrWasteItem = function(index) {
    window.mgrWasteCart.splice(index, 1);
    window.renderMgrWasteCart();
};

window.renderMgrWasteCart = function() {
    let tbody = document.getElementById('mgrWasteCartBody');
    if (!tbody) return;
    
    if (window.mgrWasteCart.length === 0) {
        tbody.innerHTML = '<tr><td colspan="3" class="text-center" style="padding: 15px; color: #94a3b8;">Cart is empty.</td></tr>';
        return;
    }
    
    let html = '';
    window.mgrWasteCart.forEach((item, idx) => {
        let photoBadge = item.file ? `<span style="color:#16a34a; font-size:10px; margin-left:5px; font-weight:bold;">(📸 Photo Attached)</span>` : '';
        html += `
            <tr style="border-bottom: 1px solid #e2e8f0; background: white;">
                <td style="padding: 12px 10px;">
                    <strong style="color: #0f172a; font-size: 13px;">${item.name}</strong> ${photoBadge}<br>
                    <span style="font-size: 11px; color: #dc2626; font-style: italic;">Reason: ${item.reason}</span>
                </td>
                <td style="padding: 12px 10px; text-align: center;">
                    <strong style="color: #dc2626; font-size: 14px;">${item.rawQty} ${item.displayUom}</strong><br>
                    <span style="font-size: 10px; color: #64748b; font-weight: bold;">(Loss: ₱${item.valueLost.toFixed(2)})</span>
                </td>
                <td style="padding: 12px 10px; text-align: right;">
                    <button onclick="window.removeMgrWasteItem(${idx})" style="background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; border-radius: 6px; padding: 6px 12px; cursor: pointer; font-weight: bold; font-size: 12px; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">✖</button>
                </td>
            </tr>
        `;
    });
    tbody.innerHTML = html;
};

window.submitMgrWasteCart = async function() {
    if (window.mgrWasteCart.length === 0) return Swal.fire('Cart Empty', 'Please add items to log.', 'warning');
    
    let btn = document.getElementById('btnSubmitMgrWaste');
    let origText = btn.innerText;
    btn.innerText = "⏳ Deducting Inventory..."; btn.disabled = true;
    
    let cashierName = window.sessionUser ? window.sessionUser.cashierName : 'Manager HQ';

    try {
        for (let item of window.mgrWasteCart) {
            let photoUrl = "";
            
            // 1. Upload photo to Firebase Storage if attached
            if (item.file) {
                const fileExt = item.file.name.split('.').pop();
                const fileName = `waste_proofs/${item.branch}_${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
                const storageRef = ref(window.storage, fileName);
                const snapshot = await uploadBytes(storageRef, item.file);
                photoUrl = await getDownloadURL(snapshot.ref);
            }
            
            // 2. Fetch live inventory directly to prevent race conditions
            const invRef = doc(db, "inventory", item.id);
            const invSnap = await getDoc(invRef);
            
            if (invSnap.exists()) {
                let currentStock = parseFloat(invSnap.data().currentStock) || 0;
                let newStock = currentStock - item.baseQty;
                
                // 3. Mathematical Deduction
                await updateDoc(invRef, { currentStock: newStock });
                
                // 4. Log the Ledger Trace
                await addDoc(collection(db, "stock_logs"), {
                    branch: item.branch,
                    item: item.name,
                    uom: item.baseUom,
                    oldQty: currentStock,
                    newQty: newStock,
                    variance: -item.baseQty,
                    type: "Waste / Spoilage",
                    note: `Manager Log: ${item.reason}`,
                    user: cashierName,
                    timestamp: serverTimestamp(),
                    photoUrl: photoUrl
                });
            }
        }
        
        Swal.fire({
            title: '✅ Waste Logged', 
            text: 'Inventory has been successfully updated and deducted.', 
            icon: 'success',
            customClass: { popup: 'rounded-2xl' }
        });
        
        document.getElementById('managerWasteModal').style.display = 'none';
        window.mgrWasteCart = [];
        window.renderMgrWasteCart();
        
        // Refresh the underlying table and boxes automatically
        if (typeof window.loadWasteTabLogs === 'function') window.loadWasteTabLogs();
        if (typeof window.loadInventoryData === 'function') window.loadInventoryData();
        
    } catch(e) {
        console.error("Manager Waste Submit Error:", e);
        Swal.fire('Error', 'Failed to log waste. Check internet connection.', 'error');
    } finally {
        btn.innerText = origText; btn.disabled = false;
    }
};

